-- مكتبة السياسات (ترحيل 110). النص مستخرج من لائحة تنظيم العمل المعتمدة رقم 351743 بتاريخ 24 أبريل 2025.
-- ملف PDF الموقّع لم يصل هذه الجلسة؛ كل مادة هنا موسومة «مستخرج — يحتاج مطابقة مع الأصل الموقّع» حتى يعتمدها الأدمن بعد المطابقة.
-- الجداول الثلاثة للمخالفات والجزاءات (50 صفًا) لا تُنسخ هنا: مصدرها الوحيد جدول وحدة الجزاءات (ترحيل 097)،
-- وهذا الترحيل يربط كل صف بمادته فقط.
-- لا طباعة ولا تصدير PDF في هذه الوحدة: السجل إلكتروني ورابط المادة هو ما يُنسخ ويُشارك.

CREATE TABLE policy_documents (
  id TEXT PRIMARY KEY,
  tenant_id TEXT REFERENCES tenants(id),
  code TEXT NOT NULL,
  title TEXT NOT NULL CHECK(length(trim(title))>=3),
  reference_no TEXT,
  approved_on TEXT,
  effective_from TEXT,
  status TEXT NOT NULL CHECK(status IN ('draft','published','superseded')),
  source_note TEXT NOT NULL CHECK(length(trim(source_note))>=10),
  verification TEXT NOT NULL CHECK(verification IN ('extracted','verified')),
  verified_by TEXT REFERENCES users(id),
  verified_at TEXT,
  version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL
) STRICT;
CREATE INDEX policy_documents_code ON policy_documents(code,tenant_id);
CREATE TRIGGER policy_documents_no_delete BEFORE DELETE ON policy_documents BEGIN SELECT RAISE(ABORT,'policy documents are retained'); END;

CREATE TABLE policy_articles (
  id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL REFERENCES policy_documents(id),
  tenant_id TEXT REFERENCES tenants(id),
  chapter TEXT NOT NULL,
  chapter_order INTEGER NOT NULL,
  number INTEGER NOT NULL CHECK(number>0),
  title TEXT NOT NULL CHECK(length(trim(title))>=2),
  title_source TEXT NOT NULL CHECK(title_source IN ('extracted','proposed','approved')),
  body TEXT NOT NULL CHECK(length(trim(body))>=2),
  paragraphs TEXT NOT NULL CHECK(json_valid(paragraphs)),
  keywords TEXT NOT NULL CHECK(json_valid(keywords)),
  artifacts TEXT NOT NULL CHECK(json_valid(artifacts)),
  effective_from TEXT,
  status TEXT NOT NULL CHECK(status IN ('in_force','amended','repealed','replaced')),
  verification TEXT NOT NULL CHECK(verification IN ('extracted','verified')),
  revision INTEGER NOT NULL DEFAULT 1,
  version INTEGER NOT NULL DEFAULT 1,
  updated_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(document_id,number)
) STRICT;
CREATE INDEX policy_articles_number ON policy_articles(number,status);
CREATE INDEX policy_articles_chapter ON policy_articles(chapter_order,number);
CREATE TRIGGER policy_articles_no_delete BEFORE DELETE ON policy_articles BEGIN SELECT RAISE(ABORT,'articles are replaced by a new dated version, never deleted'); END;
-- كل تعديل يرفع الرقمين معًا: version لمنع الكتابة المتزامنة، revision لأن كل تعديل نسخة لها تاريخ سريان.
CREATE TRIGGER policy_articles_versioned BEFORE UPDATE ON policy_articles
WHEN NEW.version<>OLD.version+1 OR NEW.number<>OLD.number OR NEW.document_id<>OLD.document_id
BEGIN SELECT RAISE(ABORT,'an article edit increments version and keeps its number and document'); END;

-- النسخة السابقة تبقى كما كانت: المقارنة تحتاج نصًا لا يتغير خلفها.
CREATE TABLE policy_article_versions (
  id TEXT PRIMARY KEY,
  article_id TEXT NOT NULL REFERENCES policy_articles(id),
  tenant_id TEXT REFERENCES tenants(id),
  revision INTEGER NOT NULL CHECK(revision>0),
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  paragraphs TEXT NOT NULL CHECK(json_valid(paragraphs)),
  status TEXT NOT NULL,
  effective_from TEXT,
  note TEXT NOT NULL DEFAULT '',
  edited_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  UNIQUE(article_id,revision)
) STRICT;
CREATE TRIGGER policy_article_versions_fixed BEFORE UPDATE ON policy_article_versions BEGIN SELECT RAISE(ABORT,'a kept version is never rewritten'); END;
CREATE TRIGGER policy_article_versions_no_delete BEFORE DELETE ON policy_article_versions BEGIN SELECT RAISE(ABORT,'versions are retained'); END;

-- الإحالات: داخلية (رابط) أو خارجية (نظام العمل — تُعرض «مرجع خارجي» ولا تُفتح).
CREATE TABLE policy_article_links (
  id TEXT PRIMARY KEY,
  article_id TEXT NOT NULL REFERENCES policy_articles(id),
  kind TEXT NOT NULL CHECK(kind IN ('reference','amends','amended_by','replaces','replaced_by','external','related')),
  target_article_id TEXT REFERENCES policy_articles(id),
  target_number INTEGER,
  target_label TEXT NOT NULL DEFAULT '',
  phrase TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  CHECK(kind='external' OR target_article_id IS NOT NULL)
) STRICT;
CREATE INDEX policy_article_links_article ON policy_article_links(article_id,kind);
CREATE INDEX policy_article_links_target ON policy_article_links(target_article_id);

-- قاموس المرادفات: ما يكتبه الموظف مقابل ما كتبته اللائحة. يحرره الأدمن، والصفوف بلا tenant_id بذرة المنصة.
CREATE TABLE policy_synonyms (
  id TEXT PRIMARY KEY,
  tenant_id TEXT REFERENCES tenants(id),
  head TEXT NOT NULL CHECK(length(trim(head))>=2),
  term TEXT NOT NULL CHECK(length(trim(term))>=2),
  active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  UNIQUE(tenant_id,head,term)
) STRICT;

CREATE TABLE policy_favourites (
  tenant_id TEXT NOT NULL REFERENCES tenants(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  article_id TEXT NOT NULL REFERENCES policy_articles(id),
  created_at TEXT NOT NULL,
  PRIMARY KEY(user_id,article_id)
) STRICT;

-- التحليلات: أكثر ما يُبحث، وما لا يجد نصًا، وأكثر ما يُفتح. الاستعلام يُحفظ بلا ربطه بقرار عن صاحبه.
CREATE TABLE policy_searches (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id),
  user_id TEXT REFERENCES users(id),
  query TEXT NOT NULL,
  normalized TEXT NOT NULL,
  results INTEGER NOT NULL,
  created_at TEXT NOT NULL
) STRICT;
CREATE INDEX policy_searches_term ON policy_searches(tenant_id,normalized);
CREATE TABLE policy_article_views (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id),
  article_id TEXT NOT NULL REFERENCES policy_articles(id),
  user_id TEXT REFERENCES users(id),
  created_at TEXT NOT NULL
) STRICT;
CREATE INDEX policy_article_views_article ON policy_article_views(article_id);

-- صف الجدول ← مادته. الصفوف نفسها تبقى في discipline_schedules (097): مصدر واحد للجداول الثلاثة.
CREATE TABLE policy_table_rows (
  row_code TEXT PRIMARY KEY,
  table_key TEXT NOT NULL,
  table_name TEXT NOT NULL,
  article_number INTEGER NOT NULL
) STRICT;

-- «قرأت واطلعت»: إقرار الموظف على اللائحة وعلى كل تحديث. مربوط بنسخة المادة أو الوثيقة وببصمة نصها، فنسخة
-- جديدة تعني إقرارًا جديدًا والإقرار القديم يبقى مرتبطًا بنسخته — القاعدة نفسها المكتوبة في وحدة إقرار السياسات.
-- وحدة إقرار السياسات (ترحيل 075) تربط جولاتها بجدول hr_policies، فلا تستقبل وثيقة مكتبة؛ المكتبة تعرض جولاتها
-- المعلّقة للموظف في مكان واحد وتسجل إقرار القراءة هنا. توحيد المحرّكين قرار مفتوح في وثيقة التسليم.
CREATE TABLE policy_reading_acknowledgements (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  document_id TEXT NOT NULL REFERENCES policy_documents(id),
  article_id TEXT REFERENCES policy_articles(id),
  revision INTEGER NOT NULL CHECK(revision>0),
  content_digest TEXT NOT NULL CHECK(length(content_digest)=64),
  acknowledged_at TEXT NOT NULL
) STRICT;
CREATE UNIQUE INDEX policy_reading_ack_once ON policy_reading_acknowledgements(user_id,document_id,COALESCE(article_id,''),revision);
CREATE TRIGGER policy_reading_ack_fixed BEFORE UPDATE ON policy_reading_acknowledgements BEGIN SELECT RAISE(ABORT,'an acknowledgement records what was read and when; it is never rewritten'); END;
CREATE TRIGGER policy_reading_ack_no_delete BEFORE DELETE ON policy_reading_acknowledgements BEGIN SELECT RAISE(ABORT,'acknowledgements are retained'); END;

-- «الأساس النظامي» تحت كل نموذج، والمادة التي منعت كل رفض آلي. مفتاح واحد تقرأه الوحدات ولا تكرر الرقم في كودها.
CREATE TABLE policy_request_basis (
  key TEXT PRIMARY KEY,
  label TEXT NOT NULL,
  article_number INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('form','refusal'))
) STRICT;


-- ── الوثائق ──────────────────────────────────────────────────────────────────
INSERT INTO policy_documents(id,tenant_id,code,title,reference_no,approved_on,effective_from,status,source_note,verification,version,created_at) VALUES
('policy-doc-work-regulation',NULL,'work_regulation','لائحة تنظيم العمل','351743','2025-04-24','2025-04-25','published','مستخرج — يحتاج مطابقة مع الأصل الموقّع — استُخرج النص من PDF بترتيب كلمات معكوس وحروف مفصولة في مواضع؛ أُصلح آليًا ولم تصل نسخة PDF الموقّعة إلى جلسة البناء.','extracted',1,'2026-09-20T00:00:00.000Z'),
('policy-doc-secondment-circular',NULL,'secondment_circular','تعميم الانتداب المعدِّل للمادتين 41 و65','—',NULL,NULL,'draft','مستخرج — يحتاج مطابقة مع الأصل الموقّع — نص التعميم لم يصل هذه الجلسة: الوثيقة مسجلة بحقولها ليربط بها الأدمن النص عند رفعه، والمادتان 41 و65 موسومتان «معدّلة» بناءً على ما أفاد به المالك.','extracted',1,'2026-09-20T00:00:00.000Z'),
('policy-doc-benefits-policy',NULL,'benefits_policy','سياسة المزايا الجديدة','—',NULL,NULL,'draft','مستخرج — يحتاج مطابقة مع الأصل الموقّع — نص سياسة المزايا لم يصل هذه الجلسة: الوثيقة مسجلة ليربط بها الأدمن النص عند رفعه.','extracted',1,'2026-09-20T00:00:00.000Z');

-- ── المواد 1–127 ─────────────────────────────────────────────────────────────
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-001','policy-doc-work-regulation',NULL,'أحكام عامة',1,1,'يقصد بلفظ المنشأة أينما ورد في هذه اللائحة شركة','proposed','يقصد بلفظ المنشأة أينما ورد في هذه اللائحة شركة: ثلاثمائة وستون درجة للدعاية والاعلان يقصد بلفظ العامل أينما ورد في هذه اللائحة كل: شخص طبيعي ذكراً- أو أنثى يعمل- لمصلحة هذه المنشأة وتحت إدارتها، أو إشرافها مقابل أجر، ولو كان بعيداً عن نظارتها.','[{"index":1,"marker":null,"text":"يقصد بلفظ المنشأة أينما ورد في هذه اللائحة شركة: ثلاثمائة وستون درجة للدعاية والاعلان يقصد بلفظ العامل أينما ورد في هذه اللائحة كل: شخص طبيعي ذكراً- أو أنثى يعمل- لمصلحة هذه المنشأة وتحت إدارتها، أو إشرافها مقابل أجر، ولو كان بعيداً عن نظارتها."}]','["بلفظ","اينما","يقصد","ورد","شرك","لايح","ثلاثما","وست","دعا","ذكرا"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-002','policy-doc-work-regulation',NULL,'أحكام عامة',1,2,'التقويم المعمول به في المنشأة هو الميلادي','proposed','التقويم المعمول به في المنشأة هو الميلادي.','[{"index":1,"marker":null,"text":"التقويم المعمول به في المنشأة هو الميلادي."}]','["معمول","تقويم","ميلاد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-003','policy-doc-work-regulation',NULL,'أحكام عامة',1,3,'تسري أحكام هذه اللائحة على جميع العاملين بالمنشأة','proposed','1. تسري أحكام هذه اللائحة على جميع العاملين بالمنشأة، والفروع التابعة لها.
2. لا تخل أحكام هذه اللائحة بالحقوق المكتسبة للعمال وتعتبر، هذه اللائحة مكملة لعقود العمل فيما لا يتعارض مع هذه الحقوق.
3. تُطلعِ المنشأة العامل على هذه اللائحة عند التعاقد وتنص، على ذلك في عقد العمل.','[{"index":1,"marker":"1","text":"تسري أحكام هذه اللائحة على جميع العاملين بالمنشأة، والفروع التابعة لها."},{"index":2,"marker":"2","text":"لا تخل أحكام هذه اللائحة بالحقوق المكتسبة للعمال وتعتبر، هذه اللائحة مكملة لعقود العمل فيما لا يتعارض مع هذه الحقوق."},{"index":3,"marker":"3","text":"تُطلعِ المنشأة العامل على هذه اللائحة عند التعاقد وتنص، على ذلك في عقد العمل."}]','["تسر","لايح","احكام","جميع","حقوق","تخل","لعقود","تطلع","وتنص","فروع"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-004','policy-doc-work-regulation',NULL,'أحكام عامة',1,4,'يجوز للمنشأة إصدار قرارات وسياسات','proposed','1. يجوز للمنشأة إصدار قرارات وسياسات، خاصة بها يُعطى بموجبها العمال حقوقًا أفضل مما هو وارد في هذه اللائحة.
2. للمنشأة الحق في تضمين هذه اللائحة شروطاً، وأحكامًا إضافية بما لا ينتقص من حقوق العمال المكتسبة بموجب نظام العمل ولائحته، التنفيذية والقرارات، الصادرة تنفيذًا له؛ ولا تكون هذه الإضافات أو التعديلات نافذة إلا بعد اعتمادها من وزارة الموارد البشرية والتنمية الاجتماعية.
3. كل نص يتم إضافته إلى هذه اللائحة يتعارض مع أحكام نظام العمل ولائحته، التنفيذية والقرارات، الصادرة تنفيذاً له؛ يعتبر باطلاُ ولا يعتد به.','[{"index":1,"marker":"1","text":"يجوز للمنشأة إصدار قرارات وسياسات، خاصة بها يُعطى بموجبها العمال حقوقًا أفضل مما هو وارد في هذه اللائحة."},{"index":2,"marker":"2","text":"للمنشأة الحق في تضمين هذه اللائحة شروطاً، وأحكامًا إضافية بما لا ينتقص من حقوق العمال المكتسبة بموجب نظام العمل ولائحته، التنفيذية والقرارات، الصادرة تنفيذًا له؛ ولا تكون هذه الإضافات أو التعديلات نافذة إلا بعد اعتمادها من وزارة الموارد البشرية والتنمية الاجتماعية."},{"index":3,"marker":"3","text":"كل نص يتم إضافته إلى هذه اللائحة يتعارض مع أحكام نظام العمل ولائحته، التنفيذية والقرارات، الصادرة تنفيذاً له؛ يعتبر باطلاُ ولا يعتد به."}]','["وسياس","قرار","اصدار","تنفيذا","اضاف","ولايح","لايح","صادر","حقوقا","افضل"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-005','policy-doc-work-regulation',NULL,'أحكام عامة',1,5,'ض ا ما م ليقت ما لك هنم ذه','proposed','ض ا ما م ليقت ما لك هنم ذه اللائحة المعاني الموضحة أم ا وردت في ه ة منيأ ارات والألفاظ التالي د بعلاب يقص ياق النص خلاف كذل: س المجلس مجلس إدارة المنشأة. الرئيس التنفيذي الرئيس التنفيذي للمنشأة. مصفوفة صلاحيات المنشأة المعتمدة من مجلس مصفوفة الصلاحيات: الادارة اللائحة يقصد بها لائحة تنظيم العمل للمنشأة. الرئيس التنفيذي أو أي شخص آخر مخوّل بممارسة صاحب الصلاحية: صلاحيات محددة وفق مصفوفة الصلاحيات المعتمدة من مجلس الادارة، أو أي صلاحيات مشار إليها في أدلة وإجراءات العمل المعتمدة. كل شخص يتقدم لشغل إحدى وظائف المنشأة المرشح نظام العمل الصادر بالمرسوم الملكي (رقم )51/م نظام العمل وما يطرأ عليه من خيراتو، 23/08/1426 ه تعديلات كل ما يعطى للعامل مقابل عمله بموجب، عقد الأجر الأساسي عمل مكتوب أو غير مكتوب مهما، كان نوع الأجر أو طريقة أدائه مضافًا، إليه العلاوات الدورية. الأجر الأساسي مضافًا إليه جميع الزيادات الأخرى الأجر الفعلي المستحقة للعامل سواء، كانت مقابل الجهد الذي يبذله في العمل أو المخاطر التي يتعرض لها أثناء أداء عمله، أو تلك التي تُمنح للعامل بموجب عقد العمل أو لائحة تنظيم العمل. الأجر الأجر الفعلي مبلغ يدفع للعامل شهريًا أو سنويًا حسب ما يتم بدل السكن الاتفاق عليه في عقد العمل لمساعدته، على تحمل أعباء السكن. بدل النقل مبلغ يدفع للعامل مقابل انتقاله من المنشأة وإليه. مجموعة المهام والواجبات والمسؤوليات المسندة الوظيفة إلى العامل. السنة السنة الميلادية الشهر الميلادي ولغرض، احتساب الحقوق المالية الشهر يعتبر (الشهر 30 ثلاثين) يومًا. السلطة المختصة السلطة المفوضة باتخاذ القرار. مدير الإدارة المدير الذي يرتبط به العامل إداريًا. وثيقة تبين مجموعة الشروط والأحكام التي تنظم عقد العمل العلاقة بين العامل والمنشأة أو الشركات التابعة له وتتضمن، العمل الذي تراضى عليها الطرفان، وأية بيانات ضرورية أخرى. الوحدة التنظيمية المعنية بشؤون العاملين في إدارة الموارد البشرية المنشأة، أو الشركات التابعة لها. هي الفترة التي يقضيها العامل في العمل لدى الخدمة المنشأة بموجب عقد عمل وبشكل مستمر من تاريخ التحاقه به وإلى، انتهاء خدمته فيه. خدمات طبية تُؤمّن للعاملين وأسرهم وفق، ما هو الرعاية الطبية منصوص في نظام الضمان الصحي التعاوني. هو تكليف للعامل بالسفر من أجل إتمام مهمة الانتداب عمل محددة وذلك وفق الأحكام التي تبينها اللائحة. زوج العامل والأبناء غير المتزوجين والبنات غير أسرة العامل المتزوجات. مكافأة نهاية الخدمة مكافأة تدفع للعامل عند نهاية خدمته في المنشأة. ساعات العمل التي يقضيها العامل في العمل دون ساعات العمل احتساب فترات الراحة.','[{"index":1,"marker":null,"text":"ض ا ما م ليقت ما لك هنم ذه اللائحة المعاني الموضحة أم ا وردت في ه ة منيأ ارات والألفاظ التالي د بعلاب يقص ياق النص خلاف كذل: س المجلس مجلس إدارة المنشأة. الرئيس التنفيذي الرئيس التنفيذي للمنشأة. مصفوفة صلاحيات المنشأة المعتمدة من مجلس مصفوفة الصلاحيات: الادارة اللائحة يقصد بها لائحة تنظيم العمل للمنشأة. الرئيس التنفيذي أو أي شخص آخر مخوّل بممارسة صاحب الصلاحية: صلاحيات محددة وفق مصفوفة الصلاحيات المعتمدة من مجلس الادارة، أو أي صلاحيات مشار إليها في أدلة وإجراءات العمل المعتمدة. كل شخص يتقدم لشغل إحدى وظائف المنشأة المرشح نظام العمل الصادر بالمرسوم الملكي (رقم )51/م نظام العمل وما يطرأ عليه من خيراتو، 23/08/1426 ه تعديلات كل ما يعطى للعامل مقابل عمله بموجب، عقد الأجر الأساسي عمل مكتوب أو غير مكتوب مهما، كان نوع الأجر أو طريقة أدائه مضافًا، إليه العلاوات الدورية. الأجر الأساسي مضافًا إليه جميع الزيادات الأخرى الأجر الفعلي المستحقة للعامل سواء، كانت مقابل الجهد الذي يبذله في العمل أو المخاطر التي يتعرض لها أثناء أداء عمله، أو تلك التي تُمنح للعامل بموجب عقد العمل أو لائحة تنظيم العمل. الأجر الأجر الفعلي مبلغ يدفع للعامل شهريًا أو سنويًا حسب ما يتم بدل السكن الاتفاق عليه في عقد العمل لمساعدته، على تحمل أعباء السكن. بدل النقل مبلغ يدفع للعامل مقابل انتقاله من المنشأة وإليه. مجموعة المهام والواجبات والمسؤوليات المسندة الوظيفة إلى العامل. السنة السنة الميلادية الشهر الميلادي ولغرض، احتساب الحقوق المالية الشهر يعتبر (الشهر 30 ثلاثين) يومًا. السلطة المختصة السلطة المفوضة باتخاذ القرار. مدير الإدارة المدير الذي يرتبط به العامل إداريًا. وثيقة تبين مجموعة الشروط والأحكام التي تنظم عقد العمل العلاقة بين العامل والمنشأة أو الشركات التابعة له وتتضمن، العمل الذي تراضى عليها الطرفان، وأية بيانات ضرورية أخرى. الوحدة التنظيمية المعنية بشؤون العاملين في إدارة الموارد البشرية المنشأة، أو الشركات التابعة لها. هي الفترة التي يقضيها العامل في العمل لدى الخدمة المنشأة بموجب عقد عمل وبشكل مستمر من تاريخ التحاقه به وإلى، انتهاء خدمته فيه. خدمات طبية تُؤمّن للعاملين وأسرهم وفق، ما هو الرعاية الطبية منصوص في نظام الضمان الصحي التعاوني. هو تكليف للعامل بالسفر من أجل إتمام مهمة الانتداب عمل محددة وذلك وفق الأحكام التي تبينها اللائحة. زوج العامل والأبناء غير المتزوجين والبنات غير أسرة العامل المتزوجات. مكافأة نهاية الخدمة مكافأة تدفع للعامل عند نهاية خدمته في المنشأة. ساعات العمل التي يقضيها العامل في العمل دون ساعات العمل احتساب فترات الراحة."}]','["ليقت","هنم","مصفوف","صلاحي","مجلس","تنظيم","لايح","عقد","يقضي","متزوج"]','["broken_glyphs"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-006','policy-doc-work-regulation',NULL,'التوظيف',2,6,'ويُراعى عند التوظيف في المنشأة ما يلي','proposed','ويُراعى عند التوظيف في المنشأة ما يلي: يوظف العمال على وظائف ذات مسميات ومواصفات، معينة؛
1. أن يكون طالب العمل سعودي الجنسية.
2. أن يكون حائزًا على المؤهلات العلمية، والخبرات المطلوبة للوظيفة من قبل المنشأة.
3. أن يجتاز بنجاح ما قد تقرره المنشأة من اختبارات، أو مقابلات شخصية تتطلبها الوظيفة.
4. أن يكون لائقًا طبيًا بموجب شهادة طبية من الجهة التي تحددها المنشأة.
5. يجوز استثناءً توظيف غير السعودي وفقًا للشروط والأحكام، الواردة في (المواد السادسة: والعشرون الثانية، والثلاثون، الثالثة والثلاثون من) نظام العمل.','[{"index":1,"marker":null,"text":"ويُراعى عند التوظيف في المنشأة ما يلي: يوظف العمال على وظائف ذات مسميات ومواصفات، معينة؛"},{"index":2,"marker":"1","text":"أن يكون طالب العمل سعودي الجنسية."},{"index":3,"marker":"2","text":"أن يكون حائزًا على المؤهلات العلمية، والخبرات المطلوبة للوظيفة من قبل المنشأة."},{"index":4,"marker":"3","text":"أن يجتاز بنجاح ما قد تقرره المنشأة من اختبارات، أو مقابلات شخصية تتطلبها الوظيفة."},{"index":5,"marker":"4","text":"أن يكون لائقًا طبيًا بموجب شهادة طبية من الجهة التي تحددها المنشأة."},{"index":6,"marker":"5","text":"يجوز استثناءً توظيف غير السعودي وفقًا للشروط والأحكام، الواردة في (المواد السادسة: والعشرون الثانية، والثلاثون، الثالثة والثلاثون من) نظام العمل."}]','["ويراع","توظيف","يلي","سعود","يوظف","مسمي","ومواصف","طالب","يجتاز","ثلاث"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-007','policy-doc-work-regulation',NULL,'التوظيف',2,7,'يشترط في المرشح لشغل وظيفة من وظائف المنشأة ما','proposed','يشترط في المرشح لشغل وظيفة من وظائف المنشأة ما يلي:.ل ما معلا واردة في نظ طور ماكحلأاو لا ا شلل عودي وفق فر غي الس زو يظوت عودي الجنسية ويج، 1.أن ون يك س ألا.2 يقل سن المتقدم (عن 18 عاماً) أن.3 يكون حائزًا على المؤهلات العلمية والخبرات العملية اللازمة لشغل الوظيفة مع، ضرورة تقديم المستندات الأصلية المؤيدة لحصوله على تلك المؤهلات. أن.4 يكون لائقًا طبيًا بموجب شهادة صادرة من الجهة الطبية التي يحددها المنشأة. ا خصية تتطلّبه ارات تحريرية،أو شفوية،أو عملية،أو مقابلات ش اح ام دق تُقرره المنشأة نم اختب زا جنب أن.5 يجت.ة الوظيف أن.6 تنطبق عليه أي شروط خاصة تتطلّبها طبيعة العمل الوظيفي. يجوز.7 للمنشأة عند الضرورة إضافة شروط أخرى تتطلّبها طبيعة عمل بعض الوظائف بناء، على موافقة صاحب الصلاحية. روط التوظيف. اء المتقدمين للعمل بالمنشأة نم رط ش أو ر أكث نم ش 8.وز يج للرئيس التنفيذي إعف','[{"index":1,"marker":null,"text":"يشترط في المرشح لشغل وظيفة من وظائف المنشأة ما يلي:.ل ما معلا واردة في نظ طور ماكحلأاو لا ا شلل عودي وفق فر غي الس زو يظوت عودي الجنسية ويج، 1.أن ون يك س ألا.2 يقل سن المتقدم (عن 18 عاماً) أن.3 يكون حائزًا على المؤهلات العلمية والخبرات العملية اللازمة لشغل الوظيفة مع، ضرورة تقديم المستندات الأصلية المؤيدة لحصوله على تلك المؤهلات. أن.4 يكون لائقًا طبيًا بموجب شهادة صادرة من الجهة الطبية التي يحددها المنشأة. ا خصية تتطلّبه ارات تحريرية،أو شفوية،أو عملية،أو مقابلات ش اح ام دق تُقرره المنشأة نم اختب زا جنب أن.5 يجت.ة الوظيف أن.6 تنطبق عليه أي شروط خاصة تتطلّبها طبيعة العمل الوظيفي. يجوز.7 للمنشأة عند الضرورة إضافة شروط أخرى تتطلّبها طبيعة عمل بعض الوظائف بناء، على موافقة صاحب الصلاحية. روط التوظيف. اء المتقدمين للعمل بالمنشأة نم رط ش أو ر أكث نم ش 8.وز يج للرئيس التنفيذي إعف"}]','["لشغل","وظيف","وظايف","يشترط","تتطلب","متقدم","مرشح","طبيع","موهل","ضرور"]','["broken_glyphs"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-008','policy-doc-work-regulation',NULL,'التوظيف',2,8,'الاحتياجات من القوى العاملة','extracted','تُحدد احتياجات المنشأة من القوى العاملة من خلال خطة يعتمدها صاحب الصلاحية مبنية، على توصية من إدارة الموارد البشرية بالتنسيق مع الإدارات ذات العلاقة.','[{"index":1,"marker":null,"text":"تُحدد احتياجات المنشأة من القوى العاملة من خلال خطة يعتمدها صاحب الصلاحية مبنية، على توصية من إدارة الموارد البشرية بالتنسيق مع الإدارات ذات العلاقة."}]','["قوي","احتياج","خطه","مبن","يعتمد","تنسيق","توص","ذات","علاق","ادار"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-009','policy-doc-work-regulation',NULL,'التوظيف',2,9,'تحليل وتقييم الوظائف','extracted','الغرض من تحليل وتقييم الوظائف هو ضمان تحديد الوظائف التي يتطلّبها المنشأة وقياسها بموضوعية وفقًا، للأدوار والمسؤوليات ويعتمد، مجلس الإدارة الهيكل التنظيمي والأدوار، المسندة للإدارات في المنشأة قبل، القيام بعملية التوظيف.','[{"index":1,"marker":null,"text":"الغرض من تحليل وتقييم الوظائف هو ضمان تحديد الوظائف التي يتطلّبها المنشأة وقياسها بموضوعية وفقًا، للأدوار والمسؤوليات ويعتمد، مجلس الإدارة الهيكل التنظيمي والأدوار، المسندة للإدارات في المنشأة قبل، القيام بعملية التوظيف."}]','["وتقييم","تحليل","وظايف","ادوار","يتطلب","وقياس","بموضوع","هيكل","ضمان","ويعتمد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-010','policy-doc-work-regulation',NULL,'التوظيف',2,10,'مصادر الحصول على الكفاءات','extracted','يتم الإعلان عن الوظائف الشاغرة في المنشأة عن طريق إدارة الموارد البشرية عبر واحدة أو أكثر من الوسائل التالية: الإعلان- الداخلي. شركات- التوظيف. الموقع- الإلكتروني للمنشأة. مواقع- التواصل الاجتماعي. أي- وسيلة أخرى تراها إدارة الموارد البشرية مناسبة. ويمكن لأي من العاملين لدى المنشأة تزويد إدارة الموارد البشرية بسير ذاتية دون التدخل في عملية التوظيف.','[{"index":1,"marker":null,"text":"يتم الإعلان عن الوظائف الشاغرة في المنشأة عن طريق إدارة الموارد البشرية عبر واحدة أو أكثر من الوسائل التالية: الإعلان- الداخلي. شركات- التوظيف. الموقع- الإلكتروني للمنشأة. مواقع- التواصل الاجتماعي. أي- وسيلة أخرى تراها إدارة الموارد البشرية مناسبة. ويمكن لأي من العاملين لدى المنشأة تزويد إدارة الموارد البشرية بسير ذاتية دون التدخل في عملية التوظيف."}]','["مصادر","كفاء","موارد","بشر","توظيف","حصول","عبر","ويمكن","تزويد","بسير"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-011','policy-doc-work-regulation',NULL,'التوظيف',2,11,'تكاليف المقابلات الشخصية قبل التعاقد','extracted','يجوز لصاحب الصلاحية التوجيه بالموافقة على تحمل تكاليف قدوم المرشح لمقابلة المختصين بالمنشأة لغرض التوظيف، ويشمل تكلفة السفر والسكن بما لا (يتجاوز 1,000 ألف) ريال لليوم الواحد وبحد، أقصى يومان.','[{"index":1,"marker":null,"text":"يجوز لصاحب الصلاحية التوجيه بالموافقة على تحمل تكاليف قدوم المرشح لمقابلة المختصين بالمنشأة لغرض التوظيف، ويشمل تكلفة السفر والسكن بما لا (يتجاوز 1,000 ألف) ريال لليوم الواحد وبحد، أقصى يومان."}]','["تكاليف","تعاقد","مقابل","شخص","توج","لمقابل","تكلف","000","الف","قدوم"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-012','policy-doc-work-regulation',NULL,'التوظيف',2,12,'متطلبات التوظيف','extracted','على كل من يرغب بالعمل لدى المنشأة تقديم نسخة من الوثائق الآتية مع الأصل للمطابقة ويجب، أن تحفظ صورة منها في ملف خدمته في حالة توظيفه: ة سارية المفعول وسجل الأسرة للسعوديين،أو جواز السفر لغير السعوديين. ة الوطني بطاقة.1 الهوي الشهادات.2 الدراسية المطلوبة لشغل الوظيفة وفي، حال كانت الشهادات الدراسية من خارج المملكة فإنه تلزم معادلتها من الجهات المختصة في المملكة. إخلاء.3 طرف أو شهادة خبرة من العمل السابق. تقرير.4 طبي عن صلاحية المرشح لشغل الوظيفة صادر، عن مركز طبي معتمد لدى المنشأة. شهادات.5 الخبرة السابقة المطلوبة لشغل الوظيفة. بيان.6 يحدد فيه محل إقامته وحالته الاجتماعية. بيانات.7 الحساب البنكي الشخصي الخاص به. أية.8 متطلبات أو مستندات أخرى يشترطها المنشأة.','[{"index":1,"marker":null,"text":"على كل من يرغب بالعمل لدى المنشأة تقديم نسخة من الوثائق الآتية مع الأصل للمطابقة ويجب، أن تحفظ صورة منها في ملف خدمته في حالة توظيفه: ة سارية المفعول وسجل الأسرة للسعوديين،أو جواز السفر لغير السعوديين. ة الوطني بطاقة.1 الهوي الشهادات.2 الدراسية المطلوبة لشغل الوظيفة وفي، حال كانت الشهادات الدراسية من خارج المملكة فإنه تلزم معادلتها من الجهات المختصة في المملكة. إخلاء.3 طرف أو شهادة خبرة من العمل السابق. تقرير.4 طبي عن صلاحية المرشح لشغل الوظيفة صادر، عن مركز طبي معتمد لدى المنشأة. شهادات.5 الخبرة السابقة المطلوبة لشغل الوظيفة. بيان.6 يحدد فيه محل إقامته وحالته الاجتماعية. بيانات.7 الحساب البنكي الشخصي الخاص به. أية.8 متطلبات أو مستندات أخرى يشترطها المنشأة."}]','["شهاد","لشغل","متطلب","سعودي","دراس","توظيف","مطلوب","بيان","وظيف","مملك"]','["broken_glyphs"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-013','policy-doc-work-regulation',NULL,'التوظيف',2,13,'اختصاصات التوظيف','extracted','تُشغل. الوظيفة الشاغرة بالدرجة الوظيفة المناسبة والملائمة للمؤهلات والخبرات وتكون، صلاحيات تعيين العاملين في المنشأة وتحديد أجورهم وترقياتهم وفقًا للائحة الصلاحيات يجوز. تكليف أي عامل للقيام بمهام وظيفة أخرى ذات درجة وظيفية أقل أو أعلى من التي يشغلها بما لا يتعارض مع أحكام المادّة 60 من نظام العمل.','[{"index":1,"marker":null,"text":"تُشغل. الوظيفة الشاغرة بالدرجة الوظيفة المناسبة والملائمة للمؤهلات والخبرات وتكون، صلاحيات تعيين العاملين في المنشأة وتحديد أجورهم وترقياتهم وفقًا للائحة الصلاحيات يجوز. تكليف أي عامل للقيام بمهام وظيفة أخرى ذات درجة وظيفية أقل أو أعلى من التي يشغلها بما لا يتعارض مع أحكام المادّة 60 من نظام العمل."}]','["اختصاص","وظيف","صلاحي","درج","توظيف","ايح","بمهام","يشغل","تشغل","وتحديد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-014','policy-doc-work-regulation',NULL,'التوظيف',2,14,'إعادة التعاقد مع من سبق لهم العمل في المنشأة','extracted','يجوز إعادة التعاقد مع من سبق له العمل في المنشأة؛ إذا كان هناك حاجة لخدماته وفق الشروط الآتية:
أ. ألاّ يكون قد تم فصله أو إنهاء عقده من قبل المنشأة.
ب. أن يكون قد مضى على استقالته أكثر من سنة ميلادية.
ج. ألاّ تقل خبرته السابقة في المنشأة عن سنة.
د. أن تنطبق عليه شروط الوظيفة المرشح لشغلها.','[{"index":1,"marker":null,"text":"يجوز إعادة التعاقد مع من سبق له العمل في المنشأة؛ إذا كان هناك حاجة لخدماته وفق الشروط الآتية:"},{"index":2,"marker":"أ","text":"ألاّ يكون قد تم فصله أو إنهاء عقده من قبل المنشأة."},{"index":3,"marker":"ب","text":"أن يكون قد مضى على استقالته أكثر من سنة ميلادية."},{"index":4,"marker":"ج","text":"ألاّ تقل خبرته السابقة في المنشأة عن سنة."},{"index":5,"marker":"د","text":"أن تنطبق عليه شروط الوظيفة المرشح لشغلها."}]','["اعاد","سبق","تعاقد","لهم","شروط","لخدم","هنا","تنطبق","سنه","حاج"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-015','policy-doc-work-regulation',NULL,'التوظيف',2,15,'الاستعانة بخبرات خارجية','extracted','يجوز للمنشأة الاستعانة بخبرات خارجية من القطاع العام أو الخاص، أو الجهات البحثية بتفرغ كامل للعمل كمعارين لديه، وتُحدّد المزايا المالية والعينية لهم؛ وفقًا للمؤهلات العلمية والعملية التي تقررها المنشأة بهذا الخصوص.','[{"index":1,"marker":null,"text":"يجوز للمنشأة الاستعانة بخبرات خارجية من القطاع العام أو الخاص، أو الجهات البحثية بتفرغ كامل للعمل كمعارين لديه، وتُحدّد المزايا المالية والعينية لهم؛ وفقًا للمؤهلات العلمية والعملية التي تقررها المنشأة بهذا الخصوص."}]','["استع","بخبر","خارج","قطاع","بتفرغ","كمعار","خصوص","بحث","عين","بهذا"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-016','policy-doc-work-regulation',NULL,'التوظيف',2,16,'الإعارة','extracted','1 يجوز- إعارة العامل السعودي بعد موافقته للعمل لدى الجهات العامة، أو الخاصة، أو المنظمات المحلية، أو الدولية، وتكون إعارته بقرار من صاحب الصلاحية. 2 يجوز- إلغاء قرار الإعارة قبل انتهاء مدتها؛ إذا اقتضت مصلحة العمل ذلك. 3 يحتفظ- العامل المعار بوظيفته ومرتبته الأصلية طوال مدة الإعارة ولا، يجوز شغلها بغيره عن طريق التعيين أو النقل، ويجوز التكليف عليها. 4 لا- تزيد مدة الإعارة عن سنة واحدة ويجوز تمديدها ولا، يجوز أن تزيد مدة الإعارة بأي حال من الأحوال عن ثلاث سنوات متصلة أو ست سنوات متفرقة ولا، يجوز إعارة العامل الذي أكمل الحد الأقصى للإعارة المتصلة قبل مضي ثلاث سنوات على الأقل من تاريخ الإعارة السابقة. 5 تحتسب- الإعارة من الخدمة وعلى، العامل المعار أن يؤدي خلالها الحسميات المقررة على أجره في وظيفته الأصلية، وما يطرأ عليها من زيادات. 6 يُقطع- أجر العامل المُعار اعتبارًا من تاريخ تركه العمل حتى يعود إلى مباشرته ويجوز، بموافقة صاحب الصلاحية إذا اقتضت مصلحة العمل أن تتحمل المنشأة كل أو بعض أجر العامل المُعار. تنتهي-7 الإعارة بانتهاء مدتها ويجوز، بقرار من صاحب الصلاحية إنهاء الإعارة بناء على طلب من الجهة المستعيرة كما، يجوز قطعها بناء على طلب من الجهة أو العامل المُعار بعد التنسيق مع الجهة المستعيرة.','[{"index":1,"marker":null,"text":"1 يجوز- إعارة العامل السعودي بعد موافقته للعمل لدى الجهات العامة، أو الخاصة، أو المنظمات المحلية، أو الدولية، وتكون إعارته بقرار من صاحب الصلاحية. 2 يجوز- إلغاء قرار الإعارة قبل انتهاء مدتها؛ إذا اقتضت مصلحة العمل ذلك. 3 يحتفظ- العامل المعار بوظيفته ومرتبته الأصلية طوال مدة الإعارة ولا، يجوز شغلها بغيره عن طريق التعيين أو النقل، ويجوز التكليف عليها. 4 لا- تزيد مدة الإعارة عن سنة واحدة ويجوز تمديدها ولا، يجوز أن تزيد مدة الإعارة بأي حال من الأحوال عن ثلاث سنوات متصلة أو ست سنوات متفرقة ولا، يجوز إعارة العامل الذي أكمل الحد الأقصى للإعارة المتصلة قبل مضي ثلاث سنوات على الأقل من تاريخ الإعارة السابقة. 5 تحتسب- الإعارة من الخدمة وعلى، العامل المعار أن يؤدي خلالها الحسميات المقررة على أجره في وظيفته الأصلية، وما يطرأ عليها من زيادات. 6 يُقطع- أجر العامل المُعار اعتبارًا من تاريخ تركه العمل حتى يعود إلى مباشرته ويجوز، بموافقة صاحب الصلاحية إذا اقتضت مصلحة العمل أن تتحمل المنشأة كل أو بعض أجر العامل المُعار. تنتهي-7 الإعارة بانتهاء مدتها ويجوز، بقرار من صاحب الصلاحية إنهاء الإعارة بناء على طلب من الجهة المستعيرة كما، يجوز قطعها بناء على طلب من الجهة أو العامل المُعار بعد التنسيق مع الجهة المستعيرة."}]','["اعار","معار","مستعير","ويجوز","اقتضت","مصلح","سنو","بقرار","جهه","مدت"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-017','policy-doc-work-regulation',NULL,'التوظيف',2,17,'التعاون المؤقت','extracted','يجوز التعاقد مع من هم من ذوي الخبرة لمشروع مؤقت لفترة محددة وتُحدّد، المزايا المالية والعينية لهم وفقًا للمؤهلات العلمية والعملية التي، تقررها المنشأة بهذا الخصوص؛ بما يتوافق مع القيمة السوقية لهم.','[{"index":1,"marker":null,"text":"يجوز التعاقد مع من هم من ذوي الخبرة لمشروع مؤقت لفترة محددة وتُحدّد، المزايا المالية والعينية لهم وفقًا للمؤهلات العلمية والعملية التي، تقررها المنشأة بهذا الخصوص؛ بما يتوافق مع القيمة السوقية لهم."}]','["موقت","لهم","تعا","لمشروع","يتوافق","سوق","خصوص","لفتر","عين","بهذا"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-018','policy-doc-work-regulation',NULL,'عقد العمل',3,18,'يتم توظيف العامل بموجب عقد عمل يحرر من نسختين','proposed','يتم توظيف العامل بموجب عقد عمل يحرر من نسختين باللغة العربية وفقًا للنموذج الموحد المُعد من الوزارة تسلم، إحداهما للعامل وتودع الأخرى في ملف خدمته لدى المنشأة بحيث، يتضمن العقد اسم صاحب العمل واسم، العامل، وجنسيته، وعنوانه الأصلي، وعنوانه المختار ونوع، العمل ومكانه، والأجر، الأساسي المتفق عليه وأية، مزايا وبدلات أخرى يتفق عليها وما، إذا كان العقد محدد المدة، أو غير محدد المدة، أو لأداء عمل معين ومدة، التجربة إذا تم الاتفاق عليها، و تاريخ مباشرة العمل وأية، بيانات ضرورية ويجوز، تحرير العقد بلغة أخرى إلى جانب اللغة العربية على; أن يكون النص العربي هو المعتمد دوماً.','[{"index":1,"marker":null,"text":"يتم توظيف العامل بموجب عقد عمل يحرر من نسختين باللغة العربية وفقًا للنموذج الموحد المُعد من الوزارة تسلم، إحداهما للعامل وتودع الأخرى في ملف خدمته لدى المنشأة بحيث، يتضمن العقد اسم صاحب العمل واسم، العامل، وجنسيته، وعنوانه الأصلي، وعنوانه المختار ونوع، العمل ومكانه، والأجر، الأساسي المتفق عليه وأية، مزايا وبدلات أخرى يتفق عليها وما، إذا كان العقد محدد المدة، أو غير محدد المدة، أو لأداء عمل معين ومدة، التجربة إذا تم الاتفاق عليها، و تاريخ مباشرة العمل وأية، بيانات ضرورية ويجوز، تحرير العقد بلغة أخرى إلى جانب اللغة العربية على; أن يكون النص العربي هو المعتمد دوماً."}]','["يحرر","نسخت","عرب","عقد","لغه","وعنو","واي","توظيف","يتم","بموجب"]','["broken_glyphs"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-019','policy-doc-work-regulation',NULL,'عقد العمل',3,19,'مع مراعاة التاريخ المحدد في عقد العمل لمباشرة العمل','proposed','مع مراعاة التاريخ المحدد في عقد العمل لمباشرة العمل؛ يحق للمنشأة إلغاء عقد العامل الذي لا يباشر مهام عمله دون عذر مشروع خلال سبعة أيام عمل من تاريخ التوقيع على العقد بين الطرفين إذا كان التعاقد تم داخل المملكة، أو من تاريخ قدومه إلى المملكة إذا كان التعاقد تم خارج المملكة.','[{"index":1,"marker":null,"text":"مع مراعاة التاريخ المحدد في عقد العمل لمباشرة العمل؛ يحق للمنشأة إلغاء عقد العامل الذي لا يباشر مهام عمله دون عذر مشروع خلال سبعة أيام عمل من تاريخ التوقيع على العقد بين الطرفين إذا كان التعاقد تم داخل المملكة، أو من تاريخ قدومه إلى المملكة إذا كان التعاقد تم خارج المملكة."}]','["لمباشر","مراعا","عقد","مملك","تاريخ","محدد","تعاقد","غاء","عذر","قدوم"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-020','policy-doc-work-regulation',NULL,'عقد العمل',3,20,'من– مكان عمله الأصلي إلى مكان آخر يقتضي تغير','proposed','من– مكان عمله الأصلي إلى مكان آخر يقتضي تغير محل إقامته.
1. لا يجوز للمنشأة أن ينقل العامل بغير موافقته كتابة-
2. للمنشأة في حالات الضرورة التي قد تقتضيها ظروف عارضة ولمدة لا تتجاوز ثلاثين يوماً في السنة تكليف العامل بعمل في مكان يختلف عن المكان المتفق عليه دون اشتراط موافقته على، أن تتحمل المنشأة تكاليف انتقال العامل وإقامته خلال تلك المدة.','[{"index":1,"marker":null,"text":"من– مكان عمله الأصلي إلى مكان آخر يقتضي تغير محل إقامته."},{"index":2,"marker":"1","text":"لا يجوز للمنشأة أن ينقل العامل بغير موافقته كتابة-"},{"index":3,"marker":"2","text":"للمنشأة في حالات الضرورة التي قد تقتضيها ظروف عارضة ولمدة لا تتجاوز ثلاثين يوماً في السنة تكليف العامل بعمل في مكان يختلف عن المكان المتفق عليه دون اشتراط موافقته على، أن تتحمل المنشأة تكاليف انتقال العامل وإقامته خلال تلك المدة."}]','["مكان","تغير","يقتض","اصل","تقتضي","عارض","ولمد","يختلف","واقام","اخر"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-021','policy-doc-work-regulation',NULL,'عقد العمل',3,21,'يجوز. تكليف العامل بالعمل في مكان مختلف عن المكان المتفق علي','proposed','يجوز. تكليف العامل بالعمل في مكان مختلف عن المكان المتفق عليه دون اشتراط موافقته ووفقًا، لما تقدرة المنشأة دون أن يقتضي ذلك تغييرًا في محل إقامته. يجوز. إنهاء تكليف العامل في أي وقت قبل انتهاء مدته بقرار من صاحب الصلاحية.','[{"index":1,"marker":null,"text":"يجوز. تكليف العامل بالعمل في مكان مختلف عن المكان المتفق عليه دون اشتراط موافقته ووفقًا، لما تقدرة المنشأة دون أن يقتضي ذلك تغييرًا في محل إقامته. يجوز. إنهاء تكليف العامل في أي وقت قبل انتهاء مدته بقرار من صاحب الصلاحية."}]','["مكان","مختلف","تكليف","متفق","ووفقا","تقدر","تغييرا","يقتض","دون","اشتراط"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-022','policy-doc-work-regulation',NULL,'عقد العمل',3,22,'الالتحاق بالعمل','extracted','1 يعتبر. تاريخ مباشرة العامل لعمله هو تاريخ ابتداء الخدمة ويتم، التوظيف بموجب قرار تعيين إداري معتمد من صاحب الصلاحية مبني على عقد العمل. 2 يعتبر. عقد العمل ساريًا ومنتجًا لجميع الآثار المترتبة عليه من تاريخ مباشرة العامل الفعلية للعمل.','[{"index":1,"marker":null,"text":"1 يعتبر. تاريخ مباشرة العامل لعمله هو تاريخ ابتداء الخدمة ويتم، التوظيف بموجب قرار تعيين إداري معتمد من صاحب الصلاحية مبني على عقد العمل. 2 يعتبر. عقد العمل ساريًا ومنتجًا لجميع الآثار المترتبة عليه من تاريخ مباشرة العامل الفعلية للعمل."}]','["التحاق","يعتبر","تاريخ","لعمل","ساريا","ومنتجا","مباشر","ابتداء","ويتم","مبن"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-023','policy-doc-work-regulation',NULL,'عقد العمل',3,23,'فترة التجربة','extracted','1 لا. يُعد العامل الذي يعمل لدى المنشأة تحت التجربة إلا إذا تم النص على ذلك صراحة في عقد العمل. تُحدد فترة التجربة بما لا يزيد عن يومًا.180 2 يجوز. إخضاع العامل لفترة تجربة أخرى باتفاق مكتوب بين الطرفين بشرط، أن تكون الوظيفة الجديدة مختلفة عن الوظيفة السابقة وألا، تتجاوز فترة التجربة الثانية 180 يومًا.','[{"index":1,"marker":null,"text":"1 لا. يُعد العامل الذي يعمل لدى المنشأة تحت التجربة إلا إذا تم النص على ذلك صراحة في عقد العمل. تُحدد فترة التجربة بما لا يزيد عن يومًا.180 2 يجوز. إخضاع العامل لفترة تجربة أخرى باتفاق مكتوب بين الطرفين بشرط، أن تكون الوظيفة الجديدة مختلفة عن الوظيفة السابقة وألا، تتجاوز فترة التجربة الثانية 180 يومًا."}]','["تجرب","180","فتر","اخضاع","باتفاق","صراح","جديد","والا","وظيف","يوما"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-024','policy-doc-work-regulation',NULL,'عقد العمل',3,24,'تقويم أداء العامل خلال فترة التجربة','extracted','يُقوّم أداء العامل خلال فترة التجربة وذلك، من خلال نموذج مخصص تُعدّه لهذا الغرض إدارة الموارد البشرية.','[{"index":1,"marker":null,"text":"يُقوّم أداء العامل خلال فترة التجربة وذلك، من خلال نموذج مخصص تُعدّه لهذا الغرض إدارة الموارد البشرية."}]','["تجرب","اداء","خلال","تقويم","فتر","يقوم","لهذا","غرض","نموذج","مخصص"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-025','policy-doc-work-regulation',NULL,'عقد العمل',3,25,'التقرير النهائي عن فترة التجربة','extracted','يجب أن يقدم مدير الإدارة تقويمه لأداء العامل قبل أسبوعين على الأقل من نهاية فترة التجربة ويجب، أن يتضمن التقرير توصية بتثبيت العامل على الوظيفة، أو وظيفة أخرى أو إنهاء خدمته.','[{"index":1,"marker":null,"text":"يجب أن يقدم مدير الإدارة تقويمه لأداء العامل قبل أسبوعين على الأقل من نهاية فترة التجربة ويجب، أن يتضمن التقرير توصية بتثبيت العامل على الوظيفة، أو وظيفة أخرى أو إنهاء خدمته."}]','["نهاي","تقرير","تجرب","فتر","بتثبيت","يقدم","وظيف","يتضمن","توص","تقويم"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-026','policy-doc-work-regulation',NULL,'عقد العمل',3,26,'تثبيت العامل في الوظيفة','extracted','يُثبّت العامل بقرار من صاحب الصلاحية بعد، إنهائه فترة التجربة بنجاح وتعتبر خدمته متصلة من تاريخ مباشرته العمل.','[{"index":1,"marker":null,"text":"يُثبّت العامل بقرار من صاحب الصلاحية بعد، إنهائه فترة التجربة بنجاح وتعتبر خدمته متصلة من تاريخ مباشرته العمل."}]','["تثبيت","انها","بنجاح","وظيف","وتعتبر","بقرار","متصل","يثبت","تجرب","مباشر"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-027','policy-doc-work-regulation',NULL,'عقد العمل',3,27,'انهاء خدمة العامل خلال فترة التجربة','extracted','إذا لم تثبت صلاحية العامل خلال فترة التجربة للعمل جاز، للمنشأة إنهاء عقد العمل دون مكافأة، أو إنذار، أو تعويض؛ وذلك وفقًا لنظام العمل.','[{"index":1,"marker":null,"text":"إذا لم تثبت صلاحية العامل خلال فترة التجربة للعمل جاز، للمنشأة إنهاء عقد العمل دون مكافأة، أو إنذار، أو تعويض؛ وذلك وفقًا لنظام العمل."}]','["انهاء","تجرب","فتر","خلال","جاز","تثبت","خدم","انذار","لنظام","مكافا"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-028','policy-doc-work-regulation',NULL,'عقد العمل',3,28,'تُشغل الوظيفة الشاغرة بالدرجة الوظيفة المناسبة والملائمة للمؤهلات والخبرات','proposed','تُشغل الوظيفة الشاغرة بالدرجة الوظيفة المناسبة والملائمة للمؤهلات والخبرات وتكون، صلاحيات تعيين العاملين في المنشأة وتحديد أجورهم وترقياتهم وفقًا لمصفوفة الصلاحيات.','[{"index":1,"marker":null,"text":"تُشغل الوظيفة الشاغرة بالدرجة الوظيفة المناسبة والملائمة للمؤهلات والخبرات وتكون، صلاحيات تعيين العاملين في المنشأة وتحديد أجورهم وترقياتهم وفقًا لمصفوفة الصلاحيات."}]','["تشغل","وظيف","ملايم","شاغر","موهل","درج","خبر","مناسب","صلاحي","وتحديد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-029','policy-doc-work-regulation',NULL,'عقد العمل',3,29,'ملفات وسجلات العاملين','extracted','تكون إدارة الموارد البشرية مسؤولة عن توثيق سجلات العاملين وحفظها، واستكمالها، وتحديثها، دوريًا والمحافظة، على سريتها.','[{"index":1,"marker":null,"text":"تكون إدارة الموارد البشرية مسؤولة عن توثيق سجلات العاملين وحفظها، واستكمالها، وتحديثها، دوريًا والمحافظة، على سريتها."}]','["وسجل","ملف","وحفظ","واستكمال","وتحديث","توثيق","دوريا","سجل","محافظ","سري"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-030','policy-doc-work-regulation',NULL,'عقد العمل',3,30,'المحظورات على العامل','extracted','يُحظر على العامل القيام بالآتي:
أ. الاحتفاظ بأية أوراق أو مستندات وصلت إليه بحكم عمله خارج الأماكن المخصصة لذلك في المنشأة.
ب. الاشتراك في أي نشاط تقوم به المشروعات أو المنشآت التي تمارس نشاطًا مماثلاً للنشاط الذي تمارسه المنشأة، دون موافقة مسبقة من المنشأة.
ج. أي سلوك غير لائق في محيط العمل وخارجه.
د. تنفيذ المشاريع التي تخص المنشأة لحسابه الخاص بشكل، مباشر أو غير مباشر.
ه. تأجير عقار أو منقول للمنشأة بشكل، مباشر أو غير مباشر.
و. الإدلاء بأية معلومات، أو تصريحات للصحف، أو وسائل الإعلام المختلفة، أو إلقاء محاضرات، أو مقالات تتعلق بالمنشأة ما لم يكن هناك موافقة خطية مسبقة من صاحب الصلاحية.
ز. الإهمال أو التقصير المتعمد في أداء واجباته.
ح. القيام بشكل غير مشروع بجمع أموال لأي فرد، أو هيئة، او جهة عمل أو بتوزيع منشورات، أو بجمع توقيعات، أو بالاشتراك في تنظيم اجتماعات داخل مقر العمل.
ط. استخدام العنف اللفظي أو الجسدي في موقع العمل ضد مديريه، أو زملائه، أو غيرهم ممن يتعاملون مع المنشأة.
ي. قبول الهدايا الخاصة من المستفيدين من المنشأة والموردين.
ك. التدخل في الشؤون السياسية، أو القيام بأية تعليقات، أو تفسيرات تنطوي على المساس بالاحترام الواجب للأنظمة والأوامر والتعليمات الصادرة من الجهات الرسمية.','[{"index":1,"marker":null,"text":"يُحظر على العامل القيام بالآتي:"},{"index":2,"marker":"أ","text":"الاحتفاظ بأية أوراق أو مستندات وصلت إليه بحكم عمله خارج الأماكن المخصصة لذلك في المنشأة."},{"index":3,"marker":"ب","text":"الاشتراك في أي نشاط تقوم به المشروعات أو المنشآت التي تمارس نشاطًا مماثلاً للنشاط الذي تمارسه المنشأة، دون موافقة مسبقة من المنشأة."},{"index":4,"marker":"ج","text":"أي سلوك غير لائق في محيط العمل وخارجه."},{"index":5,"marker":"د","text":"تنفيذ المشاريع التي تخص المنشأة لحسابه الخاص بشكل، مباشر أو غير مباشر."},{"index":6,"marker":"ه","text":"تأجير عقار أو منقول للمنشأة بشكل، مباشر أو غير مباشر."},{"index":7,"marker":"و","text":"الإدلاء بأية معلومات، أو تصريحات للصحف، أو وسائل الإعلام المختلفة، أو إلقاء محاضرات، أو مقالات تتعلق بالمنشأة ما لم يكن هناك موافقة خطية مسبقة من صاحب الصلاحية."},{"index":8,"marker":"ز","text":"الإهمال أو التقصير المتعمد في أداء واجباته."},{"index":9,"marker":"ح","text":"القيام بشكل غير مشروع بجمع أموال لأي فرد، أو هيئة، او جهة عمل أو بتوزيع منشورات، أو بجمع توقيعات، أو بالاشتراك في تنظيم اجتماعات داخل مقر العمل."},{"index":10,"marker":"ط","text":"استخدام العنف اللفظي أو الجسدي في موقع العمل ضد مديريه، أو زملائه، أو غيرهم ممن يتعاملون مع المنشأة."},{"index":11,"marker":"ي","text":"قبول الهدايا الخاصة من المستفيدين من المنشأة والموردين."},{"index":12,"marker":"ك","text":"التدخل في الشؤون السياسية، أو القيام بأية تعليقات، أو تفسيرات تنطوي على المساس بالاحترام الواجب للأنظمة والأوامر والتعليمات الصادرة من الجهات الرسمية."}]','["بشكل","محظور","تمارس","بجمع","مباشر","باي","اشترا","نشاط","مسبق","قيام"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-031','policy-doc-work-regulation',NULL,'عقد العمل',3,31,'المحافظة على الصحة والسلامة في العمل','extracted','أ. التقيد بقواعد وإجراءات السلامة واستعمال، وسائل الوقاية الخاصة بالعمل وتنفيذ، الإرشادات الخاصة بالسلامة؛ للمحافظة على حياته وصحته وتبليغ، المنشأة عن أية أخطار أو مخالفات يجدها في محيط العمل.
ب. إبلاغ المشرفين في العمل عن أية أعراض مرضية يمكن، أن تؤثر سلبًا على أداء عمله، أو تؤثر على سلامة الآخرين.
ج. مد يد العون والمساعدة عند وقوع كوارث طبيعية، أو حدوث خطر يهدد سلامة الآخرين في، محيط العمل أو قريباً منه.','[{"index":1,"marker":"أ","text":"التقيد بقواعد وإجراءات السلامة واستعمال، وسائل الوقاية الخاصة بالعمل وتنفيذ، الإرشادات الخاصة بالسلامة؛ للمحافظة على حياته وصحته وتبليغ، المنشأة عن أية أخطار أو مخالفات يجدها في محيط العمل."},{"index":2,"marker":"ب","text":"إبلاغ المشرفين في العمل عن أية أعراض مرضية يمكن، أن تؤثر سلبًا على أداء عمله، أو تؤثر على سلامة الآخرين."},{"index":3,"marker":"ج","text":"مد يد العون والمساعدة عند وقوع كوارث طبيعية، أو حدوث خطر يهدد سلامة الآخرين في، محيط العمل أو قريباً منه."}]','["سلام","محافظ","صحه","توثر","محيط","ايه","واستعمال","وتنفيذ","ارشاد","حيا"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-032','policy-doc-work-regulation',NULL,'عقد العمل',3,32,'انتهاء الخدمة','extracted','المسؤوليات في حالة استقالة العامل، أو في حالة الحاجة إلى إنهاء العامل، تتحدد المسؤوليات في الآتي: 1 مديرو- الإدارات:
أ. بحث الأسباب والظروف التي أدت إلى ترك العامل الخدمة في المنشأة وتقديم، ملحوظاتهم لإدارة الموارد البشرية حول أسباب الترك.
ب. طلب المشورة من إدارة الموارد البشرية عن كل حالة من حالات ترك الخدمة؛ للتعرف على التزامات المنشأة حيالها.
ج. اتباع الإجراءات المعتمدة في المنشأة والخاصة بانتهاء الخدمة. 2 إدارة- الموارد البشرية:
أ. تقديم المشورة لمختلف الإدارات حول السياسات والقواعد والإجراءات الملائمة للتطبيق في كل حالة.
ب. مراجعة حالات إنهاء الخدمة بالتفصيل؛ للتأكد من توافقها مع السياسات والإجراءات المقررة في هذه اللائحة وفي، نظام العمل.
ج. التأكد من التقيّد بالإجراءات المعتمدة لإنهاء الخدمة.','[{"index":1,"marker":null,"text":"المسؤوليات في حالة استقالة العامل، أو في حالة الحاجة إلى إنهاء العامل، تتحدد المسؤوليات في الآتي: 1 مديرو- الإدارات:"},{"index":2,"marker":"أ","text":"بحث الأسباب والظروف التي أدت إلى ترك العامل الخدمة في المنشأة وتقديم، ملحوظاتهم لإدارة الموارد البشرية حول أسباب الترك."},{"index":3,"marker":"ب","text":"طلب المشورة من إدارة الموارد البشرية عن كل حالة من حالات ترك الخدمة؛ للتعرف على التزامات المنشأة حيالها."},{"index":4,"marker":"ج","text":"اتباع الإجراءات المعتمدة في المنشأة والخاصة بانتهاء الخدمة. 2 إدارة- الموارد البشرية:"},{"index":5,"marker":"أ","text":"تقديم المشورة لمختلف الإدارات حول السياسات والقواعد والإجراءات الملائمة للتطبيق في كل حالة."},{"index":6,"marker":"ب","text":"مراجعة حالات إنهاء الخدمة بالتفصيل؛ للتأكد من توافقها مع السياسات والإجراءات المقررة في هذه اللائحة وفي، نظام العمل."},{"index":7,"marker":"ج","text":"التأكد من التقيّد بالإجراءات المعتمدة لإنهاء الخدمة."}]','["خدم","ترك","اجراء","حول","مشور","تاكد","مسوولي","اسباب","سياس","ادار"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-033','policy-doc-work-regulation',NULL,'عقد العمل',3,33,'أسباب انتهاء عقد العمل ينتهي عقد العمل في أي','proposed','أسباب انتهاء عقد العمل ينتهي عقد العمل في أي من الأحوال الآتية: 1 إذا- اتفق الطرفان على إنهائه بشرط، أن تكون موافقة العامل كتابية. إذا-2 انتهت المدة المحددة في العقد ما، لم يكن العقد قد تجدد صراحة وفق أحكام هذا النظام؛ فيستمر إلى أجله. 3 بنا-ً ء على إرادة أحد الطرفين في العقود غير المحددة المدة وف،ً قا لما ورد في (المادة الخامسة والسبعون من) هذا النظام. مكرر(3 الاستقالة.). 4 بلوغ- العامل سن التقاعد وفق ما تقضي به أحكام نظام التأمينات الاجتماعية ما، لم يتفق الطرفان على الاستمرار في العمل بعد هذه السن. القوة-5 القاهرة. إغلاق-6 المنشأة نهائيًا. -7 بإنهاء عقد العمل في أي من إجراءات الإفلاس المفتتحة؛ إنهاء النشاط الذي يعمل فيه العامل ما، لم يُتفق على غير ذلك. مكرر(7 صدور). قرار، أو حكم نهائي من المحكمةّ ة المختص وفق نظام الإفلاس. 8 أي- حالة أخرى ينص عليها نظام آخر.','[{"index":1,"marker":null,"text":"أسباب انتهاء عقد العمل ينتهي عقد العمل في أي من الأحوال الآتية: 1 إذا- اتفق الطرفان على إنهائه بشرط، أن تكون موافقة العامل كتابية. إذا-2 انتهت المدة المحددة في العقد ما، لم يكن العقد قد تجدد صراحة وفق أحكام هذا النظام؛ فيستمر إلى أجله. 3 بنا-ً ء على إرادة أحد الطرفين في العقود غير المحددة المدة وف،ً قا لما ورد في (المادة الخامسة والسبعون من) هذا النظام. مكرر(3 الاستقالة.). 4 بلوغ- العامل سن التقاعد وفق ما تقضي به أحكام نظام التأمينات الاجتماعية ما، لم يتفق الطرفان على الاستمرار في العمل بعد هذه السن. القوة-5 القاهرة. إغلاق-6 المنشأة نهائيًا. -7 بإنهاء عقد العمل في أي من إجراءات الإفلاس المفتتحة؛ إنهاء النشاط الذي يعمل فيه العامل ما، لم يُتفق على غير ذلك. مكرر(7 صدور). قرار، أو حكم نهائي من المحكمةّ ة المختص وفق نظام الإفلاس. 8 أي- حالة أخرى ينص عليها نظام آخر."}]','["عقد","ينته","اسباب","مكرر","افلاس","طرف","نظام","يتفق","انتهاء","اتفق"]','["broken_glyphs","clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-034','policy-doc-work-regulation',NULL,'عقد العمل',3,34,'الاستقالة','extracted','1 للعاملأن. يقدم استقالته من وظيفته شرط أن تكون بخطاب مؤرخ ومُوجّه إلى مدير الإدارة ورقيًا أو إلكترونيًا ونسخة إلى إدارة الموارد البشرية وتتضمن، السبب وتاريخ الاستقالة ويعتبر، طلب الاستقالة مقبولاً اذا مضى عليه اكثر من ثلاثين يوماً دون قبوله 2 يجوز. خلال مدة طلب الاستقالة تأجيل قبولها الى ستين يوماً يوم لأسباب تتعلق بمصلحة العمل.','[{"index":1,"marker":null,"text":"1 للعاملأن. يقدم استقالته من وظيفته شرط أن تكون بخطاب مؤرخ ومُوجّه إلى مدير الإدارة ورقيًا أو إلكترونيًا ونسخة إلى إدارة الموارد البشرية وتتضمن، السبب وتاريخ الاستقالة ويعتبر، طلب الاستقالة مقبولاً اذا مضى عليه اكثر من ثلاثين يوماً دون قبوله 2 يجوز. خلال مدة طلب الاستقالة تأجيل قبولها الى ستين يوماً يوم لأسباب تتعلق بمصلحة العمل."}]','["استقال","قبول","طلب","بخطاب","مورخ","وموج","ورقيا","ونسخ","ويعتبر","مقبولا"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-035','policy-doc-work-regulation',NULL,'عقد العمل',3,35,'الإخطار بإنهاء الخدمة','extracted','على-1 إدارة الموارد البشرية إخطار العامل المنتهية خدماته بذلك كتابة.، 2 يُمنح- العامل الذي اجتاز فترة التجربة وأُنهيت خدماته - لسبب مشروع - فترة الإنذار المقررة في نظام العمل. 3 في- حالة عدم منح العامل الذي اجتاز فترة التجربة وأنهيت خدماته لسبب مشروع فترة الإنذار المقررة في عقده أو في نظام العمل؛ فإنّه يُعوّض عن ذلك وفقاً، لنظام العمل.','[{"index":1,"marker":null,"text":"على-1 إدارة الموارد البشرية إخطار العامل المنتهية خدماته بذلك كتابة.، 2 يُمنح- العامل الذي اجتاز فترة التجربة وأُنهيت خدماته - لسبب مشروع - فترة الإنذار المقررة في نظام العمل. 3 في- حالة عدم منح العامل الذي اجتاز فترة التجربة وأنهيت خدماته لسبب مشروع فترة الإنذار المقررة في عقده أو في نظام العمل؛ فإنّه يُعوّض عن ذلك وفقاً، لنظام العمل."}]','["اجتاز","وانهيت","اخطار","خدم","بانهاء","لسبب","فتر","انذار","مقرر","مشروع"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-036','policy-doc-work-regulation',NULL,'عقد العمل',3,36,'مكافأة نهاية الخدمة','extracted','1 يُراعى- عند حساب مكافأة نهاية الخدمة المستحقة للعامل المنتهية خدمته تطبيق الأحكام الواردة في نظام العمل. يستحق-2 العامل مكافأة نهاية الخدمة وفقًا للنظام وتُحتسب، مكافأة نهاية الخدمة للعامل على النحو الآتي: أ أجر- لنصف شهر عن كل سنة للعامل الذي تبلغ خدمته أقل من خمس سنوات. أجر-ب شهر عن كل سنة خدمة للعامل الذي تبلغ خدمته خمس سنوات فأكثر. 3 إذا- انتهت علاقة العمل بسبب استقالة العامل فيطبق، على العامل المستقيل ما يلي: أ لا- يستحق مكافأة نهاية الخدمة إذا كانت الخدمة أقل من سنتين. بإذا- كانت سنوات الخدمة من سنتين (إلى 5 خمس) سنوات؛ فيستحق ثلث مكافأة نهاية الخدمة عن، كل سنة خدمة. ت إذا- كانت سنوات الخدمة (من 5 خمس) سنوات (إلى 10 عشر) سنوات؛ فيستحق ثلثي المكافأة عن، كل سنة خدمة. إذا-ث كانت سنوات الخدمة أكثر (من 10 عشر) سنوات؛ فيستحق مكافأة نهاية الخدمة كاملة عن، كل سنة خدمة. 4 يتخذ- الأجر الفعلي الأخير أساسًا لحساب مكافأة نهاية الخدمة ويستحق، العامل مكافأة عن كسور السنة؛ وفقًا لنسبة ما قضاه منها في العمل.','[{"index":1,"marker":null,"text":"1 يُراعى- عند حساب مكافأة نهاية الخدمة المستحقة للعامل المنتهية خدمته تطبيق الأحكام الواردة في نظام العمل. يستحق-2 العامل مكافأة نهاية الخدمة وفقًا للنظام وتُحتسب، مكافأة نهاية الخدمة للعامل على النحو الآتي: أ أجر- لنصف شهر عن كل سنة للعامل الذي تبلغ خدمته أقل من خمس سنوات. أجر-ب شهر عن كل سنة خدمة للعامل الذي تبلغ خدمته خمس سنوات فأكثر. 3 إذا- انتهت علاقة العمل بسبب استقالة العامل فيطبق، على العامل المستقيل ما يلي: أ لا- يستحق مكافأة نهاية الخدمة إذا كانت الخدمة أقل من سنتين. بإذا- كانت سنوات الخدمة من سنتين (إلى 5 خمس) سنوات؛ فيستحق ثلث مكافأة نهاية الخدمة عن، كل سنة خدمة. ت إذا- كانت سنوات الخدمة (من 5 خمس) سنوات (إلى 10 عشر) سنوات؛ فيستحق ثلثي المكافأة عن، كل سنة خدمة. إذا-ث كانت سنوات الخدمة أكثر (من 10 عشر) سنوات؛ فيستحق مكافأة نهاية الخدمة كاملة عن، كل سنة خدمة. 4 يتخذ- الأجر الفعلي الأخير أساسًا لحساب مكافأة نهاية الخدمة ويستحق، العامل مكافأة عن كسور السنة؛ وفقًا لنسبة ما قضاه منها في العمل."}]','["خدم","مكافا","نها","سنو","فيستحق","كانت","سنه","تبلغ","سنت","ثلث"]','["broken_glyphs","clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-037','policy-doc-work-regulation',NULL,'عقد العمل',3,37,'ضوابط مكافأة نهاية الخدمة','extracted','1 يتولى- العامل المستقيل بالتنسيق مع الجهات ذات العلاقة إكمال إجراءات انتهاء الخدمة. 2 إذا- استقال العامل يجب على مدير الإدارة التشاور مع صاحب الصلاحية لاتخاذ قرار بشأن طلب الاستقالة؛ وفقًا لجدول المهام والصلاحيات. 3 في- حال قبول طلب الاستقالة؛ يُحدّد صاحب الصلاحية تاريخ آخر يوم عمل للعامل شاملاً فترة الإشعار وله، حق الإعفاء منها. 4 على- العامل أن يستمر في عمله حتى التاريخ الذي تُحدّده الجهة المختصة في المنشأة موعدًا لسريان الاستقالة. 5 لا- يجوز قبول استقالة العامل المُحال إلى التحقيق، أو الموقوف عن العمل؛ حتى يُبت في أمره.','[{"index":1,"marker":null,"text":"1 يتولى- العامل المستقيل بالتنسيق مع الجهات ذات العلاقة إكمال إجراءات انتهاء الخدمة. 2 إذا- استقال العامل يجب على مدير الإدارة التشاور مع صاحب الصلاحية لاتخاذ قرار بشأن طلب الاستقالة؛ وفقًا لجدول المهام والصلاحيات. 3 في- حال قبول طلب الاستقالة؛ يُحدّد صاحب الصلاحية تاريخ آخر يوم عمل للعامل شاملاً فترة الإشعار وله، حق الإعفاء منها. 4 على- العامل أن يستمر في عمله حتى التاريخ الذي تُحدّده الجهة المختصة في المنشأة موعدًا لسريان الاستقالة. 5 لا- يجوز قبول استقالة العامل المُحال إلى التحقيق، أو الموقوف عن العمل؛ حتى يُبت في أمره."}]','["استقال","قبول","طلب","حتي","مكافا","خدم","ضوابط","يتول","تشاور","لاتخاذ"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-038','policy-doc-work-regulation',NULL,'عقد العمل',3,38,'ضوابط إنهاء الخدمة','extracted','1 لا- يستحق مكافأة نهاية الخدمة العامل الذي تنتهي خدمته بسبب عدم الصلاحية في فترة التجربة، أو فُصل لسبب تأديبي؛ وذلك وفقاً (للمادة 80 من) نظام العمل. 2 في- جميع الأحوال يجب على العاملين الذين تنتهي خدماتهم في المنشأة تسليم ما بعهدتهم من آلات، أو معدات، أو أدوات، أو أجهزة تقنية المعلومات للمنشأة. 3 تنتهي- خدمة العامل بوفاته ويصرف أجره الفعلي كاملاً لورثته عن الشهر الذي توفى فيه كما، يصرف له التعويض المستحق عن مدة الإجازة السنوية المستحقة حتى تاريخ الوفاة.','[{"index":1,"marker":null,"text":"1 لا- يستحق مكافأة نهاية الخدمة العامل الذي تنتهي خدمته بسبب عدم الصلاحية في فترة التجربة، أو فُصل لسبب تأديبي؛ وذلك وفقاً (للمادة 80 من) نظام العمل. 2 في- جميع الأحوال يجب على العاملين الذين تنتهي خدماتهم في المنشأة تسليم ما بعهدتهم من آلات، أو معدات، أو أدوات، أو أجهزة تقنية المعلومات للمنشأة. 3 تنتهي- خدمة العامل بوفاته ويصرف أجره الفعلي كاملاً لورثته عن الشهر الذي توفى فيه كما، يصرف له التعويض المستحق عن مدة الإجازة السنوية المستحقة حتى تاريخ الوفاة."}]','["تنته","خدم","مستحق","ضوابط","انهاء","تسليم","بعهد","الات","تقن","بوف"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-039','policy-doc-work-regulation',NULL,'الإركاب',4,39,'يتحدد الالتزام بمصروفات إركاب العامل','proposed','يتحدد الالتزام بمصروفات إركاب العامل، أو أفراد أسرته وفق الضوابط التالية:
1. عند بداية التعاقد وفق، ما يتفق عليه في عقد العمل.
2. عند تمتع العامل بإجازته السنوية وفق، ما يتفق عليه في عقد العمل.
3. عند انتهاء خدمة العامل طبقاً، لأحكام (المادة الأربعون (فقرة) 1 من) نظام العمل.
4. لا تتحمل المنشأة تكاليف عودة العامل إلى بلده في حالة عدم صلاحيته للعمل خلال فترة التجربة، أو إذا رغب في العودة دون سبب مشروع، أو في حالة ارتكابه مخالفة أدت إلى ترحيله بموجب قرار إداري، أو حكم قضائي.','[{"index":1,"marker":null,"text":"يتحدد الالتزام بمصروفات إركاب العامل، أو أفراد أسرته وفق الضوابط التالية:"},{"index":2,"marker":"1","text":"عند بداية التعاقد وفق، ما يتفق عليه في عقد العمل."},{"index":3,"marker":"2","text":"عند تمتع العامل بإجازته السنوية وفق، ما يتفق عليه في عقد العمل."},{"index":4,"marker":"3","text":"عند انتهاء خدمة العامل طبقاً، لأحكام (المادة الأربعون (فقرة) 1 من) نظام العمل."},{"index":5,"marker":"4","text":"لا تتحمل المنشأة تكاليف عودة العامل إلى بلده في حالة عدم صلاحيته للعمل خلال فترة التجربة، أو إذا رغب في العودة دون سبب مشروع، أو في حالة ارتكابه مخالفة أدت إلى ترحيله بموجب قرار إداري، أو حكم قضائي."}]','["يتحدد","بمصروف","التزام","اركاب","يتفق","عود","بلد","ترحيل","افراد","بدا"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-040','policy-doc-work-regulation',NULL,'الإركاب',4,40,'يستحق العامل الذي يتم نقله من مكان عمله الأصلي','proposed','يستحق العامل الذي يتم نقله من مكان عمله الأصلي إلى مكان آخر يقتضي تغيير محل إقامته نفقات نقله ومن، يعولهم شرعاً ممن يقيمون معه في تاريخ النقل بما فيها نفقات الإركاب مع نفقات نقل أمتعتهم؛ مالم يكن النقل بناء على رغبة العامل.','[{"index":1,"marker":null,"text":"يستحق العامل الذي يتم نقله من مكان عمله الأصلي إلى مكان آخر يقتضي تغيير محل إقامته نفقات نقله ومن، يعولهم شرعاً ممن يقيمون معه في تاريخ النقل بما فيها نفقات الإركاب مع نفقات نقل أمتعتهم؛ مالم يكن النقل بناء على رغبة العامل."}]','["نقل","نفق","مكان","اصل","يستحق","يتم","تغيير","ومن","يعول","شرعا"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-041','policy-doc-work-regulation',NULL,'الإركاب',4,41,'تذاكر الإركاب','extracted','يتم-1 إصدار تذاكر الإركاب طبقًا لما يلي: أ الدرجة. الأولى للرئيس التنفيذي ونواب الرئيس بدرجة. رجال الأعمال مدراء العموم. ت درجة. الضيافة لباقي العاملين ث يجوز. صرف قيمة التذكرة للعامل نقدًا حسب قيمة درجة السفر التي يستحقها العامل بدلاً من تأمينها بحيث، يكون التعويض بأقل سعر للفئة المستحقة للعامل، وفي حال تم إصدار تذكرة أقل من الدرجة المستحقة لعدم وجود حجز فيتم تعويض العامل بفارق السعر. ج في. حال استخدام إحدى سيارات المنشأة في السفر فإن، العامل لا يستحق تذاكر سفر على، أن تتحمل المنشأة مصاريف الوقود والصيانة. ح في. حال عدم وجود سيارة خاصة للمنشأة وعدم وجود مطار بالمدينة المنتدب إليها العامل فإن، المنشأة تصرفله ريالاً واحدًا عن الكيلو متر الواحد وذلك، من مقر المنشأة أو من أقرب مطار للمدينة المنتدب إليها حتى وصوله للمدينة المنتدب إليها ذهابًا، وإيابًا. خ يجوز. صرف قيمة التذكرة للسائق ومعاونه الذي يستخدم إحدى سيارات المنشأة في حالة نقل مواد للمنشأة، أو مرافقة الرئيس التنفيذي. 2 المتعاونون- والمستشارون غير المتفرغين والمعارون، المتفرغون: تُحدّد درجة الإركاب بحسب أحكام العقود المبرمة معهم بناء على ما يقرره صاحب الصلاحية لكل حالة على حدة. 3 يجوز- للمنشأة إصدار تذكرة إركاب للعامل أعلى من الفئة المستحقة له نظامًا عند مرافقة الضيوف الرسميين، أو مرافقة الرئيس التنفيذي. التدريب والتأهيل','[{"index":1,"marker":null,"text":"يتم-1 إصدار تذاكر الإركاب طبقًا لما يلي: أ الدرجة. الأولى للرئيس التنفيذي ونواب الرئيس بدرجة. رجال الأعمال مدراء العموم. ت درجة. الضيافة لباقي العاملين ث يجوز. صرف قيمة التذكرة للعامل نقدًا حسب قيمة درجة السفر التي يستحقها العامل بدلاً من تأمينها بحيث، يكون التعويض بأقل سعر للفئة المستحقة للعامل، وفي حال تم إصدار تذكرة أقل من الدرجة المستحقة لعدم وجود حجز فيتم تعويض العامل بفارق السعر. ج في. حال استخدام إحدى سيارات المنشأة في السفر فإن، العامل لا يستحق تذاكر سفر على، أن تتحمل المنشأة مصاريف الوقود والصيانة. ح في. حال عدم وجود سيارة خاصة للمنشأة وعدم وجود مطار بالمدينة المنتدب إليها العامل فإن، المنشأة تصرفله ريالاً واحدًا عن الكيلو متر الواحد وذلك، من مقر المنشأة أو من أقرب مطار للمدينة المنتدب إليها حتى وصوله للمدينة المنتدب إليها ذهابًا، وإيابًا. خ يجوز. صرف قيمة التذكرة للسائق ومعاونه الذي يستخدم إحدى سيارات المنشأة في حالة نقل مواد للمنشأة، أو مرافقة الرئيس التنفيذي. 2 المتعاونون- والمستشارون غير المتفرغين والمعارون، المتفرغون: تُحدّد درجة الإركاب بحسب أحكام العقود المبرمة معهم بناء على ما يقرره صاحب الصلاحية لكل حالة على حدة. 3 يجوز- للمنشأة إصدار تذكرة إركاب للعامل أعلى من الفئة المستحقة له نظامًا عند مرافقة الضيوف الرسميين، أو مرافقة الرئيس التنفيذي. التدريب والتأهيل"}]','["اركاب","تذكر","تذاكر","درج","مدين","سيار","منتدب","مرافق","اصدار","رييس"]','["broken_glyphs"]','2025-04-25','amended','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-042','policy-doc-work-regulation',NULL,'التدريب',5,42,'تتحمل المنشأة في حال قيامها بتأهيل','proposed','تتحمل المنشأة في حال قيامها بتأهيل، أو تدريب العاملين السعوديين كافة التكاليف وإذا، كان مكان التأهيل أو التدريب في غير الدائرة المكانية للمنشأة تؤمن تذاكر السفر في الذهاب والعودة، بالدرجة التي تحددها المنشأة كما، تؤمن وسائل المعيشة من مأكل ومسكن، وتنقلات، داخلية، أو تصرف للعامل بدلا عنها وتستمر، في صرف أجر العامل طوال فترة التأهيل والتدريب.،','[{"index":1,"marker":null,"text":"تتحمل المنشأة في حال قيامها بتأهيل، أو تدريب العاملين السعوديين كافة التكاليف وإذا، كان مكان التأهيل أو التدريب في غير الدائرة المكانية للمنشأة تؤمن تذاكر السفر في الذهاب والعودة، بالدرجة التي تحددها المنشأة كما، تؤمن وسائل المعيشة من مأكل ومسكن، وتنقلات، داخلية، أو تصرف للعامل بدلا عنها وتستمر، في صرف أجر العامل طوال فترة التأهيل والتدريب.،"}]','["بتاهيل","تتحمل","تدريب","قيام","تاهيل","تومن","مكان","داير","ماكل","ومسكن"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-043','policy-doc-work-regulation',NULL,'التدريب',5,43,'يجوز للمنشأة أن تُنهي عقد التأهيل','proposed','1. يجوز للمنشأة أن تُنهي عقد التأهيل، أو التدريب من غير العاملين إذا، ثبت من التقارير الصادرة عن الجهة التي تتولى التدريب، أو التأهيل عدم قابليته، أو قدرته على إكمال برامج التدريب بصورة مفيدة.
2. للمتدرب، أو الخاضع للتأهيل من غير العاملين، أو وليه، أو وصيه الحق في إنهاء التدريب، أو التأهيل إذا ثبت من التقارير الصادرة عن الجهة التي تتولى التدريب، أو التأهيل عدم قابليته، أو قدرته على إكمال برامج التدريب بصورة مفيدة.
3. وفي كلتا الحالتين السابقتين يجب على الطرف الذي يرغب في انهاء العقد إبلاغ الطرف الآخر بذلك قبل أسبوع على الأقل من تاريخ التوقف عن التدريب والتأهيل.
4. للمنشأة أن تلزم المتدرب أو الخاضع للتأهيل من غير العاملين لديه بعد- إكمال مدة التدريب أو التأهيل أن- يعمل لديها مدة مماثلة لمدة التدريب أو التأهيل.
5. للمنشأة أن تلزم المتدرب أو الخاضع للتأهيل من غير العاملين لديها بدفع تكاليف التدريب أو التأهيل التي تحملتها أو بنسبة المدة المتبقية في حالة رفضه رفض العمل المدة المماثلة او بعضها.','[{"index":1,"marker":"1","text":"يجوز للمنشأة أن تُنهي عقد التأهيل، أو التدريب من غير العاملين إذا، ثبت من التقارير الصادرة عن الجهة التي تتولى التدريب، أو التأهيل عدم قابليته، أو قدرته على إكمال برامج التدريب بصورة مفيدة."},{"index":2,"marker":"2","text":"للمتدرب، أو الخاضع للتأهيل من غير العاملين، أو وليه، أو وصيه الحق في إنهاء التدريب، أو التأهيل إذا ثبت من التقارير الصادرة عن الجهة التي تتولى التدريب، أو التأهيل عدم قابليته، أو قدرته على إكمال برامج التدريب بصورة مفيدة."},{"index":3,"marker":"3","text":"وفي كلتا الحالتين السابقتين يجب على الطرف الذي يرغب في انهاء العقد إبلاغ الطرف الآخر بذلك قبل أسبوع على الأقل من تاريخ التوقف عن التدريب والتأهيل."},{"index":4,"marker":"4","text":"للمنشأة أن تلزم المتدرب أو الخاضع للتأهيل من غير العاملين لديه بعد- إكمال مدة التدريب أو التأهيل أن- يعمل لديها مدة مماثلة لمدة التدريب أو التأهيل."},{"index":5,"marker":"5","text":"للمنشأة أن تلزم المتدرب أو الخاضع للتأهيل من غير العاملين لديها بدفع تكاليف التدريب أو التأهيل التي تحملتها أو بنسبة المدة المتبقية في حالة رفضه رفض العمل المدة المماثلة او بعضها."}]','["تاهيل","تدريب","متدرب","تنه","اكمال","خاضع","قابلي","برامج","مفيد","ثبت"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-044','policy-doc-work-regulation',NULL,'التدريب',5,44,'يجوز:أولا للمنشأة أن تشترط على الخاضع للتدريب، أو التأهيل','proposed','يجوز:أولا للمنشأة أن تشترط على الخاضع للتدريب، أو التأهيل من العاملين لديها بعد إكمال مدة التدريب أو التأهيل أن، يعمل لديها مدة لا تتجاوز المدة المماثلة لمدة برنامج التدريب أو التأهيل الذي خضع له العامل إذا، كان عقد العمل غير محددة المدة، أو باقي مدة العقد في العقود محددة المدة إذا كانت المدة المتبقية من عقد العمل أقل من المدة المماثلة لمدة برنامج التدريب. ثانيا يجوز: للمنشأة أن تُنهي تأهيل أو تدريب العامل مع، الزامه بدفع تكاليف التدريب التي تحملتها المنشأة أو بنسبة منها وذلك في الحالات التالية:
1. إذا قرر العامل إنهاء التدريب، أو التأهيل قبل الموعد المحدد لذلك دون عذر مشروع.
2. إذا تم فسخ عقد عمل العامل وفق إحدى الحالات الواردة في الثمانون(المادة من) نظام العمل عدا 6(الفقرة منها) أثناء فترة التدريب أو التأهيل.
3. إذا استقال العامل من العمل، أو تركه لغير الحالات الواردة في الحادية(المادة والثمانون من) نظام العمل أثناء فترة التدريب أو التأهيل. ثالثا يجوز: للمنشاة الزام العامل بدفع تكاليف التدريب أو التاهيل التي تحملتها المنشأة أو بنسبة منها إذا استقال العامل من العمل، أو تركه لغير الحالات الواردة في الحادية(المادة والثمانون من) نظام العمل قبل إنتهاء مدة العمل التي إشترطتها عليه المنشأة بعد إنتهاء التدريب أو التأهيل.','[{"index":1,"marker":null,"text":"يجوز:أولا للمنشأة أن تشترط على الخاضع للتدريب، أو التأهيل من العاملين لديها بعد إكمال مدة التدريب أو التأهيل أن، يعمل لديها مدة لا تتجاوز المدة المماثلة لمدة برنامج التدريب أو التأهيل الذي خضع له العامل إذا، كان عقد العمل غير محددة المدة، أو باقي مدة العقد في العقود محددة المدة إذا كانت المدة المتبقية من عقد العمل أقل من المدة المماثلة لمدة برنامج التدريب. ثانيا يجوز: للمنشأة أن تُنهي تأهيل أو تدريب العامل مع، الزامه بدفع تكاليف التدريب التي تحملتها المنشأة أو بنسبة منها وذلك في الحالات التالية:"},{"index":2,"marker":"1","text":"إذا قرر العامل إنهاء التدريب، أو التأهيل قبل الموعد المحدد لذلك دون عذر مشروع."},{"index":3,"marker":"2","text":"إذا تم فسخ عقد عمل العامل وفق إحدى الحالات الواردة في الثمانون(المادة من) نظام العمل عدا 6(الفقرة منها) أثناء فترة التدريب أو التأهيل."},{"index":4,"marker":"3","text":"إذا استقال العامل من العمل، أو تركه لغير الحالات الواردة في الحادية(المادة والثمانون من) نظام العمل أثناء فترة التدريب أو التأهيل. ثالثا يجوز: للمنشاة الزام العامل بدفع تكاليف التدريب أو التاهيل التي تحملتها المنشأة أو بنسبة منها إذا استقال العامل من العمل، أو تركه لغير الحالات الواردة في الحادية(المادة والثمانون من) نظام العمل قبل إنتهاء مدة العمل التي إشترطتها عليه المنشأة بعد إنتهاء التدريب أو التأهيل."}]','["تاهيل","تدريب","مده","اولا","تشترط","خاضع","ثمان","زام","حاد","وارد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-045','policy-doc-work-regulation',NULL,'التدريب',5,45,'التدريب والتطوير','extracted','توفر المنشأة التدريب والتطوير المهني الكفيل بخلق قوة عمل قادرة على إنجاز المهام التي تتطلبها أعمال المنشأة وأنشطته وإدخال، التطوير والتحديث المستمر عليه وجعل، ذلك حافزًا','[{"index":1,"marker":null,"text":"توفر المنشأة التدريب والتطوير المهني الكفيل بخلق قوة عمل قادرة على إنجاز المهام التي تتطلبها أعمال المنشأة وأنشطته وإدخال، التطوير والتحديث المستمر عليه وجعل، ذلك حافزًا"}]','["تطوير","تدريب","بخلق","قادر","وانشط","وادخال","تحديث","وجعل","حافزا","كفيل"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-046','policy-doc-work-regulation',NULL,'الأجور',6,46,'مع مراعاة أي إجراءات','proposed','مع مراعاة أي إجراءات، أو ترتيبات ينص عليها برنامج حماية الأجور؛ تدفع أجور العمال بالعملة الرسمية للبلاد في مواعيد استحقاقها وتودع، في حسابات العمال عن طريق البنوك المعتمدة في المملكة.','[{"index":1,"marker":null,"text":"مع مراعاة أي إجراءات، أو ترتيبات ينص عليها برنامج حماية الأجور؛ تدفع أجور العمال بالعملة الرسمية للبلاد في مواعيد استحقاقها وتودع، في حسابات العمال عن طريق البنوك المعتمدة في المملكة."}]','["مراعا","اجراء","اجور","حما","بلاد","بنو","عمال","ترتيب","ينص","برنامج"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-047','policy-doc-work-regulation',NULL,'الأجور',6,47,'تدفع أجور الساعات الإضافية المستحقة للعامل في نهاية الشهر','proposed','تدفع أجور الساعات الإضافية المستحقة للعامل في نهاية الشهر الذي تم فيه التكليف.','[{"index":1,"marker":null,"text":"تدفع أجور الساعات الإضافية المستحقة للعامل في نهاية الشهر الذي تم فيه التكليف."}]','["تدفع","اجور","ساع","اضاف","مستحق","نها","شهر","تكليف","فيه","الذ"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-048','policy-doc-work-regulation',NULL,'الأجور',6,48,'إذا وافق يوم دفع الأجور يوم الراحة الأسبوعية','proposed','إذا وافق يوم دفع الأجور يوم الراحة الأسبوعية، أو عطلة رسمية يتم الدفع في يوم العمل السابق.','[{"index":1,"marker":null,"text":"إذا وافق يوم دفع الأجور يوم الراحة الأسبوعية، أو عطلة رسمية يتم الدفع في يوم العمل السابق."}]','["دفع","وافق","يوم","راح","اجور","اسبوع","عطل","رسم","سابق","يتم"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-049','policy-doc-work-regulation',NULL,'الأجور',6,49,'مستويات الأجور','extracted','1 تمنح. المنشأة أجورًا مناسبة وكفيله، بجذب الكفاءات اللازمة لتسيير أعماله والحفاظ على لعامليه وتحفيزهم، على الإنتاجية وبما، يتناسب مع مستوى المعيشة في المملكة العربية السعودية. 2 تتولى. إدارة الموارد البشرية رصد مستويات الأجور دوريًا ومتابعة، التغيرات في مستوى المعيشة في المملكة العربية السعودية وتقدم، توصياتها لصاحب الصلاحية بشأن التعديلات المناسبة للأجور والبدلات. 3 تحتفظ. إدارة الموارد البشرية بكافة بيانات الرواتب وتتولى، إدارة الموارد البشرية والإدارة المالية مسؤولية المحافظة على السرية التامة عن معلومات الرواتب.','[{"index":1,"marker":null,"text":"1 تمنح. المنشأة أجورًا مناسبة وكفيله، بجذب الكفاءات اللازمة لتسيير أعماله والحفاظ على لعامليه وتحفيزهم، على الإنتاجية وبما، يتناسب مع مستوى المعيشة في المملكة العربية السعودية. 2 تتولى. إدارة الموارد البشرية رصد مستويات الأجور دوريًا ومتابعة، التغيرات في مستوى المعيشة في المملكة العربية السعودية وتقدم، توصياتها لصاحب الصلاحية بشأن التعديلات المناسبة للأجور والبدلات. 3 تحتفظ. إدارة الموارد البشرية بكافة بيانات الرواتب وتتولى، إدارة الموارد البشرية والإدارة المالية مسؤولية المحافظة على السرية التامة عن معلومات الرواتب."}]','["مستوي","اجور","معيش","عرب","رواتب","مستو","سعود","مملك","ادار","موارد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-050','policy-doc-work-regulation',NULL,'الأجور',6,50,'قواعد وإجراءات دفع الأجور','extracted','1 تُدفع. جميع مستحقات العاملين من الأجر الأساسي والبدلات والمكافآت بالريال السعودي ولغرض، احتساب الحقوق المالية يعد (الشهر 30 يومًا.) 2 يُدفع. أجر العامل ومستحقاته كافة حال انتهاء خدمته ووفائه، بالتزاماته المالية والعينية تجاه المنشأة خلال مدة أقصاها 7( أيام) أما، إذا كان العامل هو الذي أنهى العقد وجب على المنشأة تصفية حقوقه كاملة خلال مدة (أقصاها 14 يوم.) 3 يبدأ. احتساب الأجر للعامل المعين اعتبارًا من تاريخ مباشرته للعمل ولا، يستحق أجرًا عن الأيام التي لم يباشر فيها العمل. 4 تخضع. الأجور للحسميات والخصومات المحددة في هذه اللائحة ولنظام، العمل ولائحته التنفيذية. 5 عند. حساب كل من الأجور والبدلات، والمكافآت، والتعويضات، والحسميات، المنصوص عليها في هذه اللائحة؛ تُقرّب القيمة إلى أقرب ريال بالزيادة.','[{"index":1,"marker":null,"text":"1 تُدفع. جميع مستحقات العاملين من الأجر الأساسي والبدلات والمكافآت بالريال السعودي ولغرض، احتساب الحقوق المالية يعد (الشهر 30 يومًا.) 2 يُدفع. أجر العامل ومستحقاته كافة حال انتهاء خدمته ووفائه، بالتزاماته المالية والعينية تجاه المنشأة خلال مدة أقصاها 7( أيام) أما، إذا كان العامل هو الذي أنهى العقد وجب على المنشأة تصفية حقوقه كاملة خلال مدة (أقصاها 14 يوم.) 3 يبدأ. احتساب الأجر للعامل المعين اعتبارًا من تاريخ مباشرته للعمل ولا، يستحق أجرًا عن الأيام التي لم يباشر فيها العمل. 4 تخضع. الأجور للحسميات والخصومات المحددة في هذه اللائحة ولنظام، العمل ولائحته التنفيذية. 5 عند. حساب كل من الأجور والبدلات، والمكافآت، والتعويضات، والحسميات، المنصوص عليها في هذه اللائحة؛ تُقرّب القيمة إلى أقرب ريال بالزيادة."}]','["اجور","ريال","حسمي","واجراء","دفع","اقصا","قواعد","مكاف","احتساب","حقوق"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-051','policy-doc-work-regulation',NULL,'الأجور',6,51,'الحسومات من أجر العامل','extracted','لا يجوز حسم أي مبلغ من أجور العامل لقاء حقوقه دون موافقة خطيّة منه الا في الحلالات التالية: من% أجره. 1 استرداد- قروض صاحب العمل بشرط، الاّ يزيد ما يحسم من العام في هذه الحالة على 10 2 اشتراكات- التأمينات الاجتماعية المستحقة على العامل ومقررة نظامًا. اشتراكت-3 العامل في صندوق الادخار والقروض المستحقة للصندوق. 4 أقساط- أي مشروع يقوم به صاحب العمل لبناء المساكن بقصد تمليكها للعمال أو أي¡ مزيّة أخرى. 5 الغرامات- التي توقع على العامل بسبب المخالفات التي يرتكبها وكذلك، المبلغ الذي يقتطع منه مقابل ما أتلفه. 6 استيفاء- دين إنفاذًا لأي¡ حكم قضائي على، الا يزيد ما يحسم شهريًا لقاء ذلك على ربع الاجر المستحق للعامل ما لم يتضمن الحكم خلاف ذلك.','[{"index":1,"marker":null,"text":"لا يجوز حسم أي مبلغ من أجور العامل لقاء حقوقه دون موافقة خطيّة منه الا في الحلالات التالية: من% أجره. 1 استرداد- قروض صاحب العمل بشرط، الاّ يزيد ما يحسم من العام في هذه الحالة على 10 2 اشتراكات- التأمينات الاجتماعية المستحقة على العامل ومقررة نظامًا. اشتراكت-3 العامل في صندوق الادخار والقروض المستحقة للصندوق. 4 أقساط- أي مشروع يقوم به صاحب العمل لبناء المساكن بقصد تمليكها للعمال أو أي¡ مزيّة أخرى. 5 الغرامات- التي توقع على العامل بسبب المخالفات التي يرتكبها وكذلك، المبلغ الذي يقتطع منه مقابل ما أتلفه. 6 استيفاء- دين إنفاذًا لأي¡ حكم قضائي على، الا يزيد ما يحسم شهريًا لقاء ذلك على ربع الاجر المستحق للعامل ما لم يتضمن الحكم خلاف ذلك."}]','["حسوم","لقاء","قروض","صندوق","يحسم","مستحق","يزيد","مبلغ","حكم","منه"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-052','policy-doc-work-regulation',NULL,'تقارير الأداء',7,52,'تُعِدُ المنشأة تقارير عن الأداء بصفة دورية مرة','proposed','تُعِدُ المنشأة تقارير عن الأداء بصفة دورية مرة، كل سنة على الأقل لجميع العاملين وفقًا للنماذج التي تضعها لذلك؛ على أن تتضمن العناصر التالية:
1. المقدرة على العمل ودرجة، (إتقانه ).الكفاءة
2. سلوك العامل ومدى، تعاونه مع رؤسائه وزملائه، وعملاء، المنشأة.
3. المواظبة.','[{"index":1,"marker":null,"text":"تُعِدُ المنشأة تقارير عن الأداء بصفة دورية مرة، كل سنة على الأقل لجميع العاملين وفقًا للنماذج التي تضعها لذلك؛ على أن تتضمن العناصر التالية:"},{"index":2,"marker":"1","text":"المقدرة على العمل ودرجة، (إتقانه ).الكفاءة"},{"index":3,"marker":"2","text":"سلوك العامل ومدى، تعاونه مع رؤسائه وزملائه، وعملاء، المنشأة."},{"index":4,"marker":"3","text":"المواظبة."}]','["بصف","مره","تعد","تقارير","دور","اداء","عناصر","مقدر","اتق","روسا"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-053','policy-doc-work-regulation',NULL,'تقارير الأداء',7,53,'يُقيّمُ أداء العامل في التقرير بالتقديرات التي تحددها المنشأة','proposed','يُقيّمُ أداء العامل في التقرير بالتقديرات التي تحددها المنشأة؛ على أن يتبع في ذلك مقياسٌ من خمسة مستويات.','[{"index":1,"marker":null,"text":"يُقيّمُ أداء العامل في التقرير بالتقديرات التي تحددها المنشأة؛ على أن يتبع في ذلك مقياسٌ من خمسة مستويات."}]','["يقيم","تقدير","تقرير","اداء","تحدد","يتبع","مقياس","مستوي","خمس"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-054','policy-doc-work-regulation',NULL,'تقارير الأداء',7,54,'يُعدّ التقرير بمعرفة الرئيس المباشر للعامل','proposed','يُعدّ التقرير بمعرفة الرئيس المباشر للعامل؛ على أن يعتمد (من صاحب الصلاحية ويُخطر)، العامل بصورة من التقرير فور اعتماده ويحق، للعامل أن يتظلم من التقرير وفقًا لقواعد التظلم المنصوص عليها في هذه اللائحة.','[{"index":1,"marker":null,"text":"يُعدّ التقرير بمعرفة الرئيس المباشر للعامل؛ على أن يعتمد (من صاحب الصلاحية ويُخطر)، العامل بصورة من التقرير فور اعتماده ويحق، للعامل أن يتظلم من التقرير وفقًا لقواعد التظلم المنصوص عليها في هذه اللائحة."}]','["بمعرف","تقرير","يعد","رييس","مباشر","ويحق","لقواعد","بصور","يعتمد","ويخطر"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-055','policy-doc-work-regulation',NULL,'تقارير الأداء',7,55,'يُقيّم أداء العامل لدى المنشأة من خلال نموذج لتقويم','proposed','يُقيّم أداء العامل لدى المنشأة من خلال نموذج لتقويم الأداء الوظيفي يقيس، مستوى أدائه واجبات وظيفته وسلوكه، وتقدير مدى صلاحيته في الاستمرار في شغل الوظيفة ومدى، قدرته على القيام بمسؤوليات أعلى؛ وذلك وفقًا لعناصر ومعايير تُعدّها إدارة الموارد البشرية ويعتمدها، صاحب الصلاحية؛ وذلك لضمان ضبط أداء العاملين في المنشأة كافة. العلاوات','[{"index":1,"marker":null,"text":"يُقيّم أداء العامل لدى المنشأة من خلال نموذج لتقويم الأداء الوظيفي يقيس، مستوى أدائه واجبات وظيفته وسلوكه، وتقدير مدى صلاحيته في الاستمرار في شغل الوظيفة ومدى، قدرته على القيام بمسؤوليات أعلى؛ وذلك وفقًا لعناصر ومعايير تُعدّها إدارة الموارد البشرية ويعتمدها، صاحب الصلاحية؛ وذلك لضمان ضبط أداء العاملين في المنشأة كافة. العلاوات"}]','["لتقويم","اداء","يقيم","نموذج","وظيف","لدي","خلال","يقيس","وسلوك","مدي"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-056','policy-doc-work-regulation',NULL,'العلاوات والمكافآت',8,56,'يجوز للمنشأة منح العاملين علاوات سنوية يتم','proposed','1. يجوز للمنشأة منح العاملين علاوات سنوية يتم، تحديد نسبتها بناءً على ضوء المركز المالي للمنشأة.
2. يكون العامل مؤهلاً لاستحقاق العلاوة متى حصل في تقريره الدوري على مستوى متوسط على الأقل في النموذج الذي تضعه المنشأة وذلك، بعد مضي سنة كاملة من تاريخ التحاقه بالعمل، أو من تاريخ حصوله على العلاوة السابقة.
3. يجوز لإدارة المنشأة منح العامل علاوة استثنائية وفقًا للضوابط التي تضعها في هذا الشأن.','[{"index":1,"marker":"1","text":"يجوز للمنشأة منح العاملين علاوات سنوية يتم، تحديد نسبتها بناءً على ضوء المركز المالي للمنشأة."},{"index":2,"marker":"2","text":"يكون العامل مؤهلاً لاستحقاق العلاوة متى حصل في تقريره الدوري على مستوى متوسط على الأقل في النموذج الذي تضعه المنشأة وذلك، بعد مضي سنة كاملة من تاريخ التحاقه بالعمل، أو من تاريخ حصوله على العلاوة السابقة."},{"index":3,"marker":"3","text":"يجوز لإدارة المنشأة منح العامل علاوة استثنائية وفقًا للضوابط التي تضعها في هذا الشأن."}]','["علاو","منح","سنو","يتم","تضع","لاستحقاق","حصل","موهلا","متوسط","تحاق"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-057','policy-doc-work-regulation',NULL,'العلاوات والمكافآت',8,57,'بشكل يؤدي إلى زيادة','extracted','تحرص المنشأة على منح الزيادات والمكافآت، للعاملين الذي يثبتون نشاطًا وإخلاصًا، وكفاءة،؛ الإنتاجية، أو الذين يؤدون أعمالاً استثنائية إضافة، إلى أعمالهم العادية وضمن، حدود اختصاصاتهم، أو الذين يستحدثون أساليب وتنظيمات جديدة في العمل؛ ممّا يؤدي إلى رفع الكفاءة والطاقة الإنتاجية.','[{"index":1,"marker":null,"text":"تحرص المنشأة على منح الزيادات والمكافآت، للعاملين الذي يثبتون نشاطًا وإخلاصًا، وكفاءة،؛ الإنتاجية، أو الذين يؤدون أعمالاً استثنائية إضافة، إلى أعمالهم العادية وضمن، حدود اختصاصاتهم، أو الذين يستحدثون أساليب وتنظيمات جديدة في العمل؛ ممّا يؤدي إلى رفع الكفاءة والطاقة الإنتاجية."}]','["يود","زياد","انتاج","بشكل","ذين","تحرص","واخلاصا","وكفاء","اعمالا","وضمن"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-058','policy-doc-work-regulation',NULL,'العلاوات والمكافآت',8,58,'المكافآت المعنوية','extracted','يجوز للرئيس التنفيذي مكافأة العاملين معنويًا بأحد الأشكال الآتية: 1 خطاب- شكر وتقدير 2 منح- إجازة إضافية بأجر لا، (تتجاوز 5 خمسة) أيام عمل في السنة.','[{"index":1,"marker":null,"text":"يجوز للرئيس التنفيذي مكافأة العاملين معنويًا بأحد الأشكال الآتية: 1 خطاب- شكر وتقدير 2 منح- إجازة إضافية بأجر لا، (تتجاوز 5 خمسة) أيام عمل في السنة."}]','["معنو","مكاف","معنويا","خطاب","شكر","باحد","وتقدير","اشكال","منح","اضاف"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-059','policy-doc-work-regulation',NULL,'العلاوات والمكافآت',8,59,'المكافآت المادية','extracted','يكون-1 الأجر الفعلي أساسًا لحساب مقدار هذه المكافأة. يُصرف-2 للرئيس التنفيذي ونواب الرئيس التنفيذي مكافأة في نهاية السنة بناء، على تقدير وموافقة رئيس مجلس الادارة حسب( ما ورد في جدول مزايا وبدلات ).العاملين 3 يجوز- للرئيس التنفيذي أن يصرف لأي من لعاملي المنشأة مكافأة تشجيعية مقطوعة بما لا يتجاوز (مقدار 4 أربعة) رواتب من الأجر الفعلي (الشهري حسب ما ورد في جدول مزايا وبدلات ).العاملين','[{"index":1,"marker":null,"text":"يكون-1 الأجر الفعلي أساسًا لحساب مقدار هذه المكافأة. يُصرف-2 للرئيس التنفيذي ونواب الرئيس التنفيذي مكافأة في نهاية السنة بناء، على تقدير وموافقة رئيس مجلس الادارة حسب( ما ورد في جدول مزايا وبدلات ).العاملين 3 يجوز- للرئيس التنفيذي أن يصرف لأي من لعاملي المنشأة مكافأة تشجيعية مقطوعة بما لا يتجاوز (مقدار 4 أربعة) رواتب من الأجر الفعلي (الشهري حسب ما ورد في جدول مزايا وبدلات ).العاملين"}]','["رييس","جدول","مقدار","مكافا","ورد","وبدل","مكاف","يصرف","مزايا","تنفيذ"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-060','policy-doc-work-regulation',NULL,'العلاوات والمكافآت',8,60,'الزيادات','extracted','يكون الأجر الفعلي أساسًا لحساب مقدار الزيادة وللرئيس، التنفيذي الصلاحية بزيادة أي عامل وبالنسبة التي يقدرها ويراها مناسبة وتكون، بناء على نماذج من إدارة الموارد البشرية توضح، أسباب الزيادة ومقدارها مع، اعتماد مدير الإدارة المعنية واعتماد، الرئيس التنفيذي.','[{"index":1,"marker":null,"text":"يكون الأجر الفعلي أساسًا لحساب مقدار الزيادة وللرئيس، التنفيذي الصلاحية بزيادة أي عامل وبالنسبة التي يقدرها ويراها مناسبة وتكون، بناء على نماذج من إدارة الموارد البشرية توضح، أسباب الزيادة ومقدارها مع، اعتماد مدير الإدارة المعنية واعتماد، الرئيس التنفيذي."}]','["زياد","رييس","بزياد","وبالنسب","يقدر","ويرا","توضح","واعتماد","مقدار","ومقدار"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-061','policy-doc-work-regulation',NULL,'الترقيات',9,61,'المهني السعودي ودرجة- كل وظيفة وشروط','proposed','المهني السعودي ودرجة- كل وظيفة وشروط، شغلها وبداية، أجرها فيه ويكون، العامل مؤهلاً للترقية إلى وظيفة أعلى؛ تضع المنشأة سلما وظيفيا لوظائفها تحدد فيه عدد ومسميات، الوظائف وفقًا- لما جاء في دليل التصنيف والتوصيف، متى توفرت الشروط التالية:
1. وجود الوظيفة الشاغرة الأعلى.
2. توافر مؤهلات شغل الوظيفة المرشح للترقية إليها.
3. حصوله على مستوى فوق المتوسط على الأقل في آخر تقرير دوري.
4. موافقة صاحب الصلاحية.
5. يجوز لإدارة المنشأة منح العامل ترقية استثنائية؛ وفقًا للضوابط التي تضعها في هذا الشأن.','[{"index":1,"marker":null,"text":"المهني السعودي ودرجة- كل وظيفة وشروط، شغلها وبداية، أجرها فيه ويكون، العامل مؤهلاً للترقية إلى وظيفة أعلى؛ تضع المنشأة سلما وظيفيا لوظائفها تحدد فيه عدد ومسميات، الوظائف وفقًا- لما جاء في دليل التصنيف والتوصيف، متى توفرت الشروط التالية:"},{"index":2,"marker":"1","text":"وجود الوظيفة الشاغرة الأعلى."},{"index":3,"marker":"2","text":"توافر مؤهلات شغل الوظيفة المرشح للترقية إليها."},{"index":4,"marker":"3","text":"حصوله على مستوى فوق المتوسط على الأقل في آخر تقرير دوري."},{"index":5,"marker":"4","text":"موافقة صاحب الصلاحية."},{"index":6,"marker":"5","text":"يجوز لإدارة المنشأة منح العامل ترقية استثنائية؛ وفقًا للضوابط التي تضعها في هذا الشأن."}]','["وشروط","ودرج","وظيف","ترق","مهن","سعود","شغل","تضع","وبدا","سلما"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-062','policy-doc-work-regulation',NULL,'الترقيات',9,62,'فإن المفاضلة للترقية تكون كالآتي','proposed','فإن المفاضلة للترقية تكون كالآتي: إذا توافرت شروط الترقية لوظيفة أعلى في أكثر من عامل؛
1. ترشيح صاحب الصلاحية.
2. الحاصل على تقدير أعلى.
3. الحاصل على شهادات علمية أعلى، أو دورات تدريبية أكثر.
4. الأكثر خبرة عملية بمجال عمل المنشأة.
5. الأقدمية في العمل بالمنشأة.','[{"index":1,"marker":null,"text":"فإن المفاضلة للترقية تكون كالآتي: إذا توافرت شروط الترقية لوظيفة أعلى في أكثر من عامل؛"},{"index":2,"marker":"1","text":"ترشيح صاحب الصلاحية."},{"index":3,"marker":"2","text":"الحاصل على تقدير أعلى."},{"index":4,"marker":"3","text":"الحاصل على شهادات علمية أعلى، أو دورات تدريبية أكثر."},{"index":5,"marker":"4","text":"الأكثر خبرة عملية بمجال عمل المنشأة."},{"index":6,"marker":"5","text":"الأقدمية في العمل بالمنشأة."}]','["ترق","مفاضل","حاصل","فان","اكثر","اتي","اعل","توافرت","لوظيف","ترشيح"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-063','policy-doc-work-regulation',NULL,'الانتداب',10,63,'إذا تم انتداب العامل لأداء عمل خارج مقر عمله','proposed','إذا تم انتداب العامل لأداء عمل خارج مقر عمله تلتزم المنشأة بما يلي:
1. تؤمن للعامل وسائل التنقل اللازمة مالم، يتم صرف مقابل لها بموافقته.
2. يصرف للعامل مقابل للتكاليف التي يتكبدها للسكن والطعام، وما، إلى ذلك؛ ما لم تؤمنها له المنشأة.
3. قيمة البدل اليومي للانتداب حسب درجة العامل. ويجب أن تحدد تلك الالتزامات في قرار الانتداب؛ وفقًا للفئات والضوابط، التي تضعها المنشأة في هذا الشأن ويكون، احتساب تلك النفقات من وقت مغادرة العامل لمقر عمله إلى وقت عودته؛ وفق المدة المحددة له من قبل المنشأة.','[{"index":1,"marker":null,"text":"إذا تم انتداب العامل لأداء عمل خارج مقر عمله تلتزم المنشأة بما يلي:"},{"index":2,"marker":"1","text":"تؤمن للعامل وسائل التنقل اللازمة مالم، يتم صرف مقابل لها بموافقته."},{"index":3,"marker":"2","text":"يصرف للعامل مقابل للتكاليف التي يتكبدها للسكن والطعام، وما، إلى ذلك؛ ما لم تؤمنها له المنشأة."},{"index":4,"marker":"3","text":"قيمة البدل اليومي للانتداب حسب درجة العامل. ويجب أن تحدد تلك الالتزامات في قرار الانتداب؛ وفقًا للفئات والضوابط، التي تضعها المنشأة في هذا الشأن ويكون، احتساب تلك النفقات من وقت مغادرة العامل لمقر عمله إلى وقت عودته؛ وفق المدة المحددة له من قبل المنشأة."}]','["انتداب","لاداء","مقر","خارج","تومن","وقت","مقابل","تلك","يتكبد","لمقر"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-064','policy-doc-work-regulation',NULL,'الانتداب',10,64,'قرار الانتداب','extracted','توفر. المنشأة للعامل الذي يُنتدب لمهمة خارج مقر عمله المتطلبات اللازمة لأداء المهمة وباستثناء، الحالات المستعجلة التي يرجع تقديرها إلى صاحب الصلاحية يجب، أن يتضمن قرار الانتداب تحديد المهمة والمدة، اللازمة لأدائها، لاإ بجومب رارق؛ وتاريخ بدايتها ونهايتها. ولا يجوز تمديد مدة الانتداب إلا بعد بحث ما أنجزه من المهمة وما، بقي منها والتثب¤ت، من أن المُنتدَب قد بذل جهده في إتمام العمل في المدة التي انقضت. ولا يجوز تمديدها لأكثر من أسبوعين يصدر من صاحب الصلاحية. لا. يجوز انتداب العامل للعمل خارج مقر عمله إذا كان من الممكن أن يؤدي المهمة أحد العاملين لدى المنشأة الموجودين( في النطاق الذي تقع فيه تلك ).المهمة يستحق. العامل البدل المقرر للانتداب إذا كانت المسافة بين مكان أداء المهمة ومقر العمل لا تقل عن 75 كيلومترًا بالنسبة، للطرق المسفلتة، أو 40 كم للطرق غير المسفلتة، أو 15 كم للطرق الوعرة التي لا تصلها السيارات.','[{"index":1,"marker":null,"text":"توفر. المنشأة للعامل الذي يُنتدب لمهمة خارج مقر عمله المتطلبات اللازمة لأداء المهمة وباستثناء، الحالات المستعجلة التي يرجع تقديرها إلى صاحب الصلاحية يجب، أن يتضمن قرار الانتداب تحديد المهمة والمدة، اللازمة لأدائها، لاإ بجومب رارق؛ وتاريخ بدايتها ونهايتها. ولا يجوز تمديد مدة الانتداب إلا بعد بحث ما أنجزه من المهمة وما، بقي منها والتثب¤ت، من أن المُنتدَب قد بذل جهده في إتمام العمل في المدة التي انقضت. ولا يجوز تمديدها لأكثر من أسبوعين يصدر من صاحب الصلاحية. لا. يجوز انتداب العامل للعمل خارج مقر عمله إذا كان من الممكن أن يؤدي المهمة أحد العاملين لدى المنشأة الموجودين( في النطاق الذي تقع فيه تلك ).المهمة يستحق. العامل البدل المقرر للانتداب إذا كانت المسافة بين مكان أداء المهمة ومقر العمل لا تقل عن 75 كيلومترًا بالنسبة، للطرق المسفلتة، أو 40 كم للطرق غير المسفلتة، أو 15 كم للطرق الوعرة التي لا تصلها السيارات."}]','["انتداب","مهم","طرق","مسفل","قرار","مقر","تمديد","لازم","مده","خارج"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-065','policy-doc-work-regulation',NULL,'الانتداب',10,65,'ضوابط صرف بدل الانتداب','extracted','تصرف المنشأة بدل الانتداب وفقًا للضوابط والفئات التالية: البدلات والمزايا الرئيس التنفيذي نواب الرئيس مدراء العموم للعاملين بدل -انتداب لسفريات -الاعمال والتدريب - خارج المملكة بدل -انتداب لسفريات -الاعمال والتدريب - داخل المملكة ملاحظة* المبالغ/ المذكورة تصرف عن اليوم الواحد. يُصرف- للعامل المنتدب داخل / خارج المملكة عن كل يوم فعلي يقضيه خارج مقر عمله ويبدأ، حساب هذا البدل من يوم الانتداب الفعلي الذي يُحدّد في قرار الانتداب وينتهي، بانتهاء مدته، يخفض- بدل الانتداب إلى الربع إذا وفرت المنشأة للعامل المنتدب السكن ووسيلة التنقل أما، إذا أمن له السكن فقط فيخفض، البدل إلى النصف ولا، يتأثر البدل في حال وفرت المنشأة له السكن مؤقتًا، أو حصوله على السكن ووسيلة التنقل من أية جهة غير المنشأة؛ ما لم تحتسب التكاليف على المنشأة. يصرف- للعامل المنتدب خارج المملكة تكاليف علاجه في حال عدم تغطية التأمين الصحي لهذا العلاج على، أن تؤخذ موافقة المنشأة على هذه التكاليف قبل البدء بها. يصرف- للعامل المنتدب داخل المملكة أو خارجها تذكرة إركاب بالطائرة ذهابًا وإيابًا. في- حال تطلب وصول العامل إلى جهة الانتداب مصاريف أخرى لازمة فتتحملالمنشأة، التعويض عنها بالإضافة إلى أي تكاليف رسوم أخرى تستوجب إنهاء المهمة على، سبيل المثال رسوم: إصدار تأشيرات السفر الفحوصات، الطبية، رسوم المطارات تكاليف، استئجار أماكن أداء المهمة ولا، يتم التعويض إلا بموجب الوثائق والمستندات الأصلية المثبتة لذلك على، أن يتم أخذ الموافقة عليها مبدئيا إلا في الحالات الطارئة. يجوز- تعويض العامل عن قيمة تذاكر السفر حسب الدرجة المخصصة له بموجب أحكام الإركاب الواردة في هذه اللائحة وذلك، في حال تم تكليف العامل المنتدب من مدير إدارة الموارد البشرية بتأمين وسيلة سفره.','[{"index":1,"marker":null,"text":"تصرف المنشأة بدل الانتداب وفقًا للضوابط والفئات التالية: البدلات والمزايا الرئيس التنفيذي نواب الرئيس مدراء العموم للعاملين بدل -انتداب لسفريات -الاعمال والتدريب - خارج المملكة بدل -انتداب لسفريات -الاعمال والتدريب - داخل المملكة ملاحظة* المبالغ/ المذكورة تصرف عن اليوم الواحد. يُصرف- للعامل المنتدب داخل / خارج المملكة عن كل يوم فعلي يقضيه خارج مقر عمله ويبدأ، حساب هذا البدل من يوم الانتداب الفعلي الذي يُحدّد في قرار الانتداب وينتهي، بانتهاء مدته، يخفض- بدل الانتداب إلى الربع إذا وفرت المنشأة للعامل المنتدب السكن ووسيلة التنقل أما، إذا أمن له السكن فقط فيخفض، البدل إلى النصف ولا، يتأثر البدل في حال وفرت المنشأة له السكن مؤقتًا، أو حصوله على السكن ووسيلة التنقل من أية جهة غير المنشأة؛ ما لم تحتسب التكاليف على المنشأة. يصرف- للعامل المنتدب خارج المملكة تكاليف علاجه في حال عدم تغطية التأمين الصحي لهذا العلاج على، أن تؤخذ موافقة المنشأة على هذه التكاليف قبل البدء بها. يصرف- للعامل المنتدب داخل المملكة أو خارجها تذكرة إركاب بالطائرة ذهابًا وإيابًا. في- حال تطلب وصول العامل إلى جهة الانتداب مصاريف أخرى لازمة فتتحملالمنشأة، التعويض عنها بالإضافة إلى أي تكاليف رسوم أخرى تستوجب إنهاء المهمة على، سبيل المثال رسوم: إصدار تأشيرات السفر الفحوصات، الطبية، رسوم المطارات تكاليف، استئجار أماكن أداء المهمة ولا، يتم التعويض إلا بموجب الوثائق والمستندات الأصلية المثبتة لذلك على، أن يتم أخذ الموافقة عليها مبدئيا إلا في الحالات الطارئة. يجوز- تعويض العامل عن قيمة تذاكر السفر حسب الدرجة المخصصة له بموجب أحكام الإركاب الواردة في هذه اللائحة وذلك، في حال تم تكليف العامل المنتدب من مدير إدارة الموارد البشرية بتأمين وسيلة سفره."}]','["انتداب","بدل","منتدب","رسوم","مملك","تكاليف","خارج","سكن","يصرف","لسفري"]','["clause_reflow"]','2025-04-25','amended','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-066','policy-doc-work-regulation',NULL,'المزايا والبدلات',11,66,'تؤمن المنشأة لعمالها السكن المناسب وكذلك','proposed','تؤمن المنشأة لعمالها السكن المناسب وكذلك، وسيلة النقل إذا نُص على ذلك في عقد العمل ويجوز، النص في عقد العمل على أن تدفع المنشأة للعامل بدل سكن وبدل، نقل نقدي.','[{"index":1,"marker":null,"text":"تؤمن المنشأة لعمالها السكن المناسب وكذلك، وسيلة النقل إذا نُص على ذلك في عقد العمل ويجوز، النص في عقد العمل على أن تدفع المنشأة للعامل بدل سكن وبدل، نقل نقدي."}]','["لعمال","وكذل","سكن","تومن","مناسب","نقل","عقد","وبدل","نقد","النص"]','[]','2025-04-25','replaced','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-067','policy-doc-work-regulation',NULL,'المزايا والبدلات',11,67,'بدل السكن','extracted','استثناءً صرفه- للعامل مقدمًا بشرط، أن يكون – 1 يدفع. بدل السكن مُجزّأً على أشهر السنة ويجوز، لصاحب الصلاحية العامل قد تجاوز فترة التجربة من% الأجر الأساسي شهريًا. 2 تدفع. المنشأة بدل السكن بمعدل 25','[{"index":1,"marker":null,"text":"استثناءً صرفه- للعامل مقدمًا بشرط، أن يكون – 1 يدفع. بدل السكن مُجزّأً على أشهر السنة ويجوز، لصاحب الصلاحية العامل قد تجاوز فترة التجربة من% الأجر الأساسي شهريًا. 2 تدفع. المنشأة بدل السكن بمعدل 25"}]','["سكن","بدل","مجزا","بمعدل","مقدما","تجاوز","شهريا","اشهر","استثناء","بشرط"]','[]','2025-04-25','replaced','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-068','policy-doc-work-regulation',NULL,'المزايا والبدلات',11,68,'بدل النقل','extracted','دون الاخلال بما هو متفق عليه في عقد العمل، يراعى في بدل النقل ما يلي: 1 يُدفع. بدل النقل أثناء تمتع العامل بالإجازة السنوية، أو أية إجازات أخرى مدفوعة الأجر ويُدفع، له أثناء عطل المنشأة الرسمية. 2 لا. يُدفع بدل النقل عندما توفر المنشأة وسيلة النقل، أو يخصص إحدى سياراته لاستعمال العامل. 3 لا. يُدفع بدل النقل عندما يكون العامل مقيمًا في الوحدات السكنية الموجودة في مواقع العمل.','[{"index":1,"marker":null,"text":"دون الاخلال بما هو متفق عليه في عقد العمل، يراعى في بدل النقل ما يلي: 1 يُدفع. بدل النقل أثناء تمتع العامل بالإجازة السنوية، أو أية إجازات أخرى مدفوعة الأجر ويُدفع، له أثناء عطل المنشأة الرسمية. 2 لا. يُدفع بدل النقل عندما توفر المنشأة وسيلة النقل، أو يخصص إحدى سياراته لاستعمال العامل. 3 لا. يُدفع بدل النقل عندما يكون العامل مقيمًا في الوحدات السكنية الموجودة في مواقع العمل."}]','["نقل","بدل","يدفع","عندما","اثناء","ويدفع","لاستعمال","مقيما","وحد","مدفوع"]','[]','2025-04-25','replaced','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-069','policy-doc-work-regulation',NULL,'المزايا والبدلات',11,69,'بدل الانتقال إلى مدينة أخرى لغرض العمل','extracted','العامل الذي ينقل من مدينة إلى مدينة أخرى بقصد العمل لمدة لا تقل عن سنة يصرف، له ما يعادل أجر أساسي لشهر واحد باعتبار، ذلك مقابل نفقات انتقاله وعائلته ما، لم يكن النقل بناءً على طلبه.','[{"index":1,"marker":null,"text":"العامل الذي ينقل من مدينة إلى مدينة أخرى بقصد العمل لمدة لا تقل عن سنة يصرف، له ما يعادل أجر أساسي لشهر واحد باعتبار، ذلك مقابل نفقات انتقاله وعائلته ما، لم يكن النقل بناءً على طلبه."}]','["مدين","انتقال","لغرض","لشهر","باعتبار","وعايل","بدل","اخر","ينقل","بقصد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-070','policy-doc-work-regulation',NULL,'المزايا والبدلات',11,70,'صرف بدل أو مكافأة أو تعويض أخرى','extracted','يجوز للرئيس التنفيذي بناءً على موافقة رئيس المجلس صرف مزايا ومنافع للعاملي المنشأة وفقًا، لمصفوفة المزايا والمنافع (المرفقة مرفق 1 ).','[{"index":1,"marker":null,"text":"يجوز للرئيس التنفيذي بناءً على موافقة رئيس المجلس صرف مزايا ومنافع للعاملي المنشأة وفقًا، لمصفوفة المزايا والمنافع (المرفقة مرفق 1 )."}]','["مرفق","صرف","مزايا","مكافا","تعويض","رييس","ومنافع","منافع","بدل","لمصفوف"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-071','policy-doc-work-regulation',NULL,'المزايا والبدلات',11,71,'للرئيس التنفيذي الصلاحية بما يراه مناسبًا بمنح سلفة اضطرارية','proposed','للرئيس التنفيذي الصلاحية بما يراه مناسبًا بمنح سلفة اضطرارية للعامل؛ على أن تسترجع على شكل أقساط شهرية من راتب العامل','[{"index":1,"marker":null,"text":"للرئيس التنفيذي الصلاحية بما يراه مناسبًا بمنح سلفة اضطرارية للعامل؛ على أن تسترجع على شكل أقساط شهرية من راتب العامل"}]','["يرا","مناسبا","بمنح","سلف","اضطرار","رييس","تنفيذ","تسترجع","راتب","اقساط"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-072','policy-doc-work-regulation',NULL,'المزايا والبدلات',11,72,'بدل السكن والمواصلات، توفر المنشأة السكن اللائق لعمالها','proposed','تحل هذه المادة محل المادة المتعلقة ببدل السكن والمواصلات، توفر المنشأة السكن اللائق لعمالها. ولها أن تستعيض عن ذلك ببدل نقدي مناسب يُدفع لهم مع الأجر. كما توفر وسيلة مواصلات مناسبة لعمالها من مقر سكنهم إلى مقر العمل. ولها أن تستعيض عن ذلك ببدل نقدي مناسب يُدفع لهم مع الأجر','[{"index":1,"marker":null,"text":"تحل هذه المادة محل المادة المتعلقة ببدل السكن والمواصلات، توفر المنشأة السكن اللائق لعمالها. ولها أن تستعيض عن ذلك ببدل نقدي مناسب يُدفع لهم مع الأجر. كما توفر وسيلة مواصلات مناسبة لعمالها من مقر سكنهم إلى مقر العمل. ولها أن تستعيض عن ذلك ببدل نقدي مناسب يُدفع لهم مع الأجر"}]','["مواصل","سكن","لعمال","ببدل","توفر","لايق","تستعيض","نقد","مناسب","ولها"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-073','policy-doc-work-regulation',NULL,'أيام وساعات العمل',12,73,'يكون عدد أيام العمل ٥ أيام في الأسبوع','proposed','1. يكون عدد أيام العمل ٥ أيام في الأسبوع، يوم(ويكون يومي/ الجمعة) السبت, الراحة الأسبوعية بأجر كامل لجميع العمال، ويجوز للمنشأة بعد إبلاغ مكتب العمل المختص. أن تستبدل بهذا اليوم لبعض عمالها أي يوم من أيام الأسبوع، وعليها أن تمكنهم من القيام بواجباتهم الدينية ولا، يجوز تعويض يوم الراحة الأسبوعية بمقابل نقدي.
2. تكون ساعات ثماني(العمل ساعات) عمل يوميًا تخفض ست(إلى ساعات) يوميا في شهر رمضان للعمال المسلمين.','[{"index":1,"marker":"1","text":"يكون عدد أيام العمل ٥ أيام في الأسبوع، يوم(ويكون يومي/ الجمعة) السبت, الراحة الأسبوعية بأجر كامل لجميع العمال، ويجوز للمنشأة بعد إبلاغ مكتب العمل المختص. أن تستبدل بهذا اليوم لبعض عمالها أي يوم من أيام الأسبوع، وعليها أن تمكنهم من القيام بواجباتهم الدينية ولا، يجوز تعويض يوم الراحة الأسبوعية بمقابل نقدي."},{"index":2,"marker":"2","text":"تكون ساعات ثماني(العمل ساعات) عمل يوميًا تخفض ست(إلى ساعات) يوميا في شهر رمضان للعمال المسلمين."}]','["اسبوع","ايام","عدد","يوم","يوميا","ساع","عمال","راح","سبت","مكتب"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-074','policy-doc-work-regulation',NULL,'أيام وساعات العمل',12,74,'1 يُعتمَد','proposed','1 يُعتمَد. المعيار الأسبوعي في تحديد ساعات العمل بأجر كامل لجميع العاملين. 2 تخفض. ساعات العمل خلال شهر رمضان المبارك بحيث لا تزيد (على 36 ست) وثلاثين ساعة عمل فعلية في الأسبوع. 3 يُراعى. عند تحديد مواعيد ساعات العمل في المنشأة المتطلبات النظامية وطبيعة، العمل وتحقيق، أقصى درجات الفعالية. 4 يُخصص. للعاملين فترة مناسبة لأداء فريضة الصلاة في وقتها ولا، تحسب وقت الصلاة من ضمن ساعات العمل الفعلية. 5 يكون. تشغيل العامل بالتناوب وفق السياسات الداخلية للمنشأة. 6 يكون. حضور العاملين إلى أماكن العمل وانصرافهم منها في المواعيد المحددة وفق، الجداول التي تُعد في هذا الصدد، ويتعين إعلان هذه الجداول بوضعها في أماكن بارزة من مواقع العمل أو تبليغها إلكترونيًا ويجب، أن تتضمن هذه الجداول موعد بدء ساعات العمل وانتهائها. ولصاحب الصلاحية تحديد أوقات الحضور والانصراف لبعض الأعمال حسب ما تقتضيه مصلحة العمل. 7 يُراعى. في جداول العمل المشار إليها في الفقرة السابقة ألاّ يعمل العامل أكثر (من 5 خمس) ساعات متواصلة دون فترة للراحة والصلاة والطعام لا تقل عن نصف ساعة في المرة الواحدة وألا، يبقى العامل في مكان العمل أكثر (من )11 إحدى عشرة ساعة في اليوم الواحد. 8 لا. يجوز للعامل مغادرة العمل قبل انتهاء ساعات العمل دون موافقة مدير الإدارة وإذا، كانت طبيعة عمله تقتضي ذلك فينبغي تسجيل وقت الخروج ومكان، وجوده ووقت، العودة المتوقع قبل المغادرة. 9 يجب. على العاملين إثبات الحضور للعمل والانصراف منه حسب الأنظمة المعمول بها وتُحدّد، وسائل الرقابة على ساعات العمل بقرار من صاحب الصلاحية. 10 لا. يُسمح للعاملين بالدخول لمكان العمل، أو البقاء فيه خارج ساعات العمل الرسمية إلا في حال كان ذلك ضروريًا، حسب متطلبات العمل وبموافقة، مدير الإدارة، أو من ينوب عنه.','[{"index":1,"marker":null,"text":"1 يُعتمَد. المعيار الأسبوعي في تحديد ساعات العمل بأجر كامل لجميع العاملين. 2 تخفض. ساعات العمل خلال شهر رمضان المبارك بحيث لا تزيد (على 36 ست) وثلاثين ساعة عمل فعلية في الأسبوع. 3 يُراعى. عند تحديد مواعيد ساعات العمل في المنشأة المتطلبات النظامية وطبيعة، العمل وتحقيق، أقصى درجات الفعالية. 4 يُخصص. للعاملين فترة مناسبة لأداء فريضة الصلاة في وقتها ولا، تحسب وقت الصلاة من ضمن ساعات العمل الفعلية. 5 يكون. تشغيل العامل بالتناوب وفق السياسات الداخلية للمنشأة. 6 يكون. حضور العاملين إلى أماكن العمل وانصرافهم منها في المواعيد المحددة وفق، الجداول التي تُعد في هذا الصدد، ويتعين إعلان هذه الجداول بوضعها في أماكن بارزة من مواقع العمل أو تبليغها إلكترونيًا ويجب، أن تتضمن هذه الجداول موعد بدء ساعات العمل وانتهائها. ولصاحب الصلاحية تحديد أوقات الحضور والانصراف لبعض الأعمال حسب ما تقتضيه مصلحة العمل. 7 يُراعى. في جداول العمل المشار إليها في الفقرة السابقة ألاّ يعمل العامل أكثر (من 5 خمس) ساعات متواصلة دون فترة للراحة والصلاة والطعام لا تقل عن نصف ساعة في المرة الواحدة وألا، يبقى العامل في مكان العمل أكثر (من )11 إحدى عشرة ساعة في اليوم الواحد. 8 لا. يجوز للعامل مغادرة العمل قبل انتهاء ساعات العمل دون موافقة مدير الإدارة وإذا، كانت طبيعة عمله تقتضي ذلك فينبغي تسجيل وقت الخروج ومكان، وجوده ووقت، العودة المتوقع قبل المغادرة. 9 يجب. على العاملين إثبات الحضور للعمل والانصراف منه حسب الأنظمة المعمول بها وتُحدّد، وسائل الرقابة على ساعات العمل بقرار من صاحب الصلاحية. 10 لا. يُسمح للعاملين بالدخول لمكان العمل، أو البقاء فيه خارج ساعات العمل الرسمية إلا في حال كان ذلك ضروريًا، حسب متطلبات العمل وبموافقة، مدير الإدارة، أو من ينوب عنه."}]','["ساع","جداول","حضور","يعتمد","صلا","تحديد","وقت","انصراف","تقتض","مواعيد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-075','policy-doc-work-regulation',NULL,'أيام وساعات العمل',12,75,'الغياب والتأخ|ر','extracted','1 يجب. على العامل بأي، وسيلة كانت إبلاغ، مدير الإدارة في حالة التأخر أو الغياب لأسباب غير متوقعة وذلك، خلال اليوم نفسه الذي تغيّب فيه أو تأخّر. 2 يجب. على مدير الإدارة الإبلاغ عن حالات غياب العاملين بالوسائل التي تحددها المنشأة.','[{"index":1,"marker":null,"text":"1 يجب. على العامل بأي، وسيلة كانت إبلاغ، مدير الإدارة في حالة التأخر أو الغياب لأسباب غير متوقعة وذلك، خلال اليوم نفسه الذي تغيّب فيه أو تأخّر. 2 يجب. على مدير الإدارة الإبلاغ عن حالات غياب العاملين بالوسائل التي تحددها المنشأة."}]','["غياب","تاخ","تاخر","ابلاغ","تغيب","مدير","متوقع","نفس","لاسباب","باي"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-076','policy-doc-work-regulation',NULL,'العمل الإضافي',13,76,'في حال تكليف العامل بالعمل الإضافي','proposed','1. في حال تكليف العامل بالعمل الإضافي؛ يتم ذلك بموجب تكليف كتابي، أو الكتروني موجه له تصدره الجهة المسئولة في المنشأة يبين فيه عدد الساعات الإضافية المكلف بها العامل وعدد، الأيام اللازمة لذلك؛ وفق ما نصت عليه (المادة السادسة بعد المائة من) نظام العمل. من% أجره الأساسي. (
2. تدفع المنشأة للعامل عن ساعات العمل الإضافية أجرا إضافيا يوازي أجر الساعة مضافًا (إليه 50','[{"index":1,"marker":"1","text":"في حال تكليف العامل بالعمل الإضافي؛ يتم ذلك بموجب تكليف كتابي، أو الكتروني موجه له تصدره الجهة المسئولة في المنشأة يبين فيه عدد الساعات الإضافية المكلف بها العامل وعدد، الأيام اللازمة لذلك؛ وفق ما نصت عليه (المادة السادسة بعد المائة من) نظام العمل. من% أجره الأساسي. ("},{"index":2,"marker":"2","text":"تدفع المنشأة للعامل عن ساعات العمل الإضافية أجرا إضافيا يوازي أجر الساعة مضافًا (إليه 50"}]','["اضاف","تكليف","ساع","كتر","موج","يبين","مكلف","وعدد","يواز","مسيول"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-077','policy-doc-work-regulation',NULL,'العمل الإضافي',13,77,'العمل الإضافي','extracted','1 يعتبر. عملاً إضافيًا كل عمل يكلف به العامل بعد ساعات العمل العادية، أو في أيام الأعياد والعطلات، المنصوص عليها في هذه اللائحة. 2 مدير. الإدارة هو الذي يقر العمل الإضافي إن، وجد حاجة ماسة لإنجاز أعمال إضافية لا يمكن إنجازها أثناء ساعات العمل المعتادة، أو في الحالات الطارئة. 3 يُراعى. قبل تكليف العامل بالعمل الإضافي ما يلي: الحصول- على موافقة مسبقة من صاحب الصلاحية وتكليف كتابي. عدم- وجود إمكانية لإنجاز ذلك العمل أثناء ساعات العمل الرسمية. ألاّ- يكون التكليف نتيجة لإهمال العامل، أو تقصيره في أداء عمله. 4 احتساب. المقابل المالي لساعات العمل الإضافية عن العمل الذي يؤديه العامل خلال أيام العمل (المعتادة أيام الاسبوع وخلال) أيام الراحة الأسبوعية أو العطل الرسمية وفقا للمعادلة التالية: % ٪ من أجر الساعة الأساسي + ( ساعات العمل الإضافية (ضرب( الأجر الفعلي للساعة وتصرف ساعات العمل الإضافية المستحقة للعامل في في نهاية الشهر الذي تم فيه العمل بساعات إضافية 5 يجب. ألا يتجاوز أجر العمل الإضافي في السنة الواحدة أجر ستة أشهر من الأجر الأساسي. 6 يجوز. لصاحب العمل بموافقة العامل ان يحتسب للعامل أيام إجازة تعويضية مدفوعة الأجر بدلاً عن الأجر المستحق للعامل لساعات العمل الإضافية على، أن يدفع الأجر الإضافي نقدًا إذا انتهت خدمة العامل لأي سبب قبل استعماله للإجازة التعويضية. 7 وجود. ميزانية معتمدة والحصول على موافقة مكتوبة من إدارة الموارد البشرية. 8 يجب. ألاّ تزيد ساعات العمل الإضافية (عن 3 ساعات) في اليوم الوظيفي (و، 8 ساعات) في اليوم خلال العطل الرسمية 20(و، ساعة) أسبوعيًا. 9 لا. يجوز الجمع بين أجر العمل خارج أوقات الدوام الرسمي خلال أيام العمل المعتادة والتكليف، بمهمة رسمية.','[{"index":1,"marker":null,"text":"1 يعتبر. عملاً إضافيًا كل عمل يكلف به العامل بعد ساعات العمل العادية، أو في أيام الأعياد والعطلات، المنصوص عليها في هذه اللائحة. 2 مدير. الإدارة هو الذي يقر العمل الإضافي إن، وجد حاجة ماسة لإنجاز أعمال إضافية لا يمكن إنجازها أثناء ساعات العمل المعتادة، أو في الحالات الطارئة. 3 يُراعى. قبل تكليف العامل بالعمل الإضافي ما يلي: الحصول- على موافقة مسبقة من صاحب الصلاحية وتكليف كتابي. عدم- وجود إمكانية لإنجاز ذلك العمل أثناء ساعات العمل الرسمية. ألاّ- يكون التكليف نتيجة لإهمال العامل، أو تقصيره في أداء عمله. 4 احتساب. المقابل المالي لساعات العمل الإضافية عن العمل الذي يؤديه العامل خلال أيام العمل (المعتادة أيام الاسبوع وخلال) أيام الراحة الأسبوعية أو العطل الرسمية وفقا للمعادلة التالية: % ٪ من أجر الساعة الأساسي + ( ساعات العمل الإضافية (ضرب( الأجر الفعلي للساعة وتصرف ساعات العمل الإضافية المستحقة للعامل في في نهاية الشهر الذي تم فيه العمل بساعات إضافية 5 يجب. ألا يتجاوز أجر العمل الإضافي في السنة الواحدة أجر ستة أشهر من الأجر الأساسي. 6 يجوز. لصاحب العمل بموافقة العامل ان يحتسب للعامل أيام إجازة تعويضية مدفوعة الأجر بدلاً عن الأجر المستحق للعامل لساعات العمل الإضافية على، أن يدفع الأجر الإضافي نقدًا إذا انتهت خدمة العامل لأي سبب قبل استعماله للإجازة التعويضية. 7 وجود. ميزانية معتمدة والحصول على موافقة مكتوبة من إدارة الموارد البشرية. 8 يجب. ألاّ تزيد ساعات العمل الإضافية (عن 3 ساعات) في اليوم الوظيفي (و، 8 ساعات) في اليوم خلال العطل الرسمية 20(و، ساعة) أسبوعيًا. 9 لا. يجوز الجمع بين أجر العمل خارج أوقات الدوام الرسمي خلال أيام العمل المعتادة والتكليف، بمهمة رسمية."}]','["اضاف","ساع","معتاد","رسم","ايام","لانجاز","لساع","عطل","تكليف","اثناء"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-078','policy-doc-work-regulation',NULL,'التفتيش الإداري',14,78,'يكون دخول العمال إلى مواقع عملهم','proposed','يكون دخول العمال إلى مواقع عملهم، وانصرافهم منه من الأماكن المخصصة لذلك وعلى، العمال الامتثال (للتفتيش التفتيش الإداري متى) طُلب منهم ذلك.','[{"index":1,"marker":null,"text":"يكون دخول العمال إلى مواقع عملهم، وانصرافهم منه من الأماكن المخصصة لذلك وعلى، العمال الامتثال (للتفتيش التفتيش الإداري متى) طُلب منهم ذلك."}]','["دخول","مواقع","عمال","تفتيش","امتثال","منهم","وانصراف","مخصص","متي","اماكن"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-079','policy-doc-work-regulation',NULL,'التفتيش الإداري',14,79,'يجوز للمنشأة أن تلزم العامل بأن يثبت حضوره وانصرافه','proposed','يجوز للمنشأة أن تلزم العامل بأن يثبت حضوره وانصرافه، بإحدى الوسائل المُعدة لهذا الغرض.','[{"index":1,"marker":null,"text":"يجوز للمنشأة أن تلزم العامل بأن يثبت حضوره وانصرافه، بإحدى الوسائل المُعدة لهذا الغرض."}]','["بان","حضور","تلزم","وانصراف","يثبت","باحد","معد","لهذا","غرض","وسايل"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-080','policy-doc-work-regulation',NULL,'الإجازات',15,80,'يستحق العامل عن كل سنة من سنوات الخدمة إجازة','proposed','يستحق العامل عن كل سنة من سنوات الخدمة إجازة سنوية بأجر كامل لا تقل مدتها عن ثلاثون يومًا، تزاد إلى مدة لا تقل عن ثلاثون يومًا، وللعامل بعد موافقة المنشأة الحصول على جزء من إجازته السنوية بنسبة المدة التي قضاها من السنة في العمل؛ إذا بلغت خدمته خمس سنوات متصلة، ويجوز الاتفاق في عقد العمل على أن تكون مدة الإجازة السنوية أكثر من ذلك.','[{"index":1,"marker":null,"text":"يستحق العامل عن كل سنة من سنوات الخدمة إجازة سنوية بأجر كامل لا تقل مدتها عن ثلاثون يومًا، تزاد إلى مدة لا تقل عن ثلاثون يومًا، وللعامل بعد موافقة المنشأة الحصول على جزء من إجازته السنوية بنسبة المدة التي قضاها من السنة في العمل؛ إذا بلغت خدمته خمس سنوات متصلة، ويجوز الاتفاق في عقد العمل على أن تكون مدة الإجازة السنوية أكثر من ذلك."}]','["سنو","اجاز","يستحق","سنه","خدم","تقل","مده","تزاد","بلغت","ثلاث"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-081','policy-doc-work-regulation',NULL,'الإجازات',15,81,'للعامل الحق في إجازة بأجر كامل في الأعياد','proposed','للعامل الحق في إجازة بأجر كامل في الأعياد، والمناسبات وفق، مايلي:
1. أربعة أيام بمناسبة عيد الفطر المبارك تبدأ، من اليوم التالي لليوم التاسع والعشرين من شهر رمضان المبارك حسب تقويم أم القرى.
2. أربعة أيام بمناسبة عيد الأضحى المبارك تبدأ، من يوم الوقوف بعرفة.
3. يوم واحد بمناسبة اليوم الوطني (للمملكة أول ).الميزان
4. يوم واحد بمناسبة يوم التأسيس في الثاني والعشرون من شهر فبراير للعام الميلادي وإذا تداخلت أيام هذه الإجازات مع الراحة الأسبوعية يعوض العامل عنها بما يعادلها قبل أيام تلك الإجازات أو بعدها أما، إذا تداخلت أيام إجازة أحد العيدين مع إجازة اليوم الوطني أو يوم التأسيس فلا يعوض العامل عنه.','[{"index":1,"marker":null,"text":"للعامل الحق في إجازة بأجر كامل في الأعياد، والمناسبات وفق، مايلي:"},{"index":2,"marker":"1","text":"أربعة أيام بمناسبة عيد الفطر المبارك تبدأ، من اليوم التالي لليوم التاسع والعشرين من شهر رمضان المبارك حسب تقويم أم القرى."},{"index":3,"marker":"2","text":"أربعة أيام بمناسبة عيد الأضحى المبارك تبدأ، من يوم الوقوف بعرفة."},{"index":4,"marker":"3","text":"يوم واحد بمناسبة اليوم الوطني (للمملكة أول ).الميزان"},{"index":5,"marker":"4","text":"يوم واحد بمناسبة يوم التأسيس في الثاني والعشرون من شهر فبراير للعام الميلادي وإذا تداخلت أيام هذه الإجازات مع الراحة الأسبوعية يعوض العامل عنها بما يعادلها قبل أيام تلك الإجازات أو بعدها أما، إذا تداخلت أيام إجازة أحد العيدين مع إجازة اليوم الوطني أو يوم التأسيس فلا يعوض العامل عنه."}]','["بمناسب","يوم","اعياد","مبار","اجاز","عيد","تداخلت","ايام","تاسيس","يعوض"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-082','policy-doc-work-regulation',NULL,'الإجازات',15,82,'يحق للعامل الحصول على إجازة بأجر كامل في الحالات','proposed','يحق للعامل الحصول على إجازة بأجر كامل في الحالات التالية:
1. خمسة أيام عند زواجه.
2. ثلاثة أيام في حالة ولادة مولود له.
3. خمسة أيام في حالة وفاة زوجة العامل، أو أحد أصوله، أو فروعه.
4. أربعة أشهر وعشرة، أيام في حالة وفاة زوج العاملة المسلمة؛ ولها الحق في تمديدها دون أجر إن كانت حاملاً حتى تضع حملها ولا، يجوز لها الاستفادة من باقي إجازة العدة الممنوحة لها بعد وضع هذا الحمل.
5. خمسة عشر يومًا في حالة وفاة زوج العاملة غير المسلمة. وللمنشأة الحق في طلب الوثائق المؤيدة للحالات المشار إليها.','[{"index":1,"marker":null,"text":"يحق للعامل الحصول على إجازة بأجر كامل في الحالات التالية:"},{"index":2,"marker":"1","text":"خمسة أيام عند زواجه."},{"index":3,"marker":"2","text":"ثلاثة أيام في حالة ولادة مولود له."},{"index":4,"marker":"3","text":"خمسة أيام في حالة وفاة زوجة العامل، أو أحد أصوله، أو فروعه."},{"index":5,"marker":"4","text":"أربعة أشهر وعشرة، أيام في حالة وفاة زوج العاملة المسلمة؛ ولها الحق في تمديدها دون أجر إن كانت حاملاً حتى تضع حملها ولا، يجوز لها الاستفادة من باقي إجازة العدة الممنوحة لها بعد وضع هذا الحمل."},{"index":6,"marker":"5","text":"خمسة عشر يومًا في حالة وفاة زوج العاملة غير المسلمة. وللمنشأة الحق في طلب الوثائق المؤيدة للحالات المشار إليها."}]','["زوج","وفا","يحق","مسلم","حمل","ايام","حصول","اجاز","باجر","خمس"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-083','policy-doc-work-regulation',NULL,'الإجازات',15,83,'يستحق العامل الذي- يثبت مرضه بشهادة طبية صادرة','proposed','يستحق العامل الذي- يثبت مرضه بشهادة طبية صادرة عن طبيب المنشأة، أو مرجع طبي معتمد لديها إجازات- مرضية خلال السنة الواحدة والتي، تبدأ من تاريخ أول إجازة مرضية؛ سواء أكانت هذه الإجازات متصلة أم متقطعة وذلك، على النحو التالي:
1. الثلاثون يومًا الأولى بأجر، كامل.
2. الستون يومًا التالية بثلاثة، أرباع الأجر.
3. الثلاثون يومًأ التي تلي ذلك بدون، أجر. وللعامل الحق في وصل إجازته السنوية بالمرضية.','[{"index":1,"marker":null,"text":"يستحق العامل الذي- يثبت مرضه بشهادة طبية صادرة عن طبيب المنشأة، أو مرجع طبي معتمد لديها إجازات- مرضية خلال السنة الواحدة والتي، تبدأ من تاريخ أول إجازة مرضية؛ سواء أكانت هذه الإجازات متصلة أم متقطعة وذلك، على النحو التالي:"},{"index":2,"marker":"1","text":"الثلاثون يومًا الأولى بأجر، كامل."},{"index":3,"marker":"2","text":"الستون يومًا التالية بثلاثة، أرباع الأجر."},{"index":4,"marker":"3","text":"الثلاثون يومًأ التي تلي ذلك بدون، أجر. وللعامل الحق في وصل إجازته السنوية بالمرضية."}]','["مرض","بشهاد","يثبت","طبي","صادر","يستحق","اجاز","اول","يوما","مرجع"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-084','policy-doc-work-regulation',NULL,'الإجازات',15,84,'إذا- صادفت بداية إجازة أحد العيدين ثاني أيام العمل','proposed','إذا- صادفت بداية إجازة أحد العيدين ثاني أيام العمل الأسبوعي فإنها، تتقدم إلى نهاية آخر يوم عمل من الأسبوع السابق. إذا- صادفت نهاية إجازة أحد العيدين اليوم الذي يسبق آخر أيام العمل الأسبوعي فإنها تتأخر إلى بداية أول يوم عمل من الأسبوع اللاحق. للرئيس- التنفيذي استثناء الحق في منح العاملين إجازة بخلاف المنصوص عليها في عقودهم وبحد أقصى خمسة أيام في السنة ولا، تحتسب تلك الاجازة من إجازاتهم المنصوص عليها نظامًا. يجب- إصدار تعاميم إدارية سنوية من قبل إدارة الموارد البشرية للإعلان عن الأيام المحددة للعطلات.','[{"index":1,"marker":null,"text":"إذا- صادفت بداية إجازة أحد العيدين ثاني أيام العمل الأسبوعي فإنها، تتقدم إلى نهاية آخر يوم عمل من الأسبوع السابق. إذا- صادفت نهاية إجازة أحد العيدين اليوم الذي يسبق آخر أيام العمل الأسبوعي فإنها تتأخر إلى بداية أول يوم عمل من الأسبوع اللاحق. للرئيس- التنفيذي استثناء الحق في منح العاملين إجازة بخلاف المنصوص عليها في عقودهم وبحد أقصى خمسة أيام في السنة ولا، تحتسب تلك الاجازة من إجازاتهم المنصوص عليها نظامًا. يجب- إصدار تعاميم إدارية سنوية من قبل إدارة الموارد البشرية للإعلان عن الأيام المحددة للعطلات."}]','["صادفت","بدا","عيد","اجاز","ايام","اسبوع","ثان","احد","منصوص","يوم"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-085','policy-doc-work-regulation',NULL,'الإجازات',15,85,'ربط العطلات الرسمية بالإجازات','extracted','يجوز للعامل الحصول على إجازة طارئة أو سنوية وربطها بعطلة (رسمية عطلة عيدي الفطر والأضحى سواء)، أكان ذلك قبلها أم بعدها ويجوز، له الحصول على جزء قبلها وجزء بعدها.','[{"index":1,"marker":null,"text":"يجوز للعامل الحصول على إجازة طارئة أو سنوية وربطها بعطلة (رسمية عطلة عيدي الفطر والأضحى سواء)، أكان ذلك قبلها أم بعدها ويجوز، له الحصول على جزء قبلها وجزء بعدها."}]','["ربط","عطل","رسم","اجاز","حصول","وربط","بعطل","اكان","وجزء","فطر"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-086','policy-doc-work-regulation',NULL,'الإجازات',15,86,'الإجازة السنوية','extracted','1 استحقاق- الإجازة السنوية: يستحق العامل إجازة سنوية بأجر كامل (قدرها 30 ثلاثون) يوم تقويمي عن كل سنة ميلادية. 2 حساب- الإجازة السنوية: أ تُحسب- الإجازة السنوية اعتبارًا من تاريخ مباشرة العامل للعمل. بيُعلّق- احتساب رصيد الإجازات عند حصول العامل على إجازة استثنائية فيما زاد على عشرين يومًا. لا يجوز للعامل الخاضع لفترة التجربة التمتع بالمستحق من الإجازة إلا بعد انتهاء فترة التجربة. 4 تجميع- الإجازات السنوية: أ يجب- أن يتمتع العامل بإجازته السنوية في سنة استحقاقها وذلك، لتحقيق الهدف منها، بو- للعامل بموافقة صاحب الصلاحية أن يؤجل إجازته السنوية أو أيامًا منها إلى السنة التالية. ت يجوز- لصاحب الصلاحية إذا اقتضت ظروف العمل تأجيل إجازة العامل السنوية، أو أي منها بعد نهاية سنة استحقاقها، وذلك لمدة لا تزيد عن تسعين يوم وإذا، اقتضت ظروف العمل استمرار التأجيل وجب الحصول على موافقة العامل كتابةً، على ألاّ يتعدى التأجيل نهاية السنة التالية لسنة استحقاق الإجازة. 5 تجزئة- الإجازة السنوية: أ يُسمح- للعامل بالتمتع برصيده من الإجازة السنوية على فترات حسب ظروف المنشأة بناءً، على الضوابط التالية: ألا· تتجاوز مدة إجازته عن الرصيد المسموح به. ألا· تتجاوز فترات التجزئة في السنة ست مرات كحد، أقصى. ألا· تتجاوز عدد أيام الإجازة السنوية المتمتع بها في السنة خمسين يوم عمل. بيجوز- لصاحب الصلاحية استثناء أي من الضوابط أعلاه؛ بما لا يؤثر على سير العمل. 6 التعويض- عن الإجازة: لتحقيق الأهداف الأساسية من الإجازات السنوية؛ فإنه لا يجوز تعويض أي عامل بمبلغ مالي عن إجازته السنوية، أو جزء منها إلا عند نهاية خدمته ويتم، حساب مبلغ التعويض للعامل على أساس أخر أجر فعلي.','[{"index":1,"marker":null,"text":"1 استحقاق- الإجازة السنوية: يستحق العامل إجازة سنوية بأجر كامل (قدرها 30 ثلاثون) يوم تقويمي عن كل سنة ميلادية. 2 حساب- الإجازة السنوية: أ تُحسب- الإجازة السنوية اعتبارًا من تاريخ مباشرة العامل للعمل. بيُعلّق- احتساب رصيد الإجازات عند حصول العامل على إجازة استثنائية فيما زاد على عشرين يومًا. لا يجوز للعامل الخاضع لفترة التجربة التمتع بالمستحق من الإجازة إلا بعد انتهاء فترة التجربة. 4 تجميع- الإجازات السنوية: أ يجب- أن يتمتع العامل بإجازته السنوية في سنة استحقاقها وذلك، لتحقيق الهدف منها، بو- للعامل بموافقة صاحب الصلاحية أن يؤجل إجازته السنوية أو أيامًا منها إلى السنة التالية. ت يجوز- لصاحب الصلاحية إذا اقتضت ظروف العمل تأجيل إجازة العامل السنوية، أو أي منها بعد نهاية سنة استحقاقها، وذلك لمدة لا تزيد عن تسعين يوم وإذا، اقتضت ظروف العمل استمرار التأجيل وجب الحصول على موافقة العامل كتابةً، على ألاّ يتعدى التأجيل نهاية السنة التالية لسنة استحقاق الإجازة. 5 تجزئة- الإجازة السنوية: أ يُسمح- للعامل بالتمتع برصيده من الإجازة السنوية على فترات حسب ظروف المنشأة بناءً، على الضوابط التالية: ألا· تتجاوز مدة إجازته عن الرصيد المسموح به. ألا· تتجاوز فترات التجزئة في السنة ست مرات كحد، أقصى. ألا· تتجاوز عدد أيام الإجازة السنوية المتمتع بها في السنة خمسين يوم عمل. بيجوز- لصاحب الصلاحية استثناء أي من الضوابط أعلاه؛ بما لا يؤثر على سير العمل. 6 التعويض- عن الإجازة: لتحقيق الأهداف الأساسية من الإجازات السنوية؛ فإنه لا يجوز تعويض أي عامل بمبلغ مالي عن إجازته السنوية، أو جزء منها إلا عند نهاية خدمته ويتم، حساب مبلغ التعويض للعامل على أساس أخر أجر فعلي."}]','["اجاز","سنو","استحقاق","تاجيل","سنه","ظروف","لتحقيق","اقتضت","تتجاوز","تعويض"]','["broken_glyphs","clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-087','policy-doc-work-regulation',NULL,'الإجازات',15,87,'الإجازة الطارئة','extracted','يجوز للعامل بعد إخطار مديره أن يحصل على إجازة بأجر لأسباب طارئة بشرط، ألا تزيد مدة الإجازة عن ثلاثة أيام عمل خلال السنة ويجوز، للعامل تجزئة الإجازة الطارئة إلى نصف يوم بما (يعادل 4 أربع) ساعات يوميًا.','[{"index":1,"marker":null,"text":"يجوز للعامل بعد إخطار مديره أن يحصل على إجازة بأجر لأسباب طارئة بشرط، ألا تزيد مدة الإجازة عن ثلاثة أيام عمل خلال السنة ويجوز، للعامل تجزئة الإجازة الطارئة إلى نصف يوم بما (يعادل 4 أربع) ساعات يوميًا."}]','["طار","اجاز","يحصل","يوميا","تجز","نصف","لاسباب","يعادل","بشرط","اخطار"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-088','policy-doc-work-regulation',NULL,'الإجازات',15,88,'الإجازات المرضية','extracted','1 تمنح- المنشأة العامل الذي يثبت مرضه بموجب تقرير طبي صادر عن مركز طبي معتمد إجازة مرضية وذلك، على النحو الآتي:
أ. إجازة بأجر فعلي (عن 30 الثلاثين) يومًا الأولى. %من أجر العامل ( ل06 )الستين يومًا التي تليها.
ب. إجازة بثلاثة أرباع الأجر الفعلي أي ما يعادل 75
ج. إجازة بدون أجر فعلي ( ل03 )الثلاثين يومًا التي تليها،سواء أكانت هذه الإجازات متصلة أم متقطعة،ويُقصد بالسنة الواحدة السنة: التي تبدأ من تاريخ أول إجازة مرضية.
د. بعد انقضاء المدة أعلاه يُحال موضوع العامل مع التقارير الطبية للجنة حقوق وواجبات العاملين للنظر، في تمديد الإجازة أو عدم أهلية العامل للعمل. 2 يُخطِر- العامل إدارة الموارد البشرية بالإجازات المرضية فور اعتمادها ويُحتفَظ، ببطاقة السجل الطبي لكل عامل بالمنشأة مبينًا، بهذه البطاقة بيانات العامل وتاريخ، تردده على الكشف الطبي وبيان، المرض؛ وتُحفظ هذه البطاقة في ملف العامل. 3 في- حال كان التقرير الطبي صادرًا من خارج المملكة؛ فيجب أن يكون معتمدًا من الجهات المختصة. 4 إذا- تعرض العامل لحادث أثناء تأدية عمله، أو حين الذهاب والعودة من عمله؛ فإنّه يعتبر إصابة عمل ويطبق، عليه نظام التأمينات (الاجتماعية إصابة العمل وتقوم)، المنشأة بإشعار المؤسسة العامة للتأمينات الاجتماعية عن إصابات العمل، وفق المتطلبات التي تحددها المؤسسة. 5 لا- يدخل في احتساب مدة الاجازة المرضية ما يتخللها من عطل عيدي الفطر والاضحى واليوم، الوطني ويوم، التأسيس. 6 تمنح- المنشأة العامل المصاب بالفشل الكلوي إجازة بأجر كامل عن الأيام التي يجري له فيها الغسيل للتنقية الدموية، بموجب تقرير من الجهة الطبية التي تتولى علاجه.','[{"index":1,"marker":null,"text":"1 تمنح- المنشأة العامل الذي يثبت مرضه بموجب تقرير طبي صادر عن مركز طبي معتمد إجازة مرضية وذلك، على النحو الآتي:"},{"index":2,"marker":"أ","text":"إجازة بأجر فعلي (عن 30 الثلاثين) يومًا الأولى. %من أجر العامل ( ل06 )الستين يومًا التي تليها."},{"index":3,"marker":"ب","text":"إجازة بثلاثة أرباع الأجر الفعلي أي ما يعادل 75"},{"index":4,"marker":"ج","text":"إجازة بدون أجر فعلي ( ل03 )الثلاثين يومًا التي تليها،سواء أكانت هذه الإجازات متصلة أم متقطعة،ويُقصد بالسنة الواحدة السنة: التي تبدأ من تاريخ أول إجازة مرضية."},{"index":5,"marker":"د","text":"بعد انقضاء المدة أعلاه يُحال موضوع العامل مع التقارير الطبية للجنة حقوق وواجبات العاملين للنظر، في تمديد الإجازة أو عدم أهلية العامل للعمل. 2 يُخطِر- العامل إدارة الموارد البشرية بالإجازات المرضية فور اعتمادها ويُحتفَظ، ببطاقة السجل الطبي لكل عامل بالمنشأة مبينًا، بهذه البطاقة بيانات العامل وتاريخ، تردده على الكشف الطبي وبيان، المرض؛ وتُحفظ هذه البطاقة في ملف العامل. 3 في- حال كان التقرير الطبي صادرًا من خارج المملكة؛ فيجب أن يكون معتمدًا من الجهات المختصة. 4 إذا- تعرض العامل لحادث أثناء تأدية عمله، أو حين الذهاب والعودة من عمله؛ فإنّه يعتبر إصابة عمل ويطبق، عليه نظام التأمينات (الاجتماعية إصابة العمل وتقوم)، المنشأة بإشعار المؤسسة العامة للتأمينات الاجتماعية عن إصابات العمل، وفق المتطلبات التي تحددها المؤسسة. 5 لا- يدخل في احتساب مدة الاجازة المرضية ما يتخللها من عطل عيدي الفطر والاضحى واليوم، الوطني ويوم، التأسيس. 6 تمنح- المنشأة العامل المصاب بالفشل الكلوي إجازة بأجر كامل عن الأيام التي يجري له فيها الغسيل للتنقية الدموية، بموجب تقرير من الجهة الطبية التي تتولى علاجه."}]','["مرض","اجاز","طبي","اصاب","تلي","بطاق","تقرير","تمنح","موسس","اول"]','["broken_glyphs","clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-089','policy-doc-work-regulation',NULL,'الإجازات',15,89,'إجازة الامتحانات الدراسية','extracted','1 للعامل- إذا وافقت المنشأة على انتسابه إلى مؤسسة تعليمية، أو قبلت استمراره فيها الحق، في إجازة بأجر لتأدية الامتحان عن سنة غير مُعادة تحدد مدتها بعدد أيام الامتحان الفعلية أما، إذا كان الامتحان عن سنة مُعادة فيكون للعامل الحق في إجازة استثنائية دون أجر فعلي بعدد أيام الامتحان الفعلية ويُحرم، العامل من أجر الإجازة إذا ثبت أنه لم يؤد الامتحان مع، عدم الإخلال بحق المنشأة في مساءلته تأديبيًا. 2 إذا- لم يحصل العامل على موافقة المنشأة على انتسابه إلى مؤسسة تعليمية فله، أن يحصل على إجازة لتأدية الامتحان بعدد أيام الامتحان الفعلية تحتسب من إجازته السنوية في حال توافرها. وعند تعذر ذلك فللعامل أن يحصل على إجازة استثنائية دون أجر فعلي بعدد أيام الامتحان الفعلية. 3 يجوز- بموافقة من المنشأة أن يحصل العامل على إجازة سنوية خلال الأيام التي تتخلل أيام الاختبارات وذلك، من رصيد إجازته السنوية على ألا يتم احتساب هذه الإجازة من ضمن فرص التجزئة المحددة في هذه اللائحة. 4 على- العامل أن يتقدم بطلب إجازة الامتحانات الدراسية قبل موعدها بخمسة عشر يوماً على الأقل. وللمنشأة أن تطلب من العامل تقديم الوثائق المؤيدة لطلب الإجازة وكذلك، ما يدل على أدائه الامتحان.','[{"index":1,"marker":null,"text":"1 للعامل- إذا وافقت المنشأة على انتسابه إلى مؤسسة تعليمية، أو قبلت استمراره فيها الحق، في إجازة بأجر لتأدية الامتحان عن سنة غير مُعادة تحدد مدتها بعدد أيام الامتحان الفعلية أما، إذا كان الامتحان عن سنة مُعادة فيكون للعامل الحق في إجازة استثنائية دون أجر فعلي بعدد أيام الامتحان الفعلية ويُحرم، العامل من أجر الإجازة إذا ثبت أنه لم يؤد الامتحان مع، عدم الإخلال بحق المنشأة في مساءلته تأديبيًا. 2 إذا- لم يحصل العامل على موافقة المنشأة على انتسابه إلى مؤسسة تعليمية فله، أن يحصل على إجازة لتأدية الامتحان بعدد أيام الامتحان الفعلية تحتسب من إجازته السنوية في حال توافرها. وعند تعذر ذلك فللعامل أن يحصل على إجازة استثنائية دون أجر فعلي بعدد أيام الامتحان الفعلية. 3 يجوز- بموافقة من المنشأة أن يحصل العامل على إجازة سنوية خلال الأيام التي تتخلل أيام الاختبارات وذلك، من رصيد إجازته السنوية على ألا يتم احتساب هذه الإجازة من ضمن فرص التجزئة المحددة في هذه اللائحة. 4 على- العامل أن يتقدم بطلب إجازة الامتحانات الدراسية قبل موعدها بخمسة عشر يوماً على الأقل. وللمنشأة أن تطلب من العامل تقديم الوثائق المؤيدة لطلب الإجازة وكذلك، ما يدل على أدائه الامتحان."}]','["امتح","اجاز","بعدد","يحصل","دراس","فعل","ايام","انتساب","معاد","لتاد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-090','policy-doc-work-regulation',NULL,'الإجازات',15,90,'إجازة مرافقة مريض','extracted','1 يجوز- للمنشأة منح العامل إجازة لمرافقة أحد أفراد أسرته، أو أي من والديه لتلقي العلاج في إحدى المؤسسات الطبية لمدة، لا تزيد عن خمسة عشر يومًا بأجر فعلي كامل. 2 تحسب- المدة التي تتجاوز المدة المحددة في الفقرة السابقة من، ضمن إجازاته السنوية أو الطارئة وتحسب، إجازة استثنائية بدون أجر إذا كان قد استنفذ رصيده من الإجازات السنوية والطارئة. 3 يُشترط- لمنح هذه الإجازة تقديم وثائق من جهات طبية معتمدة لدى المنشأة تثبت، الحاجة لوجود مرافق. 4 يجب- على العامل تقديم تقارير دورية مصدقة عن وضع المريض والحاجة لاستمرار وجود المرافق. 5 يجب- الحصول على موافقة صاحب الصلاحية أو من يفوضه على إجازة مرافقة مريض.','[{"index":1,"marker":null,"text":"1 يجوز- للمنشأة منح العامل إجازة لمرافقة أحد أفراد أسرته، أو أي من والديه لتلقي العلاج في إحدى المؤسسات الطبية لمدة، لا تزيد عن خمسة عشر يومًا بأجر فعلي كامل. 2 تحسب- المدة التي تتجاوز المدة المحددة في الفقرة السابقة من، ضمن إجازاته السنوية أو الطارئة وتحسب، إجازة استثنائية بدون أجر إذا كان قد استنفذ رصيده من الإجازات السنوية والطارئة. 3 يُشترط- لمنح هذه الإجازة تقديم وثائق من جهات طبية معتمدة لدى المنشأة تثبت، الحاجة لوجود مرافق. 4 يجب- على العامل تقديم تقارير دورية مصدقة عن وضع المريض والحاجة لاستمرار وجود المرافق. 5 يجب- الحصول على موافقة صاحب الصلاحية أو من يفوضه على إجازة مرافقة مريض."}]','["مرافق","مريض","اجاز","حاج","طار","تقديم","لمرافق","ديه","لتلق","استنفذ"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-091','policy-doc-work-regulation',NULL,'الإجازات',15,91,'الإجازات الاستثنائية بدون أجر','extracted','1 يجوز- للمنشأة منح العامل إجازة بدون أجر فعلي لأسباب طارئة خاصة بالعامل ومقبولة من المنشأة. 2 يتم- منح هذه الإجازة في ضوء توفر الشروط الآتية: أ عدم- وجود رصيد إجازات سنوية أو اضطرارية لدى العامل. بإكمال- العامل سنة على الأقل في المنشأة. 3 يحسم- مجموع فترات الإجازات الاستثنائية عند تجاوزها عشرين يوماً من مدة خدمته عند حساب مكافأة نهاية الخدمة. 4 يجب- ألا تتجاوز مدة الإجازة الاستثنائية ستة أشهر ويجوز، لصاحب الصلاحية استثناء العامل من هذا الشرط لمدة أو مدد مماثلة لا تتجاوز في مجموعها ثمانية عشر شهراً خلال، خدمة العامل في المنشأة. 5 يختص- مدير الإدارة بالموافقة على الإجازة الاستثنائية إذا كانت خمسة أيام عمل فأقل للمرة الواحدة ولصاحب، الصلاحية أو من يفوضه الموافقة على الإجازة الاستثنائية إذا زادت المدة عن ذلك. 6 لا- يستحق العامل إجازة سنوية عن مدة الإجازة الاستثنائية فيما زاد على عشرين يومًا 7 لا- يستحق العامل علاوة سنوية في حال تجاوز مجموع إجازاته الاستثنائية ستة أشهر في السنة الواحدة.','[{"index":1,"marker":null,"text":"1 يجوز- للمنشأة منح العامل إجازة بدون أجر فعلي لأسباب طارئة خاصة بالعامل ومقبولة من المنشأة. 2 يتم- منح هذه الإجازة في ضوء توفر الشروط الآتية: أ عدم- وجود رصيد إجازات سنوية أو اضطرارية لدى العامل. بإكمال- العامل سنة على الأقل في المنشأة. 3 يحسم- مجموع فترات الإجازات الاستثنائية عند تجاوزها عشرين يوماً من مدة خدمته عند حساب مكافأة نهاية الخدمة. 4 يجب- ألا تتجاوز مدة الإجازة الاستثنائية ستة أشهر ويجوز، لصاحب الصلاحية استثناء العامل من هذا الشرط لمدة أو مدد مماثلة لا تتجاوز في مجموعها ثمانية عشر شهراً خلال، خدمة العامل في المنشأة. 5 يختص- مدير الإدارة بالموافقة على الإجازة الاستثنائية إذا كانت خمسة أيام عمل فأقل للمرة الواحدة ولصاحب، الصلاحية أو من يفوضه الموافقة على الإجازة الاستثنائية إذا زادت المدة عن ذلك. 6 لا- يستحق العامل إجازة سنوية عن مدة الإجازة الاستثنائية فيما زاد على عشرين يومًا 7 لا- يستحق العامل علاوة سنوية في حال تجاوز مجموع إجازاته الاستثنائية ستة أشهر في السنة الواحدة."}]','["استثناي","اجاز","مجموع","بدون","تجاوز","عشر","مده","سته","اشهر","سنو"]','["broken_glyphs"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-092','policy-doc-work-regulation',NULL,'الإجازات',15,92,'التأخر عن مباشرة العمل بعد الإجازة','extracted','1 إذا- حالت ظروف طارئة دون استئناف العامل مهام عمله بعد انتهاء أي من إجازاته فإن، عليه الاتصال بمدير إدارته بالمنشأة قبل انتهاء مدة الإجازة وطلب تمديد الإجازة مع، توضيح الظروف الطارئة وتقديم، وثائق رسمية تثبتها. وعلى المدير إفادة إدارة الموارد البشرية بذلك خطيًا أو إلكترونيًا فور علمه بهذه المعلومات. 2 إذا- أخفق العامل في إبلاغ مدير الإدارة مقدمًا عن اضطراره للتأخر في مباشرة مهام عمله بعد انتهاء أي من إجازاته، أو إذا لم تتم الموافقة على تمديد أي من إجازاته فإنه، يعتبر متغيبًا ويخضع، للمساءلة التأديبية وفقًا لهذه اللائحة. 3 تخضع- الموافقة على تمديد أي من الإجازات لتقدير مدير الإدارة. 4 إذا- لم يباشر العامل عمله بعد انتهاء مدة الإجازة المرضية بسبب المرض؛ يتم التعامل مع الحالة وفقًا لنظام العمل.','[{"index":1,"marker":null,"text":"1 إذا- حالت ظروف طارئة دون استئناف العامل مهام عمله بعد انتهاء أي من إجازاته فإن، عليه الاتصال بمدير إدارته بالمنشأة قبل انتهاء مدة الإجازة وطلب تمديد الإجازة مع، توضيح الظروف الطارئة وتقديم، وثائق رسمية تثبتها. وعلى المدير إفادة إدارة الموارد البشرية بذلك خطيًا أو إلكترونيًا فور علمه بهذه المعلومات. 2 إذا- أخفق العامل في إبلاغ مدير الإدارة مقدمًا عن اضطراره للتأخر في مباشرة مهام عمله بعد انتهاء أي من إجازاته، أو إذا لم تتم الموافقة على تمديد أي من إجازاته فإنه، يعتبر متغيبًا ويخضع، للمساءلة التأديبية وفقًا لهذه اللائحة. 3 تخضع- الموافقة على تمديد أي من الإجازات لتقدير مدير الإدارة. 4 إذا- لم يباشر العامل عمله بعد انتهاء مدة الإجازة المرضية بسبب المرض؛ يتم التعامل مع الحالة وفقًا لنظام العمل."}]','["اجاز","تاخر","تمديد","انتهاء","مباشر","ظروف","مدير","مهام","مرض","طار"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-093','policy-doc-work-regulation',NULL,'الإجازات',15,93,'توثيق إجراءات الإجازات','extracted','يجب توثيق كافة الإجراءات المتعلقة بالإجازات وتوقيعها، من أصحاب الصلاحية بالصيغة الورقية أو الإلكترونية وفقًا، للنماذج والضوابط التي تضعها إدارة الموارد البشرية.','[{"index":1,"marker":null,"text":"يجب توثيق كافة الإجراءات المتعلقة بالإجازات وتوقيعها، من أصحاب الصلاحية بالصيغة الورقية أو الإلكترونية وفقًا، للنماذج والضوابط التي تضعها إدارة الموارد البشرية."}]','["توثيق","اجراء","اجاز","وتوقيع","اصحاب","صيغ","ورق","نماذج","الكتر","متعلق"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-094','policy-doc-work-regulation',NULL,'الإجازات',15,94,'يحق للعامل الحصول على إجازة بأجر كامل في الحالات','proposed','يحق للعامل الحصول على إجازة بأجر كامل في الحالات التالية: 1 ثلاثة- أيام في حالة وفاة الأخ أو الأخت تحتسب من تاريخ الوفاة. 2 يحق- للعامل المريض بفشل كلوي إجازة مدفوعة الأجر في اليوم الذي يجرى له فيه الغسيل الكلوي للتنقية الدموية، وذلك بموجب تقرير من الجهة الطبية التي تتولى علاجه','[{"index":1,"marker":null,"text":"يحق للعامل الحصول على إجازة بأجر كامل في الحالات التالية: 1 ثلاثة- أيام في حالة وفاة الأخ أو الأخت تحتسب من تاريخ الوفاة. 2 يحق- للعامل المريض بفشل كلوي إجازة مدفوعة الأجر في اليوم الذي يجرى له فيه الغسيل الكلوي للتنقية الدموية، وذلك بموجب تقرير من الجهة الطبية التي تتولى علاجه"}]','["يحق","كلو","وفا","حصول","اجاز","باجر","كامل","الاخ","اخت","بفشل"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-095','policy-doc-work-regulation',NULL,'الرعاية الطبية',16,95,'وفقا لما يقرره نظام التأمين الصحي التعاوني ولائحته','proposed','وفقا لما يقرره نظام التأمين الصحي التعاوني ولائحته، التنفيذية، تقوم المنشأة بالتأمين على جميع العاملين لديها صحيًا؛ كما تقوم بالاشتراك عن جميع العاملين في فرع الأخطار المهنية لدى المؤسسة العامة للتأمينات الاجتماعية؛ وفقًا لما يقرره نظامها.','[{"index":1,"marker":null,"text":"وفقا لما يقرره نظام التأمين الصحي التعاوني ولائحته، التنفيذية، تقوم المنشأة بالتأمين على جميع العاملين لديها صحيًا؛ كما تقوم بالاشتراك عن جميع العاملين في فرع الأخطار المهنية لدى المؤسسة العامة للتأمينات الاجتماعية؛ وفقًا لما يقرره نظامها."}]','["يقرر","لما","تام","ولايح","تعا","صحي","تقوم","نظام","صحيا","جميع"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-096','policy-doc-work-regulation',NULL,'الرعاية الطبية',16,96,'الوقاية والسلامة','extracted','1 سعياً- لحماية العاملين من الأخطار والأمراض الناجمة عن العمل تتخذ، المنشأة التدابير الآتية:
أ. الإعلان في أماكن ظاهرة عن أخطار العمل ووسائل الوقاية منها والتعليمات، اللازم اتباعها.
ب. حظر التدخين في أماكن العمل المُعلن عنها.
ج. تأمين أجهزة لإطفاء الحريق وإعداد، منافذ للنجاة في حالات الطوارئ.
د. إبقاء أماكن العمل في حالة نظافة تامة.
ه. توفير المياه الصالحة للشرب والاستعمال.
و. توفير دورات المياه بالمستوى الصحي المطلوب.
ز. تأمين وسائل السلامة وأدوات الوقاية وتدريب، العاملين على استخدامها. 2 يجب- على كافة العاملين التقيد بتعليمات السلامة والوقاية التي، تصدرها المنشأة. يصدر-3 صاحب الصلاحية قرارًا بتحديد الشخص أو الأشخاص المسؤولين عن الوقاية والسلامة في المنشأة ويترتب، عليهم القيام بالإجراءات الآتية:
أ. تنمية الوعي الوقائي لدى العاملين.
ب. التفتيش الدوري بغرض التأكد من سلامة الأجهزة وحسن، استعمال وسائل الوقاية والسلامة اللازمة.
ج. معاينة الحوادث وتسجيلها وإعداد، تقارير عنها تتضمن الوسائل والاحتياطات الكفيلة بتلافي تكرارها.
د. مراقبة تنفيذ قواعد الوقاية والسلامة بشكل دوري.','[{"index":1,"marker":null,"text":"1 سعياً- لحماية العاملين من الأخطار والأمراض الناجمة عن العمل تتخذ، المنشأة التدابير الآتية:"},{"index":2,"marker":"أ","text":"الإعلان في أماكن ظاهرة عن أخطار العمل ووسائل الوقاية منها والتعليمات، اللازم اتباعها."},{"index":3,"marker":"ب","text":"حظر التدخين في أماكن العمل المُعلن عنها."},{"index":4,"marker":"ج","text":"تأمين أجهزة لإطفاء الحريق وإعداد، منافذ للنجاة في حالات الطوارئ."},{"index":5,"marker":"د","text":"إبقاء أماكن العمل في حالة نظافة تامة."},{"index":6,"marker":"ه","text":"توفير المياه الصالحة للشرب والاستعمال."},{"index":7,"marker":"و","text":"توفير دورات المياه بالمستوى الصحي المطلوب."},{"index":8,"marker":"ز","text":"تأمين وسائل السلامة وأدوات الوقاية وتدريب، العاملين على استخدامها. 2 يجب- على كافة العاملين التقيد بتعليمات السلامة والوقاية التي، تصدرها المنشأة. يصدر-3 صاحب الصلاحية قرارًا بتحديد الشخص أو الأشخاص المسؤولين عن الوقاية والسلامة في المنشأة ويترتب، عليهم القيام بالإجراءات الآتية:"},{"index":9,"marker":"أ","text":"تنمية الوعي الوقائي لدى العاملين."},{"index":10,"marker":"ب","text":"التفتيش الدوري بغرض التأكد من سلامة الأجهزة وحسن، استعمال وسائل الوقاية والسلامة اللازمة."},{"index":11,"marker":"ج","text":"معاينة الحوادث وتسجيلها وإعداد، تقارير عنها تتضمن الوسائل والاحتياطات الكفيلة بتلافي تكرارها."},{"index":12,"marker":"د","text":"مراقبة تنفيذ قواعد الوقاية والسلامة بشكل دوري."}]','["وقا","سلام","واعداد","ميا","اماكن","اجهز","توفير","استعمال","دور","تام"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-097','policy-doc-work-regulation',NULL,'الرعاية الطبية',16,97,'الإسعاف الطبي','extracted','تؤمن المنشأة في مقر العمل خزانة للإسعافات الطبية تحتوي على كميات كافية من الأدوية والأربطة والمطهرات وغير، ذلك مما أشارت إليه (المادة 142 من) نظام العمل ويُعهد، إلى عامل مدرب أو أكثر إجراء الإسعافات اللازمة للعاملين المصابين.','[{"index":1,"marker":null,"text":"تؤمن المنشأة في مقر العمل خزانة للإسعافات الطبية تحتوي على كميات كافية من الأدوية والأربطة والمطهرات وغير، ذلك مما أشارت إليه (المادة 142 من) نظام العمل ويُعهد، إلى عامل مدرب أو أكثر إجراء الإسعافات اللازمة للعاملين المصابين."}]','["اسعاف","طبي","خزان","تحتو","كمي","اربط","مطهر","اشارت","142","ويعهد"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-098','policy-doc-work-regulation',NULL,'الرعاية الطبية',16,98,'الرعاية والتأمين الصحي','extracted','1 تتكفل- المنشأة بتأمين صحي للعامل وأسرته وفقاً، لوثيقة التأمين الطبي وذلك، بالتعاقد مع إحدى شركات التأمين التعاوني. 2 المُعارون- المتفرّغون يُؤمّن عليهم وعلى، أسرهم؛ بحسب ما يقرره صاحب الصلاحية لكل حالة على حدة. 3 تستمر- التغطية التأمينية لأفراد عائلة العامل المُتوفّى حتى انتهاء صلاحية وثيقة التأمين الطبي.','[{"index":1,"marker":null,"text":"1 تتكفل- المنشأة بتأمين صحي للعامل وأسرته وفقاً، لوثيقة التأمين الطبي وذلك، بالتعاقد مع إحدى شركات التأمين التعاوني. 2 المُعارون- المتفرّغون يُؤمّن عليهم وعلى، أسرهم؛ بحسب ما يقرره صاحب الصلاحية لكل حالة على حدة. 3 تستمر- التغطية التأمينية لأفراد عائلة العامل المُتوفّى حتى انتهاء صلاحية وثيقة التأمين الطبي."}]','["تام","صحي","رعا","تتكفل","لوثيق","يومن","تستمر","لافراد","عايل","متوف"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-099','policy-doc-work-regulation',NULL,'الرعاية الطبية',16,99,'إصابات العمل وأمراض المهنة','extracted','1 على- العامل الذي يُصاب بإصابة عمل أو مرض مهني أن يُبلّغ مدير الإدارة فور استطاعته، أو يُوكّل بذلك أحد زملائه، وله مراجعة الطبيب مباشرة متى استدعت حالته ذلك. 2 يُطبّق- في شأن إصابات العمل والأمراض المهنية أحكام فرع الأخطار المهنية من نظام التأمينات الاجتماعية. 3 يجب- على كل مسؤول أن يبلغ الجهة المختصة في المنشأة عن حدوث أية إصابة وما، تم اتخاذه من إسعافات طبية نحو المصاب والوقت، الذي استغرقه ذلك كما، تخضع جميع الحوادث للتحقيق والتحليل؛ للوصول إلى أسباب الإصابة والإجراءات المُتّخذة لتلافيها. مستقبلاً','[{"index":1,"marker":null,"text":"1 على- العامل الذي يُصاب بإصابة عمل أو مرض مهني أن يُبلّغ مدير الإدارة فور استطاعته، أو يُوكّل بذلك أحد زملائه، وله مراجعة الطبيب مباشرة متى استدعت حالته ذلك. 2 يُطبّق- في شأن إصابات العمل والأمراض المهنية أحكام فرع الأخطار المهنية من نظام التأمينات الاجتماعية. 3 يجب- على كل مسؤول أن يبلغ الجهة المختصة في المنشأة عن حدوث أية إصابة وما، تم اتخاذه من إسعافات طبية نحو المصاب والوقت، الذي استغرقه ذلك كما، تخضع جميع الحوادث للتحقيق والتحليل؛ للوصول إلى أسباب الإصابة والإجراءات المُتّخذة لتلافيها. مستقبلاً"}]','["اصاب","مهن","وامراض","يبلغ","يصاب","باصاب","استطاع","يوكل","استدعت","يطبق"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-100','policy-doc-work-regulation',NULL,'الرعاية الطبية',16,100,'الرعاية والخدمات الاجتماعية','extracted','فإن المنشأة تتولى؛ 1 تُخصّص- المنشأة مكانًا لتأدية الصلاة المفروضة في موقع العمل. إذا-2 تعرّض أحد عاملي المنشأة للإيقاف من السلطات الحكومية بسبب قيامه بأعمال تابعة للمنشأة متابعة قضيته وتوكيل، محامٍ عند اللزوم ويتحمل، المنشأة كافة مصاريف القضية إذا، كان ما صدر عنه من تصرف لا يخالف الأنظمة واللوائح التي، تحكم عمل المنشأة. احكام خاصة بالمرأة','[{"index":1,"marker":null,"text":"فإن المنشأة تتولى؛ 1 تُخصّص- المنشأة مكانًا لتأدية الصلاة المفروضة في موقع العمل. إذا-2 تعرّض أحد عاملي المنشأة للإيقاف من السلطات الحكومية بسبب قيامه بأعمال تابعة للمنشأة متابعة قضيته وتوكيل، محامٍ عند اللزوم ويتحمل، المنشأة كافة مصاريف القضية إذا، كان ما صدر عنه من تصرف لا يخالف الأنظمة واللوائح التي، تحكم عمل المنشأة. احكام خاصة بالمرأة"}]','["قضي","رعا","تخصص","مكا","باعمال","متابع","وتوكيل","محام","لزوم","ويتحمل"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-101','policy-doc-work-regulation',NULL,'أحكام خاصة بالمرأة',17,101,'للمرأة العاملة الحق في إجازة وضع بأجر كامل لمدة','proposed','للمرأة العاملة الحق في إجازة وضع بأجر كامل لمدة عشرة أسابيع توزعها كيف تشاء بحيث، تبدأ بحد أقصى بأربعة أسابيع قبل التاريخ المرجح للوضع؛ ويحدد هذا التاريخ بواسطة الجهة الطبية المعتمدة لدى المنشأة، أو بشهادة طبية مصدقة من جهة صحية ولا، يجوز تشغيل المرأة العاملة خلال الأسابيع الستة التالية لوضعها. وفي حالة إنجاب طفل مريض، أو من ذوي الاحتياجات الخاصة؛ فللعاملة الحق في إجازة بأجر كامل لمدة شهر واحد بعد انقضاء إجازة الوضع؛ ولها تمديد الإجازة لمدة شهر دون أجر.','[{"index":1,"marker":null,"text":"للمرأة العاملة الحق في إجازة وضع بأجر كامل لمدة عشرة أسابيع توزعها كيف تشاء بحيث، تبدأ بحد أقصى بأربعة أسابيع قبل التاريخ المرجح للوضع؛ ويحدد هذا التاريخ بواسطة الجهة الطبية المعتمدة لدى المنشأة، أو بشهادة طبية مصدقة من جهة صحية ولا، يجوز تشغيل المرأة العاملة خلال الأسابيع الستة التالية لوضعها. وفي حالة إنجاب طفل مريض، أو من ذوي الاحتياجات الخاصة؛ فللعاملة الحق في إجازة بأجر كامل لمدة شهر واحد بعد انقضاء إجازة الوضع؛ ولها تمديد الإجازة لمدة شهر دون أجر."}]','["وضع","لمد","اسابيع","مرا","اجاز","باجر","كامل","كيف","تشاء","بحد"]','["clause_reflow"]','2025-04-25','replaced','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-102','policy-doc-work-regulation',NULL,'أحكام خاصة بالمرأة',17,102,'يحق للمرأة العاملة في المنشأة عندما تعود إلى مزاولة','proposed','يحق للمرأة العاملة في المنشأة عندما تعود إلى مزاولة عملها بعد إجازة الوضع أن تأخذ بقصد إرضاع مولودها فترة، أو فترات استراحة لا، تزيد في مجموعها على الساعة في اليوم الواحد وذلك، علاوة على فترات الراحة الممنوحة لجميع العمال وتحسب، هذه الفترة، أو الفترات من ساعات العمل الفعلية، وذلك لمدة أربعة، وعشرين شهرًا من تاريخ الوضع، ولا يترتب على ذلك تخفيض الأجر ويجب، على المرأة العاملة بعد عودتها من إجازة الوضع إشعار صاحب العمل كتابةً بوقت فترة، أو فترات تلك الاستراحة وما، يطرأ على ذلك الوقت من تعديل وتحدد، فترة، أو فترات الرضاعة على ضوء ذلك بحسب ماورد في اللائحة التنفيذية لنظام العمل.','[{"index":1,"marker":null,"text":"يحق للمرأة العاملة في المنشأة عندما تعود إلى مزاولة عملها بعد إجازة الوضع أن تأخذ بقصد إرضاع مولودها فترة، أو فترات استراحة لا، تزيد في مجموعها على الساعة في اليوم الواحد وذلك، علاوة على فترات الراحة الممنوحة لجميع العمال وتحسب، هذه الفترة، أو الفترات من ساعات العمل الفعلية، وذلك لمدة أربعة، وعشرين شهرًا من تاريخ الوضع، ولا يترتب على ذلك تخفيض الأجر ويجب، على المرأة العاملة بعد عودتها من إجازة الوضع إشعار صاحب العمل كتابةً بوقت فترة، أو فترات تلك الاستراحة وما، يطرأ على ذلك الوقت من تعديل وتحدد، فترة، أو فترات الرضاعة على ضوء ذلك بحسب ماورد في اللائحة التنفيذية لنظام العمل."}]','["فتر","تعود","عندما","مزاول","مرا","استراح","يحق","وضع","ساع","تاخذ"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-103','policy-doc-work-regulation',NULL,'أحكام خاصة بالمرأة',17,103,'1 على- المنشأة توفير الرعاية الطبية للمرأة العاملة أثناء','proposed','1 على- المنشأة توفير الرعاية الطبية للمرأة العاملة أثناء الحمل والولادة. 2 لا- يجوز للمنشأة فصل العاملة أو إنذارها بالفصل أثناء تمتعها بإجازة الوضع. 3 لا- يجوز لصاحب العمل فصل العاملة أو انذارها بالفصل أثناء حملها أو تمتعها بإجازة الوضع ويشمل، ذلك مدّة مرضها الناشئ عن أي منهما على، أن يثبت المرض بشهادة طبيه معتمدة، وان، لا تتجاوز مدّة (غيابها 180 يومًا) في السنة سواءً أكانت متصلة أو متفرقة 4 يسقط- حق العاملة فيما تستحقه وفقًا، لأحكام هذا الفصل؛ إذا عملت لدى صاحب عمل آخر أثناء مدة إجازتها المصرح أن يحرمها من أجرها عن مدة الإجازة، أو أن يسترد ما دفع لها. – في هذه الحالة – بها وللمنشأة،','[{"index":1,"marker":null,"text":"1 على- المنشأة توفير الرعاية الطبية للمرأة العاملة أثناء الحمل والولادة. 2 لا- يجوز للمنشأة فصل العاملة أو إنذارها بالفصل أثناء تمتعها بإجازة الوضع. 3 لا- يجوز لصاحب العمل فصل العاملة أو انذارها بالفصل أثناء حملها أو تمتعها بإجازة الوضع ويشمل، ذلك مدّة مرضها الناشئ عن أي منهما على، أن يثبت المرض بشهادة طبيه معتمدة، وان، لا تتجاوز مدّة (غيابها 180 يومًا) في السنة سواءً أكانت متصلة أو متفرقة 4 يسقط- حق العاملة فيما تستحقه وفقًا، لأحكام هذا الفصل؛ إذا عملت لدى صاحب عمل آخر أثناء مدة إجازتها المصرح أن يحرمها من أجرها عن مدة الإجازة، أو أن يسترد ما دفع لها. – في هذه الحالة – بها وللمنشأة،"}]','["اثناء","فصل","توفير","رعا","مرا","طبي","حمل","باجاز","مده","تمتع"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-104','policy-doc-work-regulation',NULL,'أحكام خاصة بالمرأة',17,104,'أماكن العمل للمرأة','extracted','على المنشأة أن توفر في جميع الأماكن التي تعمل فيها النساء أماكن خاصة بهنّ لاستراحتهن.','[{"index":1,"marker":null,"text":"على المنشأة أن توفر في جميع الأماكن التي تعمل فيها النساء أماكن خاصة بهنّ لاستراحتهن."}]','["اماكن","مرا","تعمل","بهن","لاستراحت","نساء","توفر","فيها","جميع","خاص"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-105','policy-doc-work-regulation',NULL,'أحكام خاصة بالمرأة',17,105,'حقوق المرأة العاملة في إجازة الوضع ورعاية','proposed','تحل هذه المادة محل المادة المتعلقة ( حقوق المرأة العاملة في إجازة الوضع ورعاية )المولود 1 للمرأة. العاملة الحق في إجازة وضع باجر كامل (لمدة اثني عشر أسبوغا) منها، وجوبيًا الأسابيع الستة التالية للوضع، ولها أن توزع الأسابيع الستة المتبقية وفق ما تراه ابتداء، من أربعة أسابيع قبل التاريخ المرجح للوضع. ويحدد التاريخ المرجح للوضع بموجب شهادة طبية مصدقة من جهة صحية. وفي حال قل المتبقي من مدة الإجازة (عن ستة أسابيع) نتيجة تأخر الوضع عن تاريخه المرجح فتحتسب، المدة المكملة لها إجازة دون أجر. وفي جميع الأحوال يحق للمرأة العاملة تمديد هذه (الإجازة شهراً دون) أجر 2 للمراة. العاملة - في حالة إنجاب طفل مريض أو من ذوي الإعاقة وتتطلب حالته الصحية مرافقاً مستمراً له الحق- في إجازة (مدتها شهر باجر) كامل تبدأ بعد انتهاء مدة إجازة الوضع ولها، الحق في تمديد الإجازة لمدة شهر دون أجر.','[{"index":1,"marker":null,"text":"تحل هذه المادة محل المادة المتعلقة ( حقوق المرأة العاملة في إجازة الوضع ورعاية )المولود 1 للمرأة. العاملة الحق في إجازة وضع باجر كامل (لمدة اثني عشر أسبوغا) منها، وجوبيًا الأسابيع الستة التالية للوضع، ولها أن توزع الأسابيع الستة المتبقية وفق ما تراه ابتداء، من أربعة أسابيع قبل التاريخ المرجح للوضع. ويحدد التاريخ المرجح للوضع بموجب شهادة طبية مصدقة من جهة صحية. وفي حال قل المتبقي من مدة الإجازة (عن ستة أسابيع) نتيجة تأخر الوضع عن تاريخه المرجح فتحتسب، المدة المكملة لها إجازة دون أجر. وفي جميع الأحوال يحق للمرأة العاملة تمديد هذه (الإجازة شهراً دون) أجر 2 للمراة. العاملة - في حالة إنجاب طفل مريض أو من ذوي الإعاقة وتتطلب حالته الصحية مرافقاً مستمراً له الحق- في إجازة (مدتها شهر باجر) كامل تبدأ بعد انتهاء مدة إجازة الوضع ولها، الحق في تمديد الإجازة لمدة شهر دون أجر."}]','["وضع","مرا","اجاز","اسابيع","ورعا","مرجح","سته","حقوق","متبق","ولها"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-106','policy-doc-work-regulation',NULL,'الخدمات الاجتماعية',18,106,'تلتزم المنشأة بتقديم الخدمات الاجتماعية التالية','proposed','تلتزم المنشأة بتقديم الخدمات الاجتماعية التالية:
1. إعداد مكان لأداء الصلاة.
2. إعداد مكان لتناول الطعام.
3. توفر المنشأة المتطلبات والخدمات، والمرافق، التيسيرية الضرورية للعمال من ذوي الاعاقة التي تمكنهم من أداء أعمالهم بحسب الاشتراطات المنصوص عليها في اللائحة التنفيذية لنظام العمل. ضوابط سلوكيات العمل','[{"index":1,"marker":null,"text":"تلتزم المنشأة بتقديم الخدمات الاجتماعية التالية:"},{"index":2,"marker":"1","text":"إعداد مكان لأداء الصلاة."},{"index":3,"marker":"2","text":"إعداد مكان لتناول الطعام."},{"index":4,"marker":"3","text":"توفر المنشأة المتطلبات والخدمات، والمرافق، التيسيرية الضرورية للعمال من ذوي الاعاقة التي تمكنهم من أداء أعمالهم بحسب الاشتراطات المنصوص عليها في اللائحة التنفيذية لنظام العمل. ضوابط سلوكيات العمل"}]','["بتقديم","تلتزم","اعداد","اجتماع","خدم","تال","مكان","لتناول","تيسير","سلوكي"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-107','policy-doc-work-regulation',NULL,'ضوابط السلوك',19,107,'يجب على كل منشأة وضع تنظيم لاشتراطات زي العاملين','proposed','1. يجب على كل منشأة وضع تنظيم لاشتراطات زي العاملين لديها نساءً ورجالاً وفق الضوابط التالية:
2. الا يتعارض مع الأحكام الشرعية.
3. أن يكون بمظهر مهني لائق يتناسب مع مهام العامل في مكان العمل.
4. أن يكون محتشماً وغير شفاف.
5. وضع العقوبات المترتبة على مخالفة الاشتراطات.
6. إعلان تلك الاشتراطات على حده في مكان ظاهر بالمنشأة أو أي وسيلة أخرى تكفل علم الخاضعين لها بأحكامها، وإقرارهم بالعلم بها.
7. على جميع العاملين بالمنشأة الالتزام بمقتضيات أحكام الشريعة الإسلامية والأعراف، الاجتماعية المرعية في التعامل مع الآخرين.
8. يمتنع على جميع العاملين الخلوة مع الجنس الآخر وعلى، المنشأة أن تتخذ كل التدابير التي تمنع الخلوة بين الجنسين داخل المنشأة.
9. على جميع العاملين الامتناع عن القيام بأي شكل من أشكال الإيذاء، أو الإساءة الجسدية، أو القولية، أو الإيحائية، أو باتخاذ أي موقف يخدش الحياء، أو ينال من الكرامة، أو السمعة، أو الحرية، أو يقصد منه استدراج، أو إجبار أي شخص إلى علاقة غير مشروعة حتى، لو كان ذلك على سبيل المزاح وذلك، عند التواصل المباشر، أو بأي وسيلة تواصل أخرى وللمنشأة، أن تتخذ كل الترتيبات والإجراءات، الضرورية واللازمة، لتبليغ جميع العاملين بذلك.','[{"index":1,"marker":"1","text":"يجب على كل منشأة وضع تنظيم لاشتراطات زي العاملين لديها نساءً ورجالاً وفق الضوابط التالية:"},{"index":2,"marker":"2","text":"الا يتعارض مع الأحكام الشرعية."},{"index":3,"marker":"3","text":"أن يكون بمظهر مهني لائق يتناسب مع مهام العامل في مكان العمل."},{"index":4,"marker":"4","text":"أن يكون محتشماً وغير شفاف."},{"index":5,"marker":"5","text":"وضع العقوبات المترتبة على مخالفة الاشتراطات."},{"index":6,"marker":"6","text":"إعلان تلك الاشتراطات على حده في مكان ظاهر بالمنشأة أو أي وسيلة أخرى تكفل علم الخاضعين لها بأحكامها، وإقرارهم بالعلم بها."},{"index":7,"marker":"7","text":"على جميع العاملين بالمنشأة الالتزام بمقتضيات أحكام الشريعة الإسلامية والأعراف، الاجتماعية المرعية في التعامل مع الآخرين."},{"index":8,"marker":"8","text":"يمتنع على جميع العاملين الخلوة مع الجنس الآخر وعلى، المنشأة أن تتخذ كل التدابير التي تمنع الخلوة بين الجنسين داخل المنشأة."},{"index":9,"marker":"9","text":"على جميع العاملين الامتناع عن القيام بأي شكل من أشكال الإيذاء، أو الإساءة الجسدية، أو القولية، أو الإيحائية، أو باتخاذ أي موقف يخدش الحياء، أو ينال من الكرامة، أو السمعة، أو الحرية، أو يقصد منه استدراج، أو إجبار أي شخص إلى علاقة غير مشروعة حتى، لو كان ذلك على سبيل المزاح وذلك، عند التواصل المباشر، أو بأي وسيلة تواصل أخرى وللمنشأة، أن تتخذ كل الترتيبات والإجراءات، الضرورية واللازمة، لتبليغ جميع العاملين بذلك."}]','["لاشتراط","وضع","تنظيم","خلو","جميع","تتخذ","تواصل","اشتراط","جنس","اخر"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-108','policy-doc-work-regulation',NULL,'ضوابط السلوك',19,108,'يعتبر من قبيل الايذاء جميع','proposed','1. يعتبر من قبيل الايذاء جميع، ممارسات الإساءة الإيجابية، أو السلبية وجميع، أشكال الاستغلال، أو الابتزاز، أو الإغراء، أو التهديد سواء، أكانت جسدية، أو نفسية، أو جنسية؛ والتي تقع في مكان العمل من قبل صاحب العمل على العامل، أو من قبل العامل على صاحب العمل، أو من قبل عامل على آخر، أو على أي شخص موجود في مكان العمل وتعتبر، المساعدة، والتستر على ذلك في حكم الإيذاء.
2. يعتبر من قبيل الايذاء المقصود في الفقرة السابقة ما، يقع باستخدام أية وسيلة من وسائل الاتصال سواء بالقول، أو الكتابة، أو الاشارة، أو الايحاء، أو الرسم، أو باستخدام الهاتف، أو بالوسائل الإلكترونية الأخرى، أو بأي شكل من أشكال السلوك الذي يدل على ذلك.','[{"index":1,"marker":"1","text":"يعتبر من قبيل الايذاء جميع، ممارسات الإساءة الإيجابية، أو السلبية وجميع، أشكال الاستغلال، أو الابتزاز، أو الإغراء، أو التهديد سواء، أكانت جسدية، أو نفسية، أو جنسية؛ والتي تقع في مكان العمل من قبل صاحب العمل على العامل، أو من قبل العامل على صاحب العمل، أو من قبل عامل على آخر، أو على أي شخص موجود في مكان العمل وتعتبر، المساعدة، والتستر على ذلك في حكم الإيذاء."},{"index":2,"marker":"2","text":"يعتبر من قبيل الايذاء المقصود في الفقرة السابقة ما، يقع باستخدام أية وسيلة من وسائل الاتصال سواء بالقول، أو الكتابة، أو الاشارة، أو الايحاء، أو الرسم، أو باستخدام الهاتف، أو بالوسائل الإلكترونية الأخرى، أو بأي شكل من أشكال السلوك الذي يدل على ذلك."}]','["قبيل","ايذاء","يعتبر","باستخدام","اشكال","جميع","سواء","مكان","وسايل","ممارس"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-109','policy-doc-work-regulation',NULL,'ضوابط السلوك',19,109,'مع عدم الإخلال بحق من وقع عليه الإيذاء','proposed','1. مع عدم الإخلال بحق من وقع عليه الإيذاء في مكان العمل من الالتجاء إلى الجهات الحكومية المختصة يحق، له التقدم بشكواه للمنشأة خلال مدة أقصاها خمسة أيام عمل من وقوع الإيذاء عليه ويجوز، لكل من شاهد أو اطلع على واقعة أما إذا كان الإيذاء قد وقع من قبل صاحب المنشأة، أو من أعلى سلطة فيها؛ إيذاء التقدم، ببلاغ للمنشأة بذلك؛ فيكون التقدم بالشكوى للجهة الحكومية المختصة.
2. على المنشأة عند تقديم شكوى، أو بلاغ تشكيل، لجنة بقرار من المسؤول المختص تكون، مهمتها التحقيق في حالات الإيذاء والاطلاع، على الأدلة والتوصية، بإيقاع الجزاء التأديبي المناسب على من ثبتت إدانته وذلك، خلال خمسة أيام عمل من تلقيها الشكوى، أو البلاغ.','[{"index":1,"marker":"1","text":"مع عدم الإخلال بحق من وقع عليه الإيذاء في مكان العمل من الالتجاء إلى الجهات الحكومية المختصة يحق، له التقدم بشكواه للمنشأة خلال مدة أقصاها خمسة أيام عمل من وقوع الإيذاء عليه ويجوز، لكل من شاهد أو اطلع على واقعة أما إذا كان الإيذاء قد وقع من قبل صاحب المنشأة، أو من أعلى سلطة فيها؛ إيذاء التقدم، ببلاغ للمنشأة بذلك؛ فيكون التقدم بالشكوى للجهة الحكومية المختصة."},{"index":2,"marker":"2","text":"على المنشأة عند تقديم شكوى، أو بلاغ تشكيل، لجنة بقرار من المسؤول المختص تكون، مهمتها التحقيق في حالات الإيذاء والاطلاع، على الأدلة والتوصية، بإيقاع الجزاء التأديبي المناسب على من ثبتت إدانته وذلك، خلال خمسة أيام عمل من تلقيها الشكوى، أو البلاغ."}]','["ايذاء","وقع","تقدم","شكو","بحق","اخلال","بلاغ","حكوم","مختص","عدم"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-110','policy-doc-work-regulation',NULL,'ضوابط السلوك',19,110,'مع مراعاة مبدأ السرية تستمع اللجنة لجميع الأطراف والشهود','proposed','1. مع مراعاة مبدأ السرية تستمع اللجنة لجميع الأطراف والشهود، وتدون، كل ما يجري في محاضر؛ توقع من الأطراف، و الشهود على أقوالهم، ثم توقع من أعضاء اللجنة في نهاية كل صفحة.
2. للّجنة حق استدعاء من ترى ضرورة استجوابه من العاملين، والاستماع إلى أقواله وعلى، من تم استدعاؤه المثول أمام اللجنة؛ حتى لا يقع تحت طائلة المسؤولية.
3. يجوز للّجنة أن ترفع توصية لإدارة المنشأة بالتفريق بين الشاكي والمشكو، في حقه أثناء فترة التحقيق.
4. في حال ثبوت واقعة الإيذاء بأي طريقة من طرق الإثبات المعتبرة؛ توصي اللجنة بالأغلبية بإيقاع الجزاء التأديبي المناسب على المعتدي.
5. إذا كان الاعتداء يشكل جريمة جنائية وجب، على اللجنة رفع الشكوى للمدير العام؛ لتبليغ الجهات الحكومية المختصة بذلك.
6. في حال عدم ثبوت واقعة الإيذاء توصي، اللجنة بإيقاع عقوبة تأديبية على المبلغ إذا، تبين لها أن الشكوى، أو البلاغ كيدي.
7. لا يمنع الجزاء التأديبي الموقع من قبل المنشأة على المعتدي من، حق المعتدى عليه اللجوء للجهات الحكومية المختصة.
8. لا يمنع توقيع عقوبة شرعية، أو نظامية أخرى على المعتدي من، توقيع المنشأة جزاءً تأديبيًا عليه.','[{"index":1,"marker":"1","text":"مع مراعاة مبدأ السرية تستمع اللجنة لجميع الأطراف والشهود، وتدون، كل ما يجري في محاضر؛ توقع من الأطراف، و الشهود على أقوالهم، ثم توقع من أعضاء اللجنة في نهاية كل صفحة."},{"index":2,"marker":"2","text":"للّجنة حق استدعاء من ترى ضرورة استجوابه من العاملين، والاستماع إلى أقواله وعلى، من تم استدعاؤه المثول أمام اللجنة؛ حتى لا يقع تحت طائلة المسؤولية."},{"index":3,"marker":"3","text":"يجوز للّجنة أن ترفع توصية لإدارة المنشأة بالتفريق بين الشاكي والمشكو، في حقه أثناء فترة التحقيق."},{"index":4,"marker":"4","text":"في حال ثبوت واقعة الإيذاء بأي طريقة من طرق الإثبات المعتبرة؛ توصي اللجنة بالأغلبية بإيقاع الجزاء التأديبي المناسب على المعتدي."},{"index":5,"marker":"5","text":"إذا كان الاعتداء يشكل جريمة جنائية وجب، على اللجنة رفع الشكوى للمدير العام؛ لتبليغ الجهات الحكومية المختصة بذلك."},{"index":6,"marker":"6","text":"في حال عدم ثبوت واقعة الإيذاء توصي، اللجنة بإيقاع عقوبة تأديبية على المبلغ إذا، تبين لها أن الشكوى، أو البلاغ كيدي."},{"index":7,"marker":"7","text":"لا يمنع الجزاء التأديبي الموقع من قبل المنشأة على المعتدي من، حق المعتدى عليه اللجوء للجهات الحكومية المختصة."},{"index":8,"marker":"8","text":"لا يمنع توقيع عقوبة شرعية، أو نظامية أخرى على المعتدي من، توقيع المنشأة جزاءً تأديبيًا عليه."}]','["لجن","اطراف","شهود","معتد","مبدا","تستمع","مراعا","سري","توص","يمنع"]','["broken_glyphs","clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-111','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,111,'المخالفة هي كل فعل من الأفعال التي يرتكبها العامل','proposed','المخالفة هي كل فعل من الأفعال التي يرتكبها العامل وتستوجب، أيًا من الجزاءات التالية:
1. الإنذار الكتابي وهو: كتاب توجهه المنشأة إلى العامل موضحًا به نوع المخالفة التي ارتكبها مع، لفت نظره إلى إمكان تعرضه إلى جزاء أشد،في حالة استمرار المخالفة،أو العودة إلى مثلها مستقبلاً.
2. غرامة مالية وهي: حسم نسبة من الأجر في حدود جزء من الأجر اليومي، أو الحسم من الأجر بما يترواح بين أجر يوم، و خمسة أيام في الشهر الواحد كحد أقصى.
3. الإيقاف عن العمل بدون أجر وهو: منع العامل من مزاولة عمله خلال فترة معينة مع، حرمانه من أجره خلال هذه الفترة، على أن لا تتجاوز فترة الإيقاف خمسة أيام في الشهر الواحد.
4. الحرمان من الترقية، أو العلاوة الدورية وذلك: لمدة أقصاها سنة واحدة من تاريخ استحقاقها.
5. الفصل من الخدمة مع المكافأة وهو: فصل العامل بناءً على سبب مشروع لارتكابه: المخالفة مع عدم المساس بحقه في مكافأة نهاية الخدمة.
6. الفصل من الخدمة بدون مكافأة: وهو فسخ عقد عمل العامل دون مكافأة، أو إشعار، أو تعويض لارتكابه، أي من الحالات المنصوص عليها في (المادة الثمانون من) نظام العمل. ويجب أن يتناسب الجزاء المفروض على العامل مع نوع ومدى، جسامة المخالفة المرتكبة من قبله.','[{"index":1,"marker":null,"text":"المخالفة هي كل فعل من الأفعال التي يرتكبها العامل وتستوجب، أيًا من الجزاءات التالية:"},{"index":2,"marker":"1","text":"الإنذار الكتابي وهو: كتاب توجهه المنشأة إلى العامل موضحًا به نوع المخالفة التي ارتكبها مع، لفت نظره إلى إمكان تعرضه إلى جزاء أشد،في حالة استمرار المخالفة،أو العودة إلى مثلها مستقبلاً."},{"index":3,"marker":"2","text":"غرامة مالية وهي: حسم نسبة من الأجر في حدود جزء من الأجر اليومي، أو الحسم من الأجر بما يترواح بين أجر يوم، و خمسة أيام في الشهر الواحد كحد أقصى."},{"index":4,"marker":"3","text":"الإيقاف عن العمل بدون أجر وهو: منع العامل من مزاولة عمله خلال فترة معينة مع، حرمانه من أجره خلال هذه الفترة، على أن لا تتجاوز فترة الإيقاف خمسة أيام في الشهر الواحد."},{"index":5,"marker":"4","text":"الحرمان من الترقية، أو العلاوة الدورية وذلك: لمدة أقصاها سنة واحدة من تاريخ استحقاقها."},{"index":6,"marker":"5","text":"الفصل من الخدمة مع المكافأة وهو: فصل العامل بناءً على سبب مشروع لارتكابه: المخالفة مع عدم المساس بحقه في مكافأة نهاية الخدمة."},{"index":7,"marker":"6","text":"الفصل من الخدمة بدون مكافأة: وهو فسخ عقد عمل العامل دون مكافأة، أو إشعار، أو تعويض لارتكابه، أي من الحالات المنصوص عليها في (المادة الثمانون من) نظام العمل. ويجب أن يتناسب الجزاء المفروض على العامل مع نوع ومدى، جسامة المخالفة المرتكبة من قبله."}]','["وهو","افعال","مخالف","يرتكب","فصل","مكافا","حرم","لارتكاب","حسم","ايقاف"]','["broken_glyphs"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-112','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,112,'كل عامل يرتكب أيًا من المخالفات الواردة في جداول','proposed','كل عامل يرتكب أيًا من المخالفات الواردة في جداول المخالفات والجزاءات، الملحق- بهذه اللائحة يعاقب- بالجزاء الموضح قرين المخالفة التي ارتكبها.','[{"index":1,"marker":null,"text":"كل عامل يرتكب أيًا من المخالفات الواردة في جداول المخالفات والجزاءات، الملحق- بهذه اللائحة يعاقب- بالجزاء الموضح قرين المخالفة التي ارتكبها."}]','["جداول","يرتكب","ايا","مخالف","وارد","ملحق","يعاقب","قرين","جزاء","موضح"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-113','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,113,'تكون صلاحية توقيع الجزاءات المنصوص عليها في هذه اللائحة','proposed','تكون صلاحية توقيع الجزاءات المنصوص عليها في هذه اللائحة من، (قبل صاحب الصلاحية بالمنشأة)، أو من يفوضه، ويجوز له استبدال الجزاء المقرر لأية مخالفة بجزاء أخف.','[{"index":1,"marker":null,"text":"تكون صلاحية توقيع الجزاءات المنصوص عليها في هذه اللائحة من، (قبل صاحب الصلاحية بالمنشأة)، أو من يفوضه، ويجوز له استبدال الجزاء المقرر لأية مخالفة بجزاء أخف."}]','["جزاء","توقيع","منصوص","لايح","استبدال","بجزاء","اخف","يفوض","لاي","مقرر"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-114','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,114,'فإنه لا يعتبر عائداً وتعد','proposed','فإنه لا يعتبر عائداً وتعد، مخالفة، في حال ارتكاب العامل ذات المخالفة بعد مضي مائة وثمانين يوماً على سبق ارتكابها؛ وكأنها ارتكبت للمرة الأولى.','[{"index":1,"marker":null,"text":"فإنه لا يعتبر عائداً وتعد، مخالفة، في حال ارتكاب العامل ذات المخالفة بعد مضي مائة وثمانين يوماً على سبق ارتكابها؛ وكأنها ارتكبت للمرة الأولى."}]','["عايدا","وتعد","ارتكاب","يعتبر","فان","وثم","وكان","ارتكبت","ماي","سبق"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-115','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,115,'عند تعدد المخالفات الناشئة عن فعل واحد يكتفى','proposed','عند تعدد المخالفات الناشئة عن فعل واحد يكتفى، بتوقيع الجزاء الأشد من بين الجزاءات المقررة في هذه اللائحة.','[{"index":1,"marker":null,"text":"عند تعدد المخالفات الناشئة عن فعل واحد يكتفى، بتوقيع الجزاء الأشد من بين الجزاءات المقررة في هذه اللائحة."}]','["تعدد","يكتف","ناش","مخالف","فعل","واحد","بتوقيع","جزاء","اشد","مقرر"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-116','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,116,'لا يجوز أن يوقع على العامل عن المخالفة الواحدة','proposed','لا يجوز أن يوقع على العامل عن المخالفة الواحدة أكثر من جزاء واحد كما، لا يجوز أن يوقع على العامل عن المخالفة الواحدة غرامة تزيد قيمتها على أجر خمسة أيام ولا، أن يقتطع من أجره أكثر من أجر خمسة أيام في الشهر الواحد وفاءً للغرامات التي توقع عليه.','[{"index":1,"marker":null,"text":"لا يجوز أن يوقع على العامل عن المخالفة الواحدة أكثر من جزاء واحد كما، لا يجوز أن يوقع على العامل عن المخالفة الواحدة غرامة تزيد قيمتها على أجر خمسة أيام ولا، أن يقتطع من أجره أكثر من أجر خمسة أيام في الشهر الواحد وفاءً للغرامات التي توقع عليه."}]','["يوقع","واحد","مخالف","غرام","اكثر","وفاء","خمس","يقتطع","ايام","توقع"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-117','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,117,'لا توقع المنشأة أيًا من الجزاءات التي تتجاوز عقوبتها','proposed','لا توقع المنشأة أيًا من الجزاءات التي تتجاوز عقوبتها غرامة أجر يوم واحد إلا، بعد إبلاغ العامل كتابة بالمخالفات المنسوبة إليه، وسماع أقواله وتحقيق، دفاعه وذلك، بموجب محضر يودع بملفه الخاص.','[{"index":1,"marker":null,"text":"لا توقع المنشأة أيًا من الجزاءات التي تتجاوز عقوبتها غرامة أجر يوم واحد إلا، بعد إبلاغ العامل كتابة بالمخالفات المنسوبة إليه، وسماع أقواله وتحقيق، دفاعه وذلك، بموجب محضر يودع بملفه الخاص."}]','["ايا","عقوب","توقع","تتجاوز","جزاء","منسوب","وسماع","بملف","اقوال","دفاع"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-118','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,118,'لا يجوز للمنشأة توقيع أي جزاء على العامل لأمر','proposed','لا يجوز للمنشأة توقيع أي جزاء على العامل لأمر ارتكبه خارج مكان العمل إلا إذا كان له علاقة مباشرة بطبيعة عمله أو بالمنشأة أو بمديرها المسئول وذلك، دون الإخلال بحكم (المادة الثمانون من) نظام العمل.','[{"index":1,"marker":null,"text":"لا يجوز للمنشأة توقيع أي جزاء على العامل لأمر ارتكبه خارج مكان العمل إلا إذا كان له علاقة مباشرة بطبيعة عمله أو بالمنشأة أو بمديرها المسئول وذلك، دون الإخلال بحكم (المادة الثمانون من) نظام العمل."}]','["لامر","توقيع","جزاء","بطبيع","بمدير","مسيول","بحكم","ارتكب","اخلال","ثمان"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-119','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,119,'لا يجوز مساءلة العامل تأديبيًا عن مخالفة مضي','proposed','لا يجوز مساءلة العامل تأديبيًا عن مخالفة مضي على كشفها أكثر من ثلاثين يومًا من تاريخ علم المنشأة بمرتكبها دون، أن تقوم باتخاذ أي من إجراءات التحقيق بشأنها.','[{"index":1,"marker":null,"text":"لا يجوز مساءلة العامل تأديبيًا عن مخالفة مضي على كشفها أكثر من ثلاثين يومًا من تاريخ علم المنشأة بمرتكبها دون، أن تقوم باتخاذ أي من إجراءات التحقيق بشأنها."}]','["مساءل","تاديبيا","مضي","مخالف","بمرتكب","كشف","تقوم","باتخاذ","بشان","تحقيق"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-120','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,120,'لا يجوز للمنشأة توقيع أي جزاء على العامل إذا','proposed','لا يجوز للمنشأة توقيع أي جزاء على العامل إذا، مضى على تاريخ ثبوت المخالفة أكثر من ثلاثين يومًا.','[{"index":1,"marker":null,"text":"لا يجوز للمنشأة توقيع أي جزاء على العامل إذا، مضى على تاريخ ثبوت المخالفة أكثر من ثلاثين يومًا."}]','["توقيع","جزاء","ثبوت","مضي","اكثر","ثلاث","مخالف","يوما","تاريخ"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-121','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,121,'تلتزم المنشأة بإبلاغ العامل كتابة بما أُوقِع عليه','proposed','تلتزم المنشأة بإبلاغ العامل كتابة بما أُوقِع عليه من جزاءات ونوعها، ومقدارها، والجزاء، الذي سوف يتعرض له في حالة تكرار المخالفة وإذا، امتنع العامل عن استلام الإخطار، أو رفض التوقيع بالعلم، أو كان غائبا؛ على عنوانه المختار الثابت في ملف خدمته، أو بالبريد الالكتروني الشخصي الثابت بعقد العمل، أو المعتمد لدى المنشأة؛ يرسل إليه بالبريد المسجل ويترتب على التبليغ بأي من هذه الوسائل جميع الآثار القانونية.','[{"index":1,"marker":null,"text":"تلتزم المنشأة بإبلاغ العامل كتابة بما أُوقِع عليه من جزاءات ونوعها، ومقدارها، والجزاء، الذي سوف يتعرض له في حالة تكرار المخالفة وإذا، امتنع العامل عن استلام الإخطار، أو رفض التوقيع بالعلم، أو كان غائبا؛ على عنوانه المختار الثابت في ملف خدمته، أو بالبريد الالكتروني الشخصي الثابت بعقد العمل، أو المعتمد لدى المنشأة؛ يرسل إليه بالبريد المسجل ويترتب على التبليغ بأي من هذه الوسائل جميع الآثار القانونية."}]','["بابلاغ","اوقع","تلتزم","ثابت","بريد","كتاب","سوف","امتنع","استلام","غايبا"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-122','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,122,'وتحفظ يخصص لكل عامل صحيفة جزاءات يدون','proposed','وتحفظ يخصص لكل عامل صحيفة جزاءات يدون، فيها نوع المخالفة التي ارتكبها وتاريخ، وقوعها والجزاء، الموقع عليه؛ هذه الصحيفة في ملف خدمة العامل.','[{"index":1,"marker":null,"text":"وتحفظ يخصص لكل عامل صحيفة جزاءات يدون، فيها نوع المخالفة التي ارتكبها وتاريخ، وقوعها والجزاء، الموقع عليه؛ هذه الصحيفة في ملف خدمة العامل."}]','["صحيف","يدون","وتحفظ","يخصص","لكل","جزاء","نوع","وقوع","ارتكب","وتاريخ"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-123','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,123,'تقيد الغرامات الموقعة على العمال في سجل خاص','proposed','تقيد الغرامات الموقعة على العمال في سجل خاص؛ وفق أحكام (المادة الثالثة والسبعون من) نظام العمل ويكون، التصرف فيها بما يعود بالنفع على العمال من قبل اللجنة العمالية في المنشأة؛ وفي حالة عدم وجود لجنة عمالية يكون التصرف في الغرامات بموافقة وزارة الموارد البشرية والتنمية الاجتماعية.','[{"index":1,"marker":null,"text":"تقيد الغرامات الموقعة على العمال في سجل خاص؛ وفق أحكام (المادة الثالثة والسبعون من) نظام العمل ويكون، التصرف فيها بما يعود بالنفع على العمال من قبل اللجنة العمالية في المنشأة؛ وفي حالة عدم وجود لجنة عمالية يكون التصرف في الغرامات بموافقة وزارة الموارد البشرية والتنمية الاجتماعية."}]','["عمال","غرام","سجل","تقيد","موقع","لجن","خاص","تصرف","نفع","ثالث"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-124','policy-doc-work-regulation',NULL,'المخالفات والجزاءات',20,124,'المسؤوليات','extracted','يُعد-1 العامل مسؤولاً عن جميع تصرفاته ويجب، عليه التقيّد بجميع اللوائح والتعليمات المقررة في المنشأة والتصرف، انطلاقًا من حرصه على مصلحة المنشأة في أداء عمله على أكمل وجه. 2 بالإضافة- إلى أي مسؤوليات أخرى بموجب أنظمة ولوائح المنشأة؛ يعد مديرو الإدارات مسؤولين عن الآتي:
أ. توضيح السياسات الخاصة بالعمل في المنشأة والقواعد، والإجراءات والتعليمات المتعلقة بتطبيقها والتأكّد، من فهمها من قبل العاملين الذين يعملون تحت إشرافهم.
ب. التأكّد من تقيد العاملين تحت إشرافهم بقواعد الانضباط والسلوك الوظيفي.
ج. رصد المخالفات التي تصدر عن العاملين الذين يعملون تحت إشرافهم واتباع، الإجراءات المعتمدة بشأنها.
د. أن يكونوا قدوة في الأداء والسلوك، وتحمل، المسؤولية أمام العاملين الذين، يعملون تحت إشرافهم. 3 بالإضافة- إلى أي مسؤوليات أخرى بموجب أنظمة ولوائح المنشأة؛ تعد إدارة الموارد البشرية مسؤولة عن الآتي:
أ. توضيح الإجراءات المتعلقة بالجزاءات.
ب. تقديم المشورة حول تطبيق الجزاءات.
ج. التأكّد من تطبيق الجزاءات وفقًا، للقواعد والإجراءات والصلاحيات المعتمدة.
د. تطبيق القرارات التأديبية المتعلقة بالجزاءات وفقًا، للصلاحيات المعتمدة.','[{"index":1,"marker":null,"text":"يُعد-1 العامل مسؤولاً عن جميع تصرفاته ويجب، عليه التقيّد بجميع اللوائح والتعليمات المقررة في المنشأة والتصرف، انطلاقًا من حرصه على مصلحة المنشأة في أداء عمله على أكمل وجه. 2 بالإضافة- إلى أي مسؤوليات أخرى بموجب أنظمة ولوائح المنشأة؛ يعد مديرو الإدارات مسؤولين عن الآتي:"},{"index":2,"marker":"أ","text":"توضيح السياسات الخاصة بالعمل في المنشأة والقواعد، والإجراءات والتعليمات المتعلقة بتطبيقها والتأكّد، من فهمها من قبل العاملين الذين يعملون تحت إشرافهم."},{"index":3,"marker":"ب","text":"التأكّد من تقيد العاملين تحت إشرافهم بقواعد الانضباط والسلوك الوظيفي."},{"index":4,"marker":"ج","text":"رصد المخالفات التي تصدر عن العاملين الذين يعملون تحت إشرافهم واتباع، الإجراءات المعتمدة بشأنها."},{"index":5,"marker":"د","text":"أن يكونوا قدوة في الأداء والسلوك، وتحمل، المسؤولية أمام العاملين الذين، يعملون تحت إشرافهم. 3 بالإضافة- إلى أي مسؤوليات أخرى بموجب أنظمة ولوائح المنشأة؛ تعد إدارة الموارد البشرية مسؤولة عن الآتي:"},{"index":6,"marker":"أ","text":"توضيح الإجراءات المتعلقة بالجزاءات."},{"index":7,"marker":"ب","text":"تقديم المشورة حول تطبيق الجزاءات."},{"index":8,"marker":"ج","text":"التأكّد من تطبيق الجزاءات وفقًا، للقواعد والإجراءات والصلاحيات المعتمدة."},{"index":9,"marker":"د","text":"تطبيق القرارات التأديبية المتعلقة بالجزاءات وفقًا، للصلاحيات المعتمدة."}]','["اشراف","تحت","مسوولي","تاكد","ذين","تطبيق","متعلق","ولوايح","اجراء","مسوول"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-125','policy-doc-work-regulation',NULL,'التظلم',21,125,'مع عدم الإخلال بحق العامل في الالتجاء إلى الجهات','proposed','مع عدم الإخلال بحق العامل في الالتجاء إلى الجهات الإدارية، أو القضائية المختصة، أو الهيئات؛ يحق للعامل أن يتظلم إلى إدارة المنشأة من أي تصرف، أو إجراء، أو جزاء يتخذ في حقه من قبلها ويقدم، التظلم إلى إدارة المنشأة خلال ثلاثة أيام عمل من تاريخ العلم بالتصرف، أو الإجراء المتظلم منه ولا، يضار العامل من تقديم تظلمه ويخطر، العامل بنتيجة البت في تظلمه في، ميعاد لا يتجاوز خمسة أيام عمل من تاريخ تقديمه التظلم.','[{"index":1,"marker":null,"text":"مع عدم الإخلال بحق العامل في الالتجاء إلى الجهات الإدارية، أو القضائية المختصة، أو الهيئات؛ يحق للعامل أن يتظلم إلى إدارة المنشأة من أي تصرف، أو إجراء، أو جزاء يتخذ في حقه من قبلها ويقدم، التظلم إلى إدارة المنشأة خلال ثلاثة أيام عمل من تاريخ العلم بالتصرف، أو الإجراء المتظلم منه ولا، يضار العامل من تقديم تظلمه ويخطر، العامل بنتيجة البت في تظلمه في، ميعاد لا يتجاوز خمسة أيام عمل من تاريخ تقديمه التظلم."}]','["تظلم","التجاء","بحق","اخلال","جهات","عدم","تصرف","تقديم","اجراء","ادار"]','["clause_reflow"]','2025-04-25','replaced','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-126','policy-doc-work-regulation',NULL,'التظلم',21,126,'التظلم','proposed','تحل هذه المادة محل المادة المتعلقة بالتظلم. 1 لا- يجوز توقيع جزاء تأديبي على العامل الا بعد إبلاغه كتابة بما نسب اليه واستجوابه وتحقيق دفاعه وإثبات ذلك في محضر يودع في ملفه الخاص. ويجوز أن يكون الاستجواب شفاهه في المخالفات البسيطة التي لا يتعدى الجزاء المفروض على مرتكبها الإنذار او الغرامة باقتطاع ما لا يزيد على اجر يوم واحد على، أن يثبت ذلك في المحضر. للعامل-2 أن يتظلم من أي تصرف، أو إجراء، أو جزاء يتخذ في حقه من قبل المنشأة، ويقدم التظلم كتابة إلى الجهة المختصة بالمنشأة خلال تلاثين يوما - عدا أيام العطل الرسمية - من تاريخ إبلاغه بالقرار، أو الإحراء أو الجزاء المتظلم منه ولا، يضار العامل من تقديم تظلمه، ويخطر العامل بنتيجة البت في تظلمه، في ميعاد لا يتجاوز خمسة عشر -يوما عدا أيام العطل الرسمية - من تاريخ تقديمه التظلم فإن رفض تظلم العامل او لم يبت فيه كتابة خلال خمسة عشر يوما من تاريخ تقديمه التظلم كان له حق الاعتراض أمام المحاكم العمالية خلال تلاثين يوما - عدا أيام العطل الرسمية - من تاريخ رفض تظلمه أو انتهاء المدة المحددة للبت في التظلم أبهما أقرب.','[{"index":1,"marker":null,"text":"تحل هذه المادة محل المادة المتعلقة بالتظلم. 1 لا- يجوز توقيع جزاء تأديبي على العامل الا بعد إبلاغه كتابة بما نسب اليه واستجوابه وتحقيق دفاعه وإثبات ذلك في محضر يودع في ملفه الخاص. ويجوز أن يكون الاستجواب شفاهه في المخالفات البسيطة التي لا يتعدى الجزاء المفروض على مرتكبها الإنذار او الغرامة باقتطاع ما لا يزيد على اجر يوم واحد على، أن يثبت ذلك في المحضر. للعامل-2 أن يتظلم من أي تصرف، أو إجراء، أو جزاء يتخذ في حقه من قبل المنشأة، ويقدم التظلم كتابة إلى الجهة المختصة بالمنشأة خلال تلاثين يوما - عدا أيام العطل الرسمية - من تاريخ إبلاغه بالقرار، أو الإحراء أو الجزاء المتظلم منه ولا، يضار العامل من تقديم تظلمه، ويخطر العامل بنتيجة البت في تظلمه، في ميعاد لا يتجاوز خمسة عشر -يوما عدا أيام العطل الرسمية - من تاريخ تقديمه التظلم فإن رفض تظلم العامل او لم يبت فيه كتابة خلال خمسة عشر يوما من تاريخ تقديمه التظلم كان له حق الاعتراض أمام المحاكم العمالية خلال تلاثين يوما - عدا أيام العطل الرسمية - من تاريخ رفض تظلمه أو انتهاء المدة المحددة للبت في التظلم أبهما أقرب."}]','["تظلم","عدا","تلاث","عطل","جزاء","محضر","تقديم","يوما","رسم","رفض"]','[]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
INSERT INTO policy_articles(id,document_id,tenant_id,chapter,chapter_order,number,title,title_source,body,paragraphs,keywords,artifacts,effective_from,status,verification,revision,version,updated_at,created_at) VALUES('policy-article-127','policy-doc-work-regulation',NULL,'أحكام ختامية',22,127,'تنفذ أحكام هذه اللائحة في حق المنشأة اعتبارًا','proposed','تنفذ أحكام هذه اللائحة في حق المنشأة اعتبارًا من تاريخ إبلاغها باعتمادها؛ على أن تسري في حق العمال اعتبارًا من اليوم التالي لإعلانها.','[{"index":1,"marker":null,"text":"تنفذ أحكام هذه اللائحة في حق المنشأة اعتبارًا من تاريخ إبلاغها باعتمادها؛ على أن تسري في حق العمال اعتبارًا من اليوم التالي لإعلانها."}]','["تنفذ","اعتبارا","احكام","لايح","باعتماد","لاعل","تسر","ابلاغ","عمال","تال"]','["clause_reflow"]','2025-04-25','in_force','extracted',1,1,'2026-09-20T00:00:00.000Z','2026-09-20T00:00:00.000Z');
